   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('jus-03-gobierno', 'Tema 3. El Gobierno y la Administración. La Administración periférica del Estado') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-03-gobierno' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El Gobierno en la Constitución: funciones, composición, investidura, cese y responsabilidad (arts. 97-102 CE)"},{"n":"1.1","title":"La Administración Pública y el Consejo de Estado (arts. 103-107 CE)"},{"n":"2","title":"El Presidente del Gobierno (art. 99 CE; arts. 2, 12-13 Ley 50/1997)"},{"n":"3","title":"El Consejo de Ministros y las Comisiones Delegadas (arts. 5-6 y 18 Ley 50/1997)"},{"n":"4","title":"Órganos de colaboración y apoyo: Secretarios de Estado y Comisión General de Secretarios de Estado y Subsecretarios (arts. 7-8 y 15 Ley 50/1997)"},{"n":"5","title":"Organización administrativa: órganos superiores y directivos (art. 55 Ley 40/2015)"},{"n":"5.1","title":"Ministros, Secretarios de Estado, Subsecretarios y Directores generales (arts. 61-66 Ley 40/2015)"},{"n":"6","title":"La Administración periférica del Estado: Delegaciones y Subdelegaciones (arts. 69-71 Ley 40/2015)"},{"n":"6.1","title":"Delegados del Gobierno en las Comunidades Autónomas y Subdelegados en las provincias (arts. 72-75 Ley 40/2015)"},{"n":"7","title":"La Secretaría de Estado de Justicia: referencia en el RD 1451/2005 (art. 77)"}]'::jsonb, '["Art. 97 CE: «El Gobierno dirige la política interior y exterior, la Administración civil y militar y la defensa del Estado. Ejerce la función ejecutiva y la potestad reglamentaria de acuerdo con la Constitución y las leyes.»","Art. 98.1-2 CE: «El Gobierno se compone del Presidente, de los Vicepresidentes, en su caso, de los Ministros y de los demás miembros que establezca la ley. 2. El Presidente dirige la acción del Gobierno y coordina las funciones de los demás miembros del mismo, sin perjuicio de la competencia y responsabilidad directa de éstos en su gestión.»","Art. 101 CE: «El Gobierno cesa tras la celebración de elecciones generales, en los casos de pérdida de la confianza parlamentaria previstos en la Constitución, o por dimisión o fallecimiento de su Presidente. 2. El Gobierno cesante continuará en funciones hasta la toma de posesión del nuevo Gobierno.»","Art. 103.1 CE: «La Administración Pública sirve con objetividad los intereses generales y actúa de acuerdo con los principios de eficacia, jerarquía, descentralización, desconcentración y coordinación, con sometimiento pleno a la ley y al Derecho.»","Art. 107 CE: «El Consejo de Estado es el supremo órgano consultivo del Gobierno. Una ley orgánica regulará su composición y competencia.»","Art. 1.2-3 Ley 50/1997: «El Gobierno se compone del Presidente, del Vicepresidente o Vicepresidentes, en su caso, y de los Ministros. 3. Los miembros del Gobierno se reúnen en Consejo de Ministros y en Comisiones Delegadas del Gobierno.»","Art. 11 Ley 50/1997: «Para ser miembro del Gobierno se requiere ser español, mayor de edad, disfrutar de los derechos de sufragio activo y pasivo, así como no estar inhabilitado para ejercer empleo o cargo público por sentencia judicial firme»","Art. 5.3 Ley 50/1997: «Las deliberaciones del Consejo de Ministros serán secretas.»","Art. 7.1 Ley 50/1997: «Los Secretarios de Estado son órganos superiores de la Administración General del Estado, directamente responsables de la ejecución de la acción del Gobierno en un sector de actividad específica de un Departamento o de la Presidencia del Gobierno.»","Art. 55.1 Ley 40/2015: «La organización de la Administración General del Estado responde a los principios de división funcional en Departamentos ministeriales y de gestión territorial integrada en Delegaciones del Gobierno en las Comunidades Autónomas, salvo las excepciones previstas por esta Ley.»","Art. 63.1 Ley 40/2015: «Los Subsecretarios ostentan la representación ordinaria del Ministerio, dirigen los servicios comunes, ejercen las competencias correspondientes a dichos servicios comunes»","Art. 66.1 Ley 40/2015: «Los Directores generales son los titulares de los órganos directivos encargados de la gestión de una o varias áreas funcionalmente homogéneas del Ministerio.»","Art. 69.1 Ley 40/2015: «Existirá una Delegación del Gobierno en cada una de las Comunidades Autónomas.»","Art. 72.1 Ley 40/2015: «Los Delegados del Gobierno representan al Gobierno de la Nación en el territorio de la respectiva Comunidad Autónoma, sin perjuicio de la representación ordinaria del Estado en las mismas a través de sus respectivos Presidentes.»","Art. 74 Ley 40/2015: «En cada provincia y bajo la inmediata dependencia del Delegado del Gobierno en la respectiva Comunidad Autónoma, existirá un Subdelegado del Gobierno, con nivel de Subdirector General»","Art. 77 RD 1451/2005: «Será órgano competente para resolver los expedientes de rehabilitación en los supuestos señalados en el artículo anterior el Ministro de Justicia, correspondiendo su instrucción a la Secretaría de Estado de Justicia a través del titular de la Dirección General de Relaciones con la Administración de Justicia.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"El Gobierno en la Constitución: funciones y composición (arts. 97-98 CE)","blocks":[{"text":"El Gobierno dirige la política interior y exterior, la Administración civil y militar y la defensa del Estado, y ejerce la función ejecutiva y la potestad reglamentaria de acuerdo con la Constitución y las leyes (art. 97 CE, repetido en el art. 1.1 de la Ley 50/1997, del Gobierno). Según la Constitución se compone del Presidente, de los Vicepresidentes en su caso, de los Ministros y de los demás miembros que establezca la ley; la Ley del Gobierno concreta que lo forman el Presidente, el Vicepresidente o Vicepresidentes, en su caso, y los Ministros, que se reúnen en Consejo de Ministros y en Comisiones Delegadas.","refs":[{"ref":"Art. 97 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Gobierno dirige la política interior y exterior, la Administración civil y militar y la defensa del Estado. Ejerce la función ejecutiva y la potestad reglamentaria de acuerdo con la Constitución y las leyes."},{"ref":"Art. 98.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Gobierno se compone del Presidente, de los Vicepresidentes, en su caso, de los Ministros y de los demás miembros que establezca la ley."},{"ref":"Art. 1.2-3 LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"El Gobierno se compone del Presidente, del Vicepresidente o Vicepresidentes, en su caso, y de los Ministros. 3. Los miembros del Gobierno se reúnen en Consejo de Ministros y en Comisiones Delegadas del Gobierno."}]},{"text":"Los miembros del Gobierno no pueden ejercer otras funciones representativas que las del mandato parlamentario, ni otra función pública que no derive de su cargo, ni actividad profesional o mercantil alguna (art. 98.3 CE; art. 14 LG). Para serlo hay que ser español, mayor de edad, disfrutar del sufragio activo y pasivo, no estar inhabilitado por sentencia firme y reunir los requisitos de idoneidad de la Ley 3/2015, del alto cargo (art. 11 LG).","refs":[{"ref":"Art. 98.3 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Los miembros del Gobierno no podrán ejercer otras funciones representativas que las propias del mandato parlamentario, ni cualquier otra función pública que no derive de su cargo, ni actividad profesional o mercantil alguna."},{"ref":"Art. 11 LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"Para ser miembro del Gobierno se requiere ser español, mayor de edad, disfrutar de los derechos de sufragio activo y pasivo, así como no estar inhabilitado para ejercer empleo o cargo público por sentencia judicial firme"}]}]},{"n":"2","title":"Investidura, cese y responsabilidad del Gobierno (arts. 99-102 y 108-114 CE)","blocks":[{"text":"Tras cada renovación del Congreso, el Rey, previa consulta con los representantes de los grupos políticos y a través del Presidente del Congreso, propone un candidato, que expone su programa y pide la confianza de la Cámara. Si obtiene la mayoría absoluta, el Rey lo nombra; si no, se vota de nuevo 48 horas después y basta la mayoría simple. Si en dos meses desde la primera votación ningún candidato obtiene la confianza, el Rey disuelve ambas Cámaras y convoca elecciones con el refrendo del Presidente del Congreso (art. 99 CE). Los demás miembros los nombra y separa el Rey a propuesta del Presidente (art. 100 CE).","refs":[{"ref":"Art. 99.3 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Si el Congreso de los Diputados, por el voto de la mayoría absoluta de sus miembros, otorgare su confianza a dicho candidato, el Rey le nombrará Presidente. De no alcanzarse dicha mayoría, se someterá la misma propuesta a nueva votación cuarenta y ocho horas después de la anterior, y la confianza se entenderá otorgada si obtuviere la mayoría simple."},{"ref":"Art. 99.5 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Si transcurrido el plazo de dos meses, a partir de la primera votación de investidura, ningún candidato hubiere obtenido la confianza del Congreso, el Rey disolverá ambas Cámaras y convocará nuevas elecciones con el refrendo del Presidente del Congreso."},{"ref":"Art. 100 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Los demás miembros del Gobierno serán nombrados y separados por el Rey, a propuesta de su Presidente."}]},{"text":"El Gobierno cesa tras las elecciones generales, por pérdida de la confianza parlamentaria (cuestión de confianza perdida o moción de censura aprobada) y por dimisión o fallecimiento de su Presidente; el Gobierno cesante sigue en funciones hasta que toma posesión el nuevo (art. 101 CE). Responde solidariamente de su gestión política ante el Congreso (art. 108 CE). La moción de censura requiere mayoría absoluta, debe proponerla al menos la décima parte de los Diputados con un candidato alternativo y no se vota hasta pasados cinco días (art. 113 CE); la cuestión de confianza se gana por mayoría simple (art. 112 CE).","refs":[{"ref":"Art. 101 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Gobierno cesa tras la celebración de elecciones generales, en los casos de pérdida de la confianza parlamentaria previstos en la Constitución, o por dimisión o fallecimiento de su Presidente. 2. El Gobierno cesante continuará en funciones hasta la toma de posesión del nuevo Gobierno."},{"ref":"Art. 113 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Congreso de los Diputados puede exigir la responsabilidad política del Gobierno mediante la adopción por mayoría absoluta de la moción de censura. 2. La moción de censura deberá ser propuesta al menos por la décima parte de los Diputados, y habrá de incluir un candidato a la Presidencia del Gobierno. 3. La moción de censura no podrá ser votada hasta que transcurran cinco días desde su presentación."},{"ref":"Art. 112 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"La confianza se entenderá otorgada cuando vote a favor de la misma la mayoría simple de los Diputados."}]},{"text":"La responsabilidad criminal del Presidente y de los miembros del Gobierno se exige ante la Sala de lo Penal del Tribunal Supremo. Si la acusación es por traición o por delito contra la seguridad del Estado en el ejercicio de sus funciones, solo puede plantearla la cuarta parte de los Diputados con aprobación de la mayoría absoluta del Congreso, y en estos casos no cabe la prerrogativa real de gracia (art. 102 CE).","refs":[{"ref":"Art. 102 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"La responsabilidad criminal del Presidente y los demás miembros del Gobierno será exigible, en su caso, ante la Sala de lo Penal del Tribunal Supremo. 2. Si la acusación fuere por traición o por cualquier delito contra la seguridad del Estado en el ejercicio de sus funciones, sólo podrá ser planteada por iniciativa de la cuarta parte de los miembros del Congreso, y con la aprobación de la mayoría absoluta del mismo. 3. La prerrogativa real de gracia no será aplicable a ninguno de los supuestos del presente artículo."}]}]},{"n":"3","title":"La Administración Pública y el Consejo de Estado (arts. 103-107 CE)","blocks":[{"text":"La Administración sirve con objetividad los intereses generales y actúa conforme a los principios de eficacia, jerarquía, descentralización, desconcentración y coordinación, con sometimiento pleno a la ley y al Derecho. Sus órganos se crean, rigen y coordinan de acuerdo con la ley, y la ley regula el estatuto de los funcionarios y el acceso a la función pública según mérito y capacidad (art. 103 CE). Los Tribunales controlan la potestad reglamentaria y la legalidad de la actuación administrativa, y los particulares tienen derecho a indemnización por las lesiones causadas por el funcionamiento de los servicios públicos, salvo fuerza mayor (art. 106 CE).","refs":[{"ref":"Art. 103.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"La Administración Pública sirve con objetividad los intereses generales y actúa de acuerdo con los principios de eficacia, jerarquía, descentralización, desconcentración y coordinación, con sometimiento pleno a la ley y al Derecho."},{"ref":"Art. 106.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Los Tribunales controlan la potestad reglamentaria y la legalidad de la actuación administrativa, así como el sometimiento de ésta a los fines que la justifican."}]},{"text":"El Consejo de Estado es el supremo órgano consultivo del Gobierno; su composición y competencia las regula una ley orgánica (art. 107 CE). Por eso los reglamentos ejecutivos de las leyes los aprueba el Consejo de Ministros previo dictamen del Consejo de Estado (art. 5.1.h LG).","refs":[{"ref":"Art. 107 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Consejo de Estado es el supremo órgano consultivo del Gobierno. Una ley orgánica regulará su composición y competencia."},{"ref":"Art. 5.1 LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"h) Aprobar los reglamentos para el desarrollo y la ejecución de las leyes, previo dictamen del Consejo de Estado, así como las demás disposiciones reglamentarias que procedan."}]}]},{"n":"4","title":"El Presidente del Gobierno (art. 98.2 CE; arts. 2, 12 y 13 LG)","blocks":[{"text":"El Presidente dirige la acción del Gobierno y coordina las funciones de los demás miembros, sin perjuicio de la competencia y responsabilidad directa de los Ministros (art. 98.2 CE; art. 2.1 LG). Entre sus atribuciones (art. 2.2 LG) están representar al Gobierno; fijar el programa político y las directrices de la política interior y exterior; proponer al Rey, previa deliberación del Consejo de Ministros, la disolución de las Cámaras; plantear la cuestión de confianza; proponer la convocatoria de referéndum consultivo, previa autorización del Congreso; dirigir la política de defensa; convocar, presidir y fijar el orden del día del Consejo de Ministros, e interponer el recurso de inconstitucionalidad.","refs":[{"ref":"Art. 2.2 LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"a) Representar al Gobierno. b) Establecer el programa político del Gobierno y determinar las directrices de la política interior y exterior y velar por su cumplimiento. c) Proponer al Rey, previa deliberación del Consejo de Ministros, la disolución del Congreso, del Senado o de las Cortes Generales."},{"ref":"Art. 2.2 LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"g) Convocar, presidir y fijar el orden del día de las reuniones del Consejo de Ministros, sin perjuicio de lo previsto en el artículo 62.g) de la Constitución."},{"ref":"Art. 2.2 LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"i) Interponer el recurso de inconstitucionalidad."}]},{"text":"También le corresponde crear, modificar y suprimir por Real Decreto los Departamentos Ministeriales y las Secretarías de Estado, aprobar la estructura de la Presidencia del Gobierno, proponer al Rey el nombramiento y separación de Vicepresidentes y Ministros, resolver los conflictos de atribuciones entre Ministerios e impartir instrucciones a los demás miembros del Gobierno (art. 2.2.j-m LG; art. 57.3 Ley 40/2015).","refs":[{"ref":"Art. 2.2 LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"j) Crear, modificar y suprimir, por Real Decreto, los Departamentos Ministeriales, así como las Secretarías de Estado"},{"ref":"Art. 2.2 LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"k) Proponer al Rey el nombramiento y separación de los Vicepresidentes y de los Ministros. l) Resolver los conflictos de atribuciones que puedan surgir entre los diferentes Ministerios. m) Impartir instrucciones a los demás miembros del Gobierno."},{"ref":"Art. 57.3 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"La determinación del número, la denominación y el ámbito de competencia respectivo de los Ministerios y las Secretarías de Estado se establecen mediante Real Decreto del Presidente del Gobierno."}]},{"text":"Vicepresidentes y Ministros son nombrados y separados por el Rey a propuesta del Presidente; en su nombramiento debe garantizarse la presencia equilibrada, de modo que cada sexo suponga al menos el 40 % en su conjunto (art. 12 LG). En caso de vacante, ausencia o enfermedad del Presidente, le suplen los Vicepresidentes por su orden de prelación y, en su defecto, los Ministros por el orden de precedencia de los Departamentos (art. 13.1 LG). La suplencia de los Ministros la fija un Real Decreto del Presidente y recae siempre en otro miembro del Gobierno (art. 13.2 LG).","refs":[{"ref":"Art. 12.2 bis LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"En el nombramiento de las personas titulares de las Vicepresidencias y los Ministerios se garantizará el principio de presencia equilibrada de mujeres y hombres, de forma que cada uno de los sexos suponga como mínimo el cuarenta por ciento en su conjunto."},{"ref":"Art. 13.1 LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"En los casos de vacante, ausencia o enfermedad, las funciones del Presidente del Gobierno serán asumidas por los Vicepresidentes, de acuerdo con el correspondiente orden de prelación, y, en defecto de ellos, por los Ministros, según el orden de precedencia de los Departamentos."},{"ref":"Art. 13.2 LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"La suplencia de los Ministros, para el despacho ordinario de los asuntos de su competencia, será determinada por Real Decreto del Presidente del Gobierno, debiendo recaer, en todo caso, en otro miembro del Gobierno."}]}]},{"n":"5","title":"El Consejo de Ministros y las Comisiones Delegadas (arts. 5, 6 y 18 LG)","blocks":[{"text":"El Consejo de Ministros es el órgano colegiado del Gobierno. Le corresponde, entre otras funciones, aprobar los proyectos de ley y el de Presupuestos Generales del Estado, los Reales Decretos-leyes y los Reales Decretos Legislativos; acordar la negociación y firma de tratados; declarar los estados de alarma y de excepción y proponer al Congreso el de sitio; aprobar los reglamentos de desarrollo de las leyes, y crear, modificar y suprimir los órganos directivos de los Ministerios (art. 5.1 LG). Pueden asistir los Secretarios de Estado y, excepcionalmente, otros altos cargos convocados; sus deliberaciones son secretas (art. 5.2-3 LG).","refs":[{"ref":"Art. 5.1 LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"a) Aprobar los proyectos de ley y su remisión al Congreso de los Diputados o, en su caso, al Senado. b) Aprobar el Proyecto de Ley de Presupuestos Generales del Estado. c) Aprobar los Reales Decretos-leyes y los Reales Decretos Legislativos."},{"ref":"Art. 5.1 LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"f) Declarar los estados de alarma y de excepción y proponer al Congreso de los Diputados la declaración del estado de sitio."},{"ref":"Art. 5.2-3 LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"A las reuniones del Consejo de Ministros podrán asistir los Secretarios de Estado y excepcionalmente otros altos cargos, cuando sean convocados para ello, sin perjuicio de lo dispuesto en los tratados internacionales válidamente celebrados por España. 3. Las deliberaciones del Consejo de Ministros serán secretas."}]},{"text":"El Presidente convoca y preside el Consejo de Ministros y fija su orden del día; actúa como Secretario el Ministro de la Presidencia. Las reuniones pueden ser decisorias o deliberantes, y del acta solo constan tiempo y lugar, asistentes, acuerdos adoptados e informes presentados (art. 18 LG). Recuerda que el Rey puede presidir el Consejo cuando lo estime oportuno, a petición del Presidente (art. 62.g CE).","refs":[{"ref":"Art. 18 LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"El Presidente del Gobierno convoca y preside las reuniones del Consejo de Ministros, actuando como Secretario el Ministro de la Presidencia. 2. Las reuniones del Consejo de Ministros podrán tener carácter decisorio o deliberante."},{"ref":"Art. 18.4 LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"De las sesiones del Consejo de Ministros se levantará acta en la que figurarán, exclusivamente, las circunstancias relativas al tiempo y lugar de su celebración, la relación de asistentes, los acuerdos adoptados y los informes presentados."}]},{"text":"Las Comisiones Delegadas del Gobierno se crean, modifican y suprimen por Real Decreto del Consejo de Ministros a propuesta del Presidente. Examinan cuestiones generales que afectan a varios Ministerios, preparan propuestas conjuntas para el Consejo de Ministros y resuelven asuntos interministeriales que no requieran elevarse a él; sus deliberaciones también son secretas (art. 6 LG).","refs":[{"ref":"Art. 6.1 LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"La creación, modificación y supresión de las Comisiones Delegadas del Gobierno será acordada por el Consejo de Ministros mediante Real Decreto, a propuesta del Presidente del Gobierno."},{"ref":"Art. 6.5 LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"Las deliberaciones de las Comisiones Delegadas del Gobierno serán secretas."}]}]},{"n":"6","title":"Órganos de colaboración y apoyo: Secretarios de Estado y Comisión General (arts. 7-9 y 15 LG)","blocks":[{"text":"Los Secretarios de Estado son órganos superiores de la Administración General del Estado, directamente responsables de ejecutar la acción del Gobierno en un sector específico de un Departamento o de la Presidencia; actúan bajo la dirección del Ministro o, si están adscritos a la Presidencia, del Presidente (art. 7 LG). Son nombrados y separados por Real Decreto del Consejo de Ministros a propuesta del Presidente o del Ministro del que dependan (art. 15.1 LG).","refs":[{"ref":"Art. 7.1 LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"Los Secretarios de Estado son órganos superiores de la Administración General del Estado, directamente responsables de la ejecución de la acción del Gobierno en un sector de actividad específica de un Departamento o de la Presidencia del Gobierno."},{"ref":"Art. 15.1 LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"Los Secretarios de Estado son nombrados y separados por Real Decreto del Consejo de Ministros, aprobado a propuesta del Presidente del Gobierno o del miembro del Gobierno a cuyo Departamento pertenezcan."}]},{"text":"La Comisión General de Secretarios de Estado y Subsecretarios la integran los Secretarios de Estado y los Subsecretarios, con asistencia del Abogado General del Estado. La preside un Vicepresidente o, en su defecto, el Ministro de la Presidencia; su Secretario es el Subsecretario de la Presidencia (sustituido por el Director del Secretariado del Gobierno). Sus deliberaciones son reservadas, nunca adopta acuerdos por delegación del Gobierno y examina los asuntos que van al Consejo de Ministros, salvo nombramientos, ceses, ascensos de oficiales generales y asuntos urgentes (art. 8 LG).","refs":[{"ref":"Art. 8.2 LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"La Presidencia de la Comisión General de Secretarios de Estado y Subsecretarios corresponde a un Vicepresidente del Gobierno o, en su defecto, al Ministro de la Presidencia."},{"ref":"Art. 8.3-4 LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"La Secretaría de la Comisión General de Secretarios de Estado y Subsecretarios será ejercida por el Subsecretario de la Presidencia. En caso de ausencia, vacante o enfermedad, actuará como Secretario el Director del Secretariado del Gobierno. 4. Las deliberaciones de la Comisión General de Secretarios de Estado y Subsecretarios serán reservadas. En ningún caso la Comisión podrá adoptar decisiones o acuerdos por delegación del Gobierno."}]},{"text":"El Secretariado del Gobierno es el órgano de apoyo del Consejo de Ministros, de las Comisiones Delegadas y de la Comisión General: asiste al Ministro-Secretario, remite las convocatorias, custodia actas y vela por la correcta publicación en el BOE de las normas del Gobierno; se integra en el Ministerio de la Presidencia (art. 9 LG). Los Gabinetes son órganos de apoyo político y técnico que no pueden dictar actos propios de los órganos administrativos (art. 10 LG).","refs":[{"ref":"Art. 9.1 LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"El Secretariado del Gobierno, como órgano de apoyo del Consejo de Ministros, de las Comisiones Delegadas del Gobierno y de la Comisión General de Secretarios de Estado y Subsecretarios, ejercerá las siguientes funciones: a) La asistencia al Ministro-Secretario del Consejo de Ministros."},{"ref":"Art. 10.1 LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"Los Gabinetes son órganos de apoyo político y técnico del Presidente del Gobierno, de los Vicepresidentes, de los Ministros y de los Secretarios de Estado."}]}]},{"n":"7","title":"Organización administrativa: órganos superiores y directivos (arts. 55, 58 y 60 Ley 40/2015)","blocks":[{"text":"La Administración General del Estado se organiza según los principios de división funcional en Departamentos ministeriales y de gestión territorial integrada en Delegaciones del Gobierno; comprende la Organización Central, la Territorial y la Administración en el exterior (art. 55.1-2 Ley 40/2015). En la organización central son órganos superiores los Ministros y los Secretarios de Estado, y órganos directivos los Subsecretarios y Secretarios generales, los Secretarios generales técnicos y Directores generales y los Subdirectores generales (art. 55.3).","refs":[{"ref":"Art. 55.1 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"La organización de la Administración General del Estado responde a los principios de división funcional en Departamentos ministeriales y de gestión territorial integrada en Delegaciones del Gobierno en las Comunidades Autónomas, salvo las excepciones previstas por esta Ley."},{"ref":"Art. 55.3 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"a) Órganos superiores: 1.º Los Ministros. 2.º Los Secretarios de Estado. b) Órganos directivos: 1.º Los Subsecretarios y Secretarios generales. 2.º Los Secretarios generales técnicos y Directores generales. 3.º Los Subdirectores generales."}]},{"text":"En la organización territorial son órganos directivos los Delegados del Gobierno (rango de Subsecretario) y los Subdelegados (nivel de Subdirector general); en el exterior, los embajadores y representantes permanentes. Todos los órganos superiores y directivos son altos cargos, salvo los Subdirectores generales y asimilados (art. 55.4-6). Cada Ministerio cuenta siempre con una Subsecretaría y, dependiendo de ella, una Secretaría General Técnica; las Direcciones Generales se organizan en Subdirecciones Generales (art. 58). Jerárquicamente, el Ministro es superior directo de Secretarios de Estado y Subsecretarios, y los órganos directivos se ordenan así: Subsecretario, Director general y Subdirector general (art. 60).","refs":[{"ref":"Art. 55.4 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"En la organización territorial de la Administración General del Estado son órganos directivos tanto los Delegados del Gobierno en las Comunidades Autónomas, que tendrán rango de Subsecretario, como los Subdelegados del Gobierno en las provincias, los cuales tendrán nivel de Subdirector general."},{"ref":"Art. 55.6 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Los órganos superiores y directivos tienen además la condición de alto cargo, excepto los Subdirectores generales y asimilados"},{"ref":"Art. 58.2 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Los Ministerios contarán, en todo caso, con una Subsecretaría, y dependiendo de ella una Secretaría General Técnica, para la gestión de los servicios comunes previstos en este Título."},{"ref":"Art. 60 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Los Ministros son los jefes superiores del Departamento y superiores jerárquicos directos de los Secretarios de Estado y Subsecretarios. 2. Los órganos directivos dependen de alguno de los anteriores y se ordenan jerárquicamente entre sí de la siguiente forma: Subsecretario, Director general y Subdirector general."}]},{"text":"Los titulares de las Secretarías de Estado y de los órganos directivos se nombran con representación equilibrada: ninguno de los sexos puede superar el 60 % ni bajar del 40 % en cada departamento (art. 55 bis).","refs":[{"ref":"Art. 55 bis LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"de tal manera que las personas de cada sexo no superen el sesenta por ciento ni sean menos del cuarenta por ciento en el ámbito de cada departamento ministerial."}]}]},{"n":"8","title":"Ministros, Secretarios de Estado, Subsecretarios y Directores generales (arts. 61-67 Ley 40/2015)","blocks":[{"text":"Los Ministros dirigen los sectores de actividad de su Ministerio: ejercen la potestad reglamentaria en sus materias, fijan objetivos y aprueban planes, nombran y separan a los titulares de órganos directivos cuando no corresponda al Consejo de Ministros, resuelven conflictos de atribuciones, celebran contratos y convenios e imponen la sanción de separación del servicio por faltas muy graves (art. 61). Los Secretarios de Estado dirigen y coordinan las Secretarías y Direcciones Generales a su cargo, responden ante el Ministro y, entre otras competencias, nombran y separan a los Subdirectores Generales de la Secretaría de Estado (art. 62).","refs":[{"ref":"Art. 61 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"a) Ejercer la potestad reglamentaria en las materias propias de su Departamento."},{"ref":"Art. 61 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"s) Imponer la sanción de separación del servicio por faltas muy graves."},{"ref":"Art. 62.2 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"c) Nombrar y separar a los Subdirectores Generales de la Secretaría de Estado."}]},{"text":"Los Subsecretarios ostentan la representación ordinaria del Ministerio y dirigen los servicios comunes; desempeñan la jefatura superior de todo el personal del Departamento, convocan y resuelven las pruebas selectivas y los concursos, y ejercen la potestad disciplinaria por faltas graves o muy graves, salvo la separación del servicio. Se nombran y separan por Real Decreto del Consejo de Ministros a propuesta del Ministro, entre funcionarios de carrera del Subgrupo A1 (art. 63). Los Secretarios generales tienen categoría de Subsecretario y los Secretarios generales técnicos, de Director general, con competencias en producción normativa, asistencia jurídica y publicaciones (arts. 60, 64 y 65).","refs":[{"ref":"Art. 63.1 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Los Subsecretarios ostentan la representación ordinaria del Ministerio, dirigen los servicios comunes, ejercen las competencias correspondientes a dichos servicios comunes"},{"ref":"Art. 63.1 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"f) Desempeñar la jefatura superior de todo el personal del Departamento."},{"ref":"Art. 63.1 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"ñ) Ejercer la potestad disciplinaria del personal del Departamento por faltas graves o muy graves, salvo la separación del servicio."},{"ref":"Art. 63.3 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Los Subsecretarios serán nombrados y separados por Real Decreto del Consejo de Ministros a propuesta del titular del Ministerio."},{"ref":"Art. 65.1 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"las relativas a producción normativa, asistencia jurídica y publicaciones."}]},{"text":"Los Directores generales son los titulares de los órganos directivos encargados de la gestión de una o varias áreas funcionalmente homogéneas del Ministerio; proponen y dirigen los proyectos de su Dirección y supervisan su gestión ordinaria. Se nombran por Real Decreto del Consejo de Ministros a propuesta del Ministro o del Presidente, en principio entre funcionarios del Subgrupo A1, salvo excepción motivada en el Real Decreto de estructura (art. 66). Los Subdirectores generales son nombrados y cesados por el Ministro, Secretario de Estado o Subsecretario del que dependan, entre funcionarios del Subgrupo A1 (art. 67).","refs":[{"ref":"Art. 66.1 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Los Directores generales son los titulares de los órganos directivos encargados de la gestión de una o varias áreas funcionalmente homogéneas del Ministerio."},{"ref":"Art. 66.2 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Los Directores generales serán nombrados y separados por Real Decreto del Consejo de Ministros, a propuesta del titular del Departamento o del Presidente del Gobierno."},{"ref":"Art. 67.2 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Los Subdirectores generales serán nombrados, respetando los principios de igualdad, mérito y capacidad, y cesados por el Ministro, Secretario de Estado o Subsecretario del que dependan."}]}]},{"n":"9","title":"La Administración periférica del Estado: Delegaciones y Subdelegaciones (arts. 69-71 Ley 40/2015; art. 154 CE)","blocks":[{"text":"La Constitución prevé que un Delegado nombrado por el Gobierno dirija la Administración del Estado en el territorio de cada Comunidad Autónoma y la coordine con la administración autonómica (art. 154 CE). La Ley 40/2015 establece una Delegación del Gobierno en cada Comunidad Autónoma, con sede donde radique el Consejo de Gobierno autonómico, salvo que el Consejo de Ministros acuerde otra o lo disponga el Estatuto. Las Delegaciones están adscritas orgánicamente al Ministerio de Hacienda y Administraciones Públicas (denominación del texto de la ley; la adscripción real depende de la estructura ministerial vigente).","refs":[{"ref":"Art. 154 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Un Delegado nombrado por el Gobierno dirigirá la Administración del Estado en el territorio de la Comunidad Autónoma y la coordinará, cuando proceda, con la administración propia de la Comunidad."},{"ref":"Art. 69.1-3 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Existirá una Delegación del Gobierno en cada una de las Comunidades Autónomas. 2. Las Delegaciones del Gobierno tendrán su sede en la localidad donde radique el Consejo de Gobierno de la Comunidad Autónoma, salvo que el Consejo de Ministros acuerde ubicarla en otra distinta y sin perjuicio de lo que disponga expresamente el Estatuto de Autonomía. 3. Las Delegaciones del Gobierno están adscritas orgánicamente al Ministerio de Hacienda y Administraciones Públicas."}]},{"text":"En cada provincia de las Comunidades pluriprovinciales hay un Subdelegado del Gobierno, bajo la inmediata dependencia del Delegado; en las uniprovinciales pueden crearse Subdelegaciones por Real Decreto si lo justifican la población, el volumen de gestión u otras singularidades (art. 69.4). En determinadas islas existe un Director Insular, nombrado por el Delegado por libre designación (art. 70). Los servicios territoriales pueden ser integrados en la Delegación (dependen del Delegado o Subdelegado a través de la Secretaría General) o no integrados (dependen del órgano central competente) (art. 71).","refs":[{"ref":"Art. 69.4 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"En cada una de las provincias de las Comunidades Autónomas pluriprovinciales, existirá un Subdelegado del Gobierno, que estará bajo la inmediata dependencia del Delegado del Gobierno."},{"ref":"Art. 70 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Reglamentariamente se determinarán las islas en las que existirá un Director Insular de la Administración General del Estado"},{"ref":"Art. 71.1 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"se organizarán atendiendo al mejor cumplimiento de sus fines, en servicios integrados y no integrados en las Delegaciones del Gobierno."}]}]},{"n":"10","title":"Delegados del Gobierno en las Comunidades Autónomas y Subdelegados en las provincias (arts. 72-75 Ley 40/2015)","blocks":[{"text":"Los Delegados del Gobierno representan al Gobierno de la Nación en el territorio de la Comunidad, sin perjuicio de la representación ordinaria del Estado que corresponde a los Presidentes autonómicos. Dirigen y supervisan la Administración General del Estado en ese territorio. Son órganos directivos con rango de Subsecretario, dependen orgánicamente del Presidente del Gobierno y funcionalmente del Ministerio competente por razón de la materia, y se nombran y separan por Real Decreto del Consejo de Ministros a propuesta del Presidente. Les suple el Subdelegado que designen (art. 72).","refs":[{"ref":"Art. 72.1 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Los Delegados del Gobierno representan al Gobierno de la Nación en el territorio de la respectiva Comunidad Autónoma, sin perjuicio de la representación ordinaria del Estado en las mismas a través de sus respectivos Presidentes."},{"ref":"Art. 72.3-4 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"3. Los Delegados del Gobierno son órganos directivos con rango de Subsecretario que dependen orgánicamente del Presidente del Gobierno y funcionalmente del Ministerio competente por razón de la materia. 4. Los Delegados del Gobierno serán nombrados y separados por Real Decreto del Consejo de Ministros, a propuesta del Presidente del Gobierno."}]},{"text":"Entre sus competencias (art. 73) figuran nombrar a los Subdelegados y Directores Insulares, coordinar la información sobre la acción del Gobierno, elevar al Gobierno un informe anual sobre los servicios públicos estatales en la Comunidad, mantener la cooperación con la Comunidad y las Entidades Locales, resolver recursos contra actos de órganos de la Delegación y velar por las competencias del Estado. Además ejercen la potestad sancionadora y expropiatoria, y protegen el libre ejercicio de derechos y libertades y la seguridad ciudadana, con la jefatura de las Fuerzas y Cuerpos de Seguridad del Estado bajo la dependencia funcional del Ministerio del Interior.","refs":[{"ref":"Art. 73.1 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"2.º Nombrar a los Subdelegados del Gobierno en las provincias de su ámbito de actuación y, en su caso, a los Directores Insulares, y como superior jerárquico, dirigir y coordinar su actividad."},{"ref":"Art. 73.3 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Corresponde a los Delegados del Gobierno proteger el libre ejercicio de los derechos y libertades y garantizar la seguridad ciudadana, a través de los Subdelegados del Gobierno y de las Fuerzas y Cuerpos de seguridad del Estado, cuya jefatura corresponderá al Delegado del Gobierno"}]},{"text":"El Subdelegado del Gobierno, con nivel de Subdirector General, lo nombra el Delegado por libre designación entre funcionarios de carrera del Estado, de las Comunidades Autónomas o de las Entidades Locales del Subgrupo A1; en las Comunidades uniprovinciales sin Subdelegado, sus funciones las asume el Delegado (art. 74). Le corresponde la cooperación con la Comunidad y las Entidades Locales en la provincia, dirigir las Fuerzas y Cuerpos de Seguridad del Estado en la provincia, dirigir y coordinar la protección civil, dirigir los servicios integrados e inspeccionar los no integrados, y ejercer la potestad sancionadora (art. 75).","refs":[{"ref":"Art. 74 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"En cada provincia y bajo la inmediata dependencia del Delegado del Gobierno en la respectiva Comunidad Autónoma, existirá un Subdelegado del Gobierno, con nivel de Subdirector General, que será nombrado por aquél mediante el procedimiento de libre designación entre funcionarios de carrera del Estado, de las Comunidades Autónomas o de las Entidades Locales, pertenecientes a Cuerpos o Escalas clasificados como Subgrupo A1."},{"ref":"Art. 75 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"b) Proteger el libre ejercicio de los derechos y libertades, garantizando la seguridad ciudadana, todo ello dentro de las competencias estatales en la materia. A estos efectos, dirigirá las Fuerzas y Cuerpos de Seguridad del Estado en la provincia. c) Dirigir y coordinar la protección civil en el ámbito de la provincia."}]}]},{"n":"11","title":"La Secretaría de Estado de Justicia: principales competencias","blocks":[{"text":"Aviso de fuentes: la carpeta no contiene el Real Decreto de estructura orgánica básica del Ministerio de Justicia, que es la norma que enumera las competencias de la Secretaría de Estado de Justicia; por eso este apartado solo recoge lo que dicen de ella las normas de la Administración de Justicia disponibles. Como todo Secretario de Estado, su titular es órgano superior y dirige las Direcciones Generales que dependen de él (art. 62.2 Ley 40/2015). En materia de personal, el Reglamento de Ingreso (RD 1451/2005) atribuye al Ministro de Justicia la resolución de los expedientes de rehabilitación de los funcionarios de Justicia, cuya instrucción corresponde a la Secretaría de Estado de Justicia a través del titular de la Dirección General de Relaciones con la Administración de Justicia.","refs":[{"ref":"Art. 62.2 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Los Secretarios de Estado dirigen y coordinan las Secretarías y las Direcciones Generales situadas bajo su dependencia, y responden ante el Ministro de la ejecución de los objetivos fijados para la Secretaría de Estado."},{"ref":"Art. 77 RD 1451/2005","law":"RD 1451/2005","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2005-21264","quote":"Será órgano competente para resolver los expedientes de rehabilitación en los supuestos señalados en el artículo anterior el Ministro de Justicia, correspondiendo su instrucción a la Secretaría de Estado de Justicia a través del titular de la Dirección General de Relaciones con la Administración de Justicia."}]},{"text":"En materia de archivos judiciales, las Juntas de Expurgo adscritas al Ministerio de Justicia lo están a través de la Secretaría de Estado de Justicia; tienen su sede donde radique la presidencia del Tribunal Superior de Justicia y las preside un magistrado designado por su Presidente (RD 937/2003). La propia Secretaría de Estado de Justicia fue la que publicó, por Resolución de 28 de octubre de 2005, el Plan de Transparencia Judicial.","refs":[{"ref":"Art. 14.3 RD 937/2003","law":"RD 937/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-15237","quote":"Las Juntas de Expurgo adscritas al Ministerio de Justicia a través de la Secretaría de Estado de Justicia tendrán su sede donde radique la presidencia del Tribunal Superior de Justicia y estarán presididas por un magistrado designado por el Presidente del Tribunal Superior de Justicia"},{"ref":"Título de la Resolución","law":"Plan de Transparencia Judicial","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2005-17951","quote":"Resolución de 28 de octubre de 2005, de la Secretaría de Estado de Justicia, por la que se dispone la publicación del Acuerdo de Consejo de Ministros de 21 de octubre de 2005, por el que se aprueba el Plan de Transparencia Judicial"}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Investidura: mayoría absoluta en la primera votación; mayoría simple en la segunda, 48 horas después; si en dos meses no hay investidura, disolución con refrendo del Presidente del Congreso.","refs":[{"ref":"Art. 99.3 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"se someterá la misma propuesta a nueva votación cuarenta y ocho horas después de la anterior, y la confianza se entenderá otorgada si obtuviere la mayoría simple."}]},{"text":"Acusación por traición o delito contra la seguridad del Estado: iniciativa de la cuarta parte del Congreso y aprobación por mayoría absoluta.","refs":[{"ref":"Art. 102.2 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"sólo podrá ser planteada por iniciativa de la cuarta parte de los miembros del Congreso, y con la aprobación de la mayoría absoluta del mismo."}]},{"text":"Supremo órgano consultivo del Gobierno: el Consejo de Estado.","refs":[{"ref":"Art. 107 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Consejo de Estado es el supremo órgano consultivo del Gobierno."}]},{"text":"Secretario del Consejo de Ministros: el Ministro de la Presidencia. Secretario de la Comisión General de Secretarios de Estado y Subsecretarios: el Subsecretario de la Presidencia.","refs":[{"ref":"Art. 8.3 LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"La Secretaría de la Comisión General de Secretarios de Estado y Subsecretarios será ejercida por el Subsecretario de la Presidencia."}]},{"text":"Deliberaciones: secretas en el Consejo de Ministros y en las Comisiones Delegadas; reservadas en la Comisión General de Secretarios de Estado y Subsecretarios.","refs":[{"ref":"Art. 5.3 LG","law":"Ley 50/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336","quote":"Las deliberaciones del Consejo de Ministros serán secretas."}]},{"text":"Órganos superiores: Ministros y Secretarios de Estado. Todos los demás de la organización central (Subsecretarios, Secretarios generales, Secretarios generales técnicos, Directores generales, Subdirectores generales) son directivos.","refs":[{"ref":"Art. 55.3 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"a) Órganos superiores: 1.º Los Ministros. 2.º Los Secretarios de Estado."}]},{"text":"Nombramientos: Subsecretarios, Secretarios generales técnicos y Directores generales, por Real Decreto del Consejo de Ministros; Subdirectores generales, por el Ministro, Secretario de Estado o Subsecretario del que dependan.","refs":[{"ref":"Art. 63.3 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Los Subsecretarios serán nombrados y separados por Real Decreto del Consejo de Ministros a propuesta del titular del Ministerio."}]},{"text":"Delegado del Gobierno: rango de Subsecretario y nombramiento por Real Decreto del Consejo de Ministros a propuesta del Presidente. Subdelegado: nivel de Subdirector General y nombramiento por el Delegado (libre designación, Subgrupo A1).","refs":[{"ref":"Art. 72.3 LRJSP","law":"Ley 40/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566","quote":"Los Delegados del Gobierno son órganos directivos con rango de Subsecretario"}]},{"text":"Rehabilitación de funcionarios de Justicia: la resuelve el Ministro de Justicia y la instruye la Secretaría de Estado de Justicia (a través de la DG de Relaciones con la Administración de Justicia).","refs":[{"ref":"Art. 77 RD 1451/2005","law":"RD 1451/2005","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2005-21264","quote":"correspondiendo su instrucción a la Secretaría de Estado de Justicia a través del titular de la Dirección General de Relaciones con la Administración de Justicia."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566', null, null, null, 'Otras normas citadas: CE (https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229), Ley 50/1997 (https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336), RD 1451/2005 (https://www.boe.es/buscar/act.php?id=BOE-A-2005-21264)'
  from public.topics t where t.slug = 'jus-03-gobierno'
