   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Constitución Española (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('jus-06-poder-judicial', 'Tema 6. El Poder Judicial, el CGPJ, la independencia judicial y el Ministerio Fiscal') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-06-poder-judicial' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El Poder Judicial en la Constitución (arts. 117-127 CE)"},{"n":"1.1","title":"Principios: unidad jurisdiccional, exclusividad y prohibición de Tribunales de excepción (art. 117 CE)"},{"n":"2","title":"El Poder Judicial y la potestad jurisdiccional en la LOPJ (arts. 1-20 LOPJ)"},{"n":"2.1","title":"La jurisdicción y los órdenes jurisdiccionales (arts. 3-9 LOPJ)"},{"n":"3","title":"El Consejo General del Poder Judicial: composición (art. 122 CE; arts. 566-571 LOPJ)"},{"n":"3.1","title":"Atribuciones (arts. 558-561 LOPJ)"},{"n":"3.2","title":"Órganos: Presidencia, Pleno y Comisiones (arts. 585-603 LOPJ)"},{"n":"4","title":"Jueces y Magistrados: la Carrera Judicial y el acceso (arts. 298-302 LOPJ)"},{"n":"5","title":"La independencia judicial: inamovilidad, incompatibilidades, inmunidad y asociación (arts. 12-15 y 378-401 LOPJ)"},{"n":"6","title":"El Ministerio Fiscal: naturaleza y funciones (art. 124 CE; arts. 1-3 EOMF)"},{"n":"6.1","title":"Organización: órganos, Consejo Fiscal y Fiscal General del Estado (arts. 12-14, 22 y 29-31 EOMF)"}]'::jsonb, '["Art. 117.1 CE: «La justicia emana del pueblo y se administra en nombre del Rey por Jueces y Magistrados integrantes del poder judicial, independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley.»","Art. 117.3 CE: «El ejercicio de la potestad jurisdiccional en todo tipo de procesos, juzgando y haciendo ejecutar lo juzgado, corresponde exclusivamente a los Juzgados y Tribunales determinados por las leyes, según las normas de competencia y procedimiento que las mismas establezcan.»","Art. 117.5-6 CE: «El principio de unidad jurisdiccional es la base de la organización y funcionamiento de los Tribunales. […] 6. Se prohíben los Tribunales de excepción.»","Art. 3.1 LOPJ: «La jurisdicción es única y se ejerce por los jueces, las juezas y los Tribunales previstos en esta ley orgánica, sin perjuicio de las potestades jurisdiccionales reconocidas por la Constitución a otros órganos.»","Art. 122.2 CE: «El Consejo General del Poder Judicial es el órgano de gobierno del mismo. La ley orgánica establecerá su estatuto y el régimen de incompatibilidades de sus miembros y sus funciones, en particular en materia de nombramientos, ascensos, inspección y régimen disciplinario.»","Art. 122.3 CE: «El Consejo General del Poder Judicial estará integrado por el Presidente del Tribunal Supremo, que lo presidirá, y por veinte miembros nombrados por el Rey por un período de cinco años. De éstos, doce entre Jueces y Magistrados de todas las categorías judiciales, en los términos que establezca la ley orgánica; cuatro a propuesta del Congreso de los Diputados, y cuatro a propuesta del Senado, elegidos en ambos casos por mayoría de tres quintos de sus miembros, entre abogados y otros juristas, todos ellos de reconocida competencia y con más de quince años de ejercicio en su profesión.»","Art. 567.2 LOPJ: «Cada una de las Cámaras elegirá, por mayoría de tres quintos de sus miembros, a diez Vocales, cuatro entre juristas de reconocida competencia con más de quince años de ejercicio en su profesión y seis correspondientes al turno judicial, conforme a lo previsto en el Capítulo II del presente Título.»","Art. 595.2 LOPJ: «En el Consejo General del Poder Judicial existirán las siguientes Comisiones: Permanente, de Calificación, Disciplinaria, de Asuntos Económicos, de Igualdad y de Supervisión y Control de Protección de Datos.»","Art. 299.1 LOPJ: «La Carrera Judicial consta de tres categorías: – Magistrado del Tribunal Supremo. – Magistrado. – Juez.»","Art. 301.3 LOPJ: «El ingreso en la Carrera Judicial por la categoría de juez se producirá mediante la superación de oposición libre y de un curso teórico y práctico de selección realizado en la Escuela Judicial.»","Art. 12.1 LOPJ: «En el ejercicio de la potestad jurisdiccional, los Jueces y Magistrados son independientes respecto a todos los órganos judiciales y de gobierno del Poder Judicial.»","Art. 15 LOPJ: «Los Jueces y Magistrados no podrán ser separados, suspendidos, trasladados ni jubilados sino por alguna de las causas y con las garantías previstas en esta Ley.»","Art. 124.1 CE: «El Ministerio Fiscal, sin perjuicio de las funciones encomendadas a otros órganos, tiene por misión promover la acción de la justicia en defensa de la legalidad, de los derechos de los ciudadanos y del interés público tutelado por la ley, de oficio o a petición de los interesados, así como velar por la independencia de los Tribunales y procurar ante éstos la satisfacción del interés social.»","Art. 2.1 Ley 50/1981: «El Ministerio Fiscal es un órgano de relevancia constitucional con personalidad jurídica propia, integrado con autonomía funcional en el Poder Judicial, y ejerce su misión por medio de órganos propios, conforme a los principios de unidad de actuación y dependencia jerárquica y con sujeción, en todo caso, a los de legalidad e imparcialidad.»","Art. 22.2 Ley 50/1981: «El Fiscal General del Estado ostenta la jefatura superior del Ministerio Fiscal y su representación en todo el territorio español. A él corresponde impartir las órdenes e instrucciones convenientes al servicio y al orden interno de la institución y, en general, la dirección e inspección del Ministerio Fiscal.»","Art. 124.4 CE: «El Fiscal General del Estado será nombrado por el Rey, a propuesta del Gobierno, oído el Consejo General del Poder Judicial.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"El Poder Judicial en la Constitución","blocks":[{"text":"La Constitución dedica su Título VI (arts. 117 a 127) al Poder Judicial. El punto de partida es que la justicia emana del pueblo y se administra en nombre del Rey por Jueces y Magistrados que forman parte del poder judicial. La Constitución les atribuye cuatro notas que conviene memorizar en este orden: independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley (art. 117.1 CE). La LOPJ repite la fórmula en su artículo 1, pero añade que están sometidos «a la Constitución y al imperio de la ley».","refs":[{"ref":"Art. 117.1","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"La justicia emana del pueblo y se administra en nombre del Rey por Jueces y Magistrados integrantes del poder judicial, independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley."},{"ref":"Art. 1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"La justicia emana del pueblo y se administra en nombre del Rey por Jueces y Magistrados integrantes del Poder Judicial, independientes, inamovibles, responsables y sometidos únicamente a la Constitución y al imperio de la ley."}]},{"text":"La Constitución remite a una ley orgánica, la LOPJ, la regulación de la constitución, funcionamiento y gobierno de Juzgados y Tribunales, el estatuto de los Jueces y Magistrados de carrera, que forman un Cuerpo único, y el del personal al servicio de la Administración de Justicia (art. 122.1 CE). El mismo Título VI recoge además la participación ciudadana: la acción popular y el Jurado en los procesos penales que la ley determine, así como los Tribunales consuetudinarios y tradicionales (art. 125 CE). La policía judicial depende de los Jueces, de los Tribunales y del Ministerio Fiscal en la averiguación del delito y el descubrimiento y aseguramiento del delincuente (art. 126 CE).","refs":[{"ref":"Art. 122.1","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"La ley orgánica del poder judicial determinará la constitución, funcionamiento y gobierno de los Juzgados y Tribunales, así como el estatuto jurídico de los Jueces y Magistrados de carrera, que formarán un Cuerpo único, y del personal al servicio de la Administración de Justicia."},{"ref":"Art. 125","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Los ciudadanos podrán ejercer la acción popular y participar en la Administración de Justicia mediante la institución del Jurado, en la forma y con respecto a aquellos procesos penales que la ley determine, así como en los Tribunales consuetudinarios y tradicionales."},{"ref":"Art. 126","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"La policía judicial depende de los Jueces, de los Tribunales y del Ministerio Fiscal en sus funciones de averiguación del delito y descubrimiento y aseguramiento del delincuente, en los términos que la ley establezca."}]}]},{"n":"2","title":"Principios: exclusividad, unidad jurisdiccional y prohibición de Tribunales de excepción","blocks":[{"text":"El principio de exclusividad tiene dos caras. En sentido positivo, juzgar y hacer ejecutar lo juzgado en todo tipo de procesos corresponde exclusivamente a los Juzgados y Tribunales determinados por las leyes, según sus normas de competencia y procedimiento (art. 117.3 CE). En sentido negativo, los Juzgados y Tribunales no ejercen más funciones que esa y las que la ley les atribuya expresamente en garantía de cualquier derecho (art. 117.4 CE; art. 2 LOPJ, que menciona también los tratados internacionales).","refs":[{"ref":"Art. 117.3","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El ejercicio de la potestad jurisdiccional en todo tipo de procesos, juzgando y haciendo ejecutar lo juzgado, corresponde exclusivamente a los Juzgados y Tribunales determinados por las leyes, según las normas de competencia y procedimiento que las mismas establezcan."},{"ref":"Art. 2.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Los jueces, las juezas y los Tribunales no ejercerán más funciones que las señaladas en el apartado anterior, y las demás que expresamente les sean atribuidas por ley en garantía de cualquier derecho."}]},{"text":"La unidad jurisdiccional es la base de la organización y funcionamiento de los Tribunales; la única excepción constitucional es la jurisdicción militar, limitada al ámbito estrictamente castrense y a los supuestos de estado de sitio (art. 117.5 CE). La LOPJ precisa que la jurisdicción militar forma parte del Poder Judicial del Estado (art. 3.2 LOPJ). Como garantía, la Constitución prohíbe los Tribunales de excepción (art. 117.6 CE) y la LOPJ prohíbe los Tribunales de Honor en la Administración de Justicia (art. 16.2 LOPJ).","refs":[{"ref":"Art. 117.5 y 117.6","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El principio de unidad jurisdiccional es la base de la organización y funcionamiento de los Tribunales. La ley regulará el ejercicio de la jurisdicción militar en el ámbito estrictamente castrense y en los supuestos de estado de sitio, de acuerdo con los principios de la Constitución. 6. Se prohíben los Tribunales de excepción."},{"ref":"Art. 16.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Se prohíben los Tribunales de Honor en la Administración de Justicia."}]}]},{"n":"3","title":"La jurisdicción en la LOPJ y los órdenes jurisdiccionales","blocks":[{"text":"La jurisdicción es única y la ejercen los jueces, las juezas y los Tribunales previstos en la LOPJ, sin perjuicio de las potestades jurisdiccionales que la Constitución reconoce a otros órganos (art. 3.1 LOPJ). Se extiende a todas las personas, materias y a todo el territorio español (art. 4 LOPJ). La Constitución vincula a todos los Jueces y Tribunales; si un órgano judicial considera que una norma con rango de ley aplicable al caso, de cuya validez dependa el fallo, puede ser inconstitucional, plantea la cuestión ante el Tribunal Constitucional (art. 5 LOPJ). Además, los Jueces no aplican reglamentos contrarios a la Constitución, a la ley o al principio de jerarquía normativa (art. 6 LOPJ).","refs":[{"ref":"Art. 3.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"La jurisdicción es única y se ejerce por los jueces, las juezas y los Tribunales previstos en esta ley orgánica, sin perjuicio de las potestades jurisdiccionales reconocidas por la Constitución a otros órganos."},{"ref":"Art. 5.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Cuando un órgano judicial considere, en algún proceso, que una norma con rango de ley, aplicable al caso, de cuya validez dependa el fallo, pueda ser contraria a la Constitución, planteará la cuestión ante el Tribunal Constitucional, con arreglo a lo que establece su Ley Orgánica."},{"ref":"Art. 6","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Los Jueces y Tribunales no aplicarán los reglamentos o cualquier otra disposición contrarios a la Constitución, a la ley o al principio de jerarquía normativa."}]},{"text":"El artículo 9 LOPJ reparte la materia entre cuatro órdenes. El civil conoce de lo suyo y, además, de todo lo que no esté atribuido a otro orden (es el orden «residual»). El penal conoce de las causas y juicios criminales, salvo los de la jurisdicción militar. El contencioso-administrativo conoce de las pretensiones relativas a la actuación de las Administraciones públicas sujeta al derecho administrativo, de las disposiciones generales de rango inferior a la ley y de la responsabilidad patrimonial de las Administraciones. El social conoce de la rama social del derecho, en conflictos individuales y colectivos, y de las reclamaciones de Seguridad Social. La jurisdicción es improrrogable y la falta de jurisdicción se aprecia de oficio, con audiencia de las partes y del Ministerio Fiscal (art. 9.6 LOPJ).","refs":[{"ref":"Art. 9.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Los jueces y juezas, así como los Tribunales del orden civil conocerán, además de las materias que les son propias, de todas aquellas que no estén atribuidas a otro orden jurisdiccional."},{"ref":"Art. 9.3","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Los del orden jurisdiccional penal tendrán atribuido el conocimiento de las causas y juicios criminales, con excepción de los que correspondan a la jurisdicción militar."},{"ref":"Art. 9.5","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Los del orden jurisdiccional social conocerán de las pretensiones que se promuevan dentro de la rama social del derecho, tanto en conflictos individuales como colectivos, así como las reclamaciones en materia de Seguridad Social o contra el Estado cuando le atribuya responsabilidad la legislación laboral."},{"ref":"Art. 9.6","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"La jurisdicción es improrrogable. Los órganos judiciales apreciarán de oficio la falta de jurisdicción y resolverán sobre la misma con audiencia de las partes y del Ministerio Fiscal."}]},{"text":"Tras la LO 1/2025, el artículo 26 LOPJ enumera así los órganos que ejercen la potestad jurisdiccional: jueces y juezas de paz, Tribunales de Instancia, Audiencias Provinciales, Tribunales Superiores de Justicia, Tribunal Central de Instancia, Audiencia Nacional y Tribunal Supremo. Ya no figuran en la lista los antiguos Juzgados unipersonales: su lugar lo ocupan los Tribunales de Instancia y el Tribunal Central de Instancia (se estudian en el tema 8).","refs":[{"ref":"Art. 26","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Los Tribunales a los que se atribuye el ejercicio de la potestad jurisdiccional son los siguientes: a) Jueces y juezas de paz. b) Tribunales de Instancia. c) Audiencias Provinciales. d) Tribunales Superiores de Justicia. e) Tribunal Central de Instancia. f) Audiencia Nacional. g) Tribunal Supremo."}]}]},{"n":"4","title":"El Consejo General del Poder Judicial: naturaleza y composición","blocks":[{"text":"El CGPJ es el órgano de gobierno del Poder Judicial (art. 122.2 CE); ejerce sus competencias en todo el territorio nacional y tiene su sede en la villa de Madrid (art. 558 LOPJ). Los Presidentes y demás órganos de gobierno de Juzgados y Tribunales están subordinados a él en el ejercicio de sus funciones gubernativas (art. 559 LOPJ). Según la Constitución, lo integran el Presidente del Tribunal Supremo, que lo preside, y veinte miembros nombrados por el Rey por cinco años: doce entre Jueces y Magistrados de todas las categorías y ocho entre abogados y otros juristas de reconocida competencia con más de quince años de ejercicio, cuatro a propuesta del Congreso y cuatro del Senado, por mayoría de tres quintos (art. 122.3 CE).","refs":[{"ref":"Art. 122.3","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Consejo General del Poder Judicial estará integrado por el Presidente del Tribunal Supremo, que lo presidirá, y por veinte miembros nombrados por el Rey por un período de cinco años. De éstos, doce entre Jueces y Magistrados de todas las categorías judiciales, en los términos que establezca la ley orgánica; cuatro a propuesta del Congreso de los Diputados, y cuatro a propuesta del Senado, elegidos en ambos casos por mayoría de tres quintos de sus miembros, entre abogados y otros juristas, todos ellos de reconocida competencia y con más de quince años de ejercicio en su profesión."},{"ref":"Art. 558","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"El gobierno del Poder Judicial corresponde al Consejo General del Poder Judicial, que ejerce sus competencias en todo el territorio nacional de acuerdo con la Constitución y la presente Ley Orgánica. 2. El Consejo General del Poder Judicial tiene su sede en la villa de Madrid."}]},{"text":"La LOPJ concreta el sistema: los veinte Vocales los designan las Cortes Generales (art. 567.1 LOPJ). Cada Cámara elige, por mayoría de tres quintos, a diez Vocales: cuatro juristas de reconocida competencia con más de quince años de ejercicio y seis del turno judicial (art. 567.2 LOPJ). Entre esos diez debe haber como mínimo un cuarenta por ciento de cada sexo. Las Cámaras designan también tres suplentes por cada turno, y nunca pueden ser designados Vocales del Consejo saliente (art. 567.4 y 5 LOPJ).","refs":[{"ref":"Art. 567.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Cada una de las Cámaras elegirá, por mayoría de tres quintos de sus miembros, a diez Vocales, cuatro entre juristas de reconocida competencia con más de quince años de ejercicio en su profesión y seis correspondientes al turno judicial"},{"ref":"Art. 567.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"cada una de las Cámaras garantizará el principio de presencia equilibrada de mujeres y hombres de forma que entre las diez personas vocales se incluya como mínimo un cuarenta por ciento de cada uno de los sexos."},{"ref":"Art. 567.5","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"En ningún caso podrá recaer la designación de Vocales del Consejo General del Poder Judicial en Vocales del Consejo saliente."}]},{"text":"El Consejo se renueva en su totalidad cada cinco años desde su constitución; cuatro meses antes de que expire ese plazo, el Presidente remite a los Presidentes de las Cámaras los datos del escalafón y del Registro de Asociaciones judiciales y abre el plazo de candidaturas del turno judicial (art. 568 LOPJ). Si ninguna Cámara ha designado a tiempo sus Vocales, el Consejo saliente continúa en funciones hasta la toma de posesión del nuevo (art. 570.2 LOPJ).","refs":[{"ref":"Art. 568.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"El Consejo General del Poder Judicial se renovará en su totalidad cada cinco años, contados desde la fecha de su constitución."},{"ref":"Art. 570.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Si ninguna de las dos Cámaras hubieren efectuado en el plazo legalmente previsto la designación de los Vocales que les corresponda, el Consejo saliente continuará en funciones hasta la toma de posesión del nuevo"}]}]},{"n":"5","title":"Atribuciones del CGPJ","blocks":[{"text":"El artículo 560 LOPJ enumera las atribuciones del Consejo. Entre las más preguntadas: proponer el nombramiento del Presidente del Tribunal Supremo y del CGPJ; proponer el de Jueces, Magistrados y Magistrados del Tribunal Supremo; proponer el nombramiento de dos Magistrados del Tribunal Constitucional; ser oído por el Gobierno antes de nombrar al Fiscal General del Estado; interponer el conflicto de atribuciones entre órganos constitucionales; y resolver sobre formación, destinos, ascensos, situaciones administrativas y régimen disciplinario de Jueces y Magistrados. También ejerce la alta inspección de Tribunales, regula la Escuela Judicial y el Centro de Documentación Judicial y recibe las quejas de los ciudadanos sobre la Administración de Justicia.","refs":[{"ref":"Art. 560.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"2.ª Proponer el nombramiento de Jueces, Magistrados y Magistrados del Tribunal Supremo. 3.ª Proponer el nombramiento, en los términos previstos por la presente Ley Orgánica, de dos Magistrados del Tribunal Constitucional. 4.ª Ser oído por el Gobierno antes del nombramiento del Fiscal General del Estado."},{"ref":"Art. 560.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"7.ª Resolver lo que proceda en materia de formación y perfeccionamiento, provisión de destinos, ascensos, situaciones administrativas y régimen disciplinario de Jueces y Magistrados."},{"ref":"Art. 560.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"20.ª Recibir quejas de los ciudadanos en materias relacionadas con la Administración de Justicia."}]},{"text":"La potestad reglamentaria del Consejo es limitada: solo cabe en el marco estricto de desarrollo de la LOPJ y en materias tasadas (por ejemplo, órganos de gobierno de Juzgados y Tribunales, publicidad de las actuaciones, reparto de asuntos o régimen de guardias), y nunca puede afectar a los derechos y deberes de personas ajenas al Consejo (art. 560.1.16.ª LOPJ).","refs":[{"ref":"Art. 560.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"16.ª Ejercer la potestad reglamentaria, en el marco estricto de desarrollo de las previsiones de la Ley Orgánica del Poder Judicial, en las siguientes materias:"},{"ref":"Art. 560.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"En ningún caso, las disposiciones reglamentarias del Consejo General del Poder Judicial podrán afectar o regular directa o indirectamente los derechos y deberes de personas ajenas al mismo."}]},{"text":"El Consejo informa los anteproyectos de ley y disposiciones generales sobre las materias del artículo 561 LOPJ: reformas de la LOPJ, demarcación y planta, estatuto de Jueces, Magistrados, Letrados y demás personal, normas procesales, leyes penales y régimen penitenciario, entre otras. El informe se emite en el plazo improrrogable de treinta días, o de quince si la orden de remisión hace constar la urgencia; si no se emite en plazo, se tiene por cumplido el trámite (art. 561.2 y 3 LOPJ).","refs":[{"ref":"Art. 561.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"El Consejo General del Poder Judicial emitirá su informe en el plazo improrrogable de treinta días. Si en la orden de remisión se hiciere constar la urgencia del informe, el plazo será de quince días."},{"ref":"Art. 561.3","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Cuando no hubiera sido emitido informe en los plazos previstos en el apartado anterior, se tendrá por cumplido dicho trámite."}]}]},{"n":"6","title":"Órganos del CGPJ: Presidencia, Pleno y Comisiones","blocks":[{"text":"Para ser elegido Presidente del Tribunal Supremo y del CGPJ hay que ser Magistrado del Tribunal Supremo que reúna las condiciones para ser Presidente de Sala, o jurista de reconocida competencia con más de veinticinco años de antigüedad. Las candidaturas se presentan en la sesión constitutiva, presidida por el Vocal de más edad; la elección se celebra entre tres y siete días después y exige, en votación nominal, la mayoría de tres quintos de los miembros del Pleno. Lo nombra el Rey mediante Real Decreto refrendado por el Presidente del Gobierno (art. 586 LOPJ).","refs":[{"ref":"Art. 586.3","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"La elección tendrá lugar en una sesión a celebrar entre tres y siete días más tarde, siendo elegido quien en votación nominal obtenga el apoyo de la mayoría de tres quintos de los miembros del Pleno."},{"ref":"Art. 586.4","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"El Presidente del Tribunal Supremo será nombrado por el Rey mediante Real Decreto refrendado por el Presidente del Gobierno."}]},{"text":"El Consejo actúa en Pleno o a través de sus Comisiones, que son seis: Permanente, de Calificación, Disciplinaria, de Asuntos Económicos, de Igualdad y de Supervisión y Control de Protección de Datos (art. 595 LOPJ). El Pleno propone, por tres quintos, a los dos Magistrados del Tribunal Constitucional que corresponden al Consejo (en el plazo máximo de tres meses desde el vencimiento del mandato anterior), resuelve los expedientes en que se proponga la separación de la carrera judicial y aprueba la Memoria anual, entre otras materias (art. 599.1 LOPJ).","refs":[{"ref":"Art. 595.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"En el Consejo General del Poder Judicial existirán las siguientes Comisiones: Permanente, de Calificación, Disciplinaria, de Asuntos Económicos, de Igualdad y de Supervisión y Control de Protección de Datos."},{"ref":"Art. 599.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"1.ª La propuesta de nombramiento, por mayoría de tres quintos, de los dos Magistrados del Tribunal Constitucional cuya designación corresponde al Consejo General del Poder Judicial, que tendrá que realizarse en el plazo máximo de tres meses a contar desde el día siguiente al vencimiento del mandato anterior."},{"ref":"Art. 599.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"10.ª La resolución de aquellos expedientes disciplinarios en los que la propuesta de sanción consista en la separación de la carrera judicial."}]},{"text":"El Pleno se reúne en sesión ordinaria una vez al mes, a convocatoria del Presidente, y en sesión extraordinaria si lo decide el Presidente o lo piden cinco Vocales. Para elegir Presidente se necesita la presencia de al menos doce miembros; en los demás casos, de diez Vocales y el Presidente (art. 600 LOPJ). La Comisión Permanente la forman el Presidente y siete Vocales (cuatro del turno judicial y tres del de juristas), elegidos anualmente por el Pleno (art. 601 LOPJ).","refs":[{"ref":"Art. 600.1 y 600.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"El Pleno se reunirá en sesión ordinaria, a convocatoria del Presidente, una vez al mes. 2. Deberá celebrarse sesión extraordinaria si lo considerare oportuno el Presidente o si lo solicitaren cinco Vocales"},{"ref":"Art. 600.3 y 600.4","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"En la sesión en la que se tenga que proceder a la elección del Presidente del Tribunal Supremo y del Consejo General del Poder Judicial será necesaria, para la válida constitución del Pleno, al menos la presencia de doce de sus miembros. 4. En los demás casos, para la válida constitución del Pleno será siempre necesaria, como mínimo, la presencia de diez Vocales y el Presidente."},{"ref":"Art. 601.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"La Comisión Permanente estará compuesta por el Presidente del Tribunal Supremo y del Consejo General del Poder Judicial, que la presidirá, y otros siete Vocales: cuatro de los nombrados por el turno judicial y tres de los designados por el turno de juristas de reconocida competencia."}]}]},{"n":"7","title":"Jueces y Magistrados: la Carrera Judicial y los sistemas de acceso","blocks":[{"text":"Las funciones jurisdiccionales se ejercen únicamente por jueces y magistrados profesionales, que forman la Carrera Judicial; también ejercen jurisdicción, sin pertenecer a ella y con inamovilidad temporal, los magistrados suplentes, los jueces sustitutos y los jueces de paz y sus sustitutos (art. 298 LOPJ). La Carrera Judicial tiene tres categorías: Magistrado del Tribunal Supremo, Magistrado y Juez (art. 299.1 LOPJ). El CGPJ aprueba el escalafón cada tres años como máximo y se publica en el BOE (art. 300 LOPJ).","refs":[{"ref":"Art. 298.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"También ejercen funciones jurisdiccionales sin pertenecer a la Carrera Judicial, con sujeción al régimen establecido en esta ley y con inamovilidad temporal, los magistrados y las magistradas suplentes, quienes sirven plazas como jueces sustitutos y juezas sustitutas, así como los jueces de paz y sus sustitutos."},{"ref":"Art. 299.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"La Carrera Judicial consta de tres categorías: – Magistrado del Tribunal Supremo. – Magistrado. – Juez."}]},{"text":"El ingreso se basa en el mérito y la capacidad. Por la categoría de juez se ingresa superando una oposición libre y un curso teórico y práctico de selección en la Escuela Judicial (art. 301.3 LOPJ). La convocatoria se hace conjuntamente con la de la Carrera Fiscal, y los aprobados eligen una u otra carrera según el orden de puntuación (art. 301.4 LOPJ; art. 42 EOMF). También pueden ingresar como magistrado o magistrado del Tribunal Supremo juristas de reconocida competencia; los que entren como magistrado deben superar un curso en la Escuela Judicial (art. 301.5 LOPJ). Se reserva al menos un cinco por ciento de las vacantes a personas con discapacidad igual o superior al 33 % (art. 301.8 LOPJ). Para opositar se requiere ser español, mayor de edad y licenciado en Derecho, y no estar incurso en causa de incapacidad (art. 302 LOPJ).","refs":[{"ref":"Art. 301.3","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"El ingreso en la Carrera Judicial por la categoría de juez se producirá mediante la superación de oposición libre y de un curso teórico y práctico de selección realizado en la Escuela Judicial."},{"ref":"Art. 301.4","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"La convocatoria para el ingreso en la Carrera Judicial, que se realizará conjuntamente con la de ingreso en la Carrera Fiscal, comprenderá todas las plazas vacantes existentes en el momento de la misma y un número adicional que permita cubrir las que previsiblemente puedan producirse hasta la siguiente convocatoria."},{"ref":"Art. 301.8","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"También se reservará en la convocatoria un cupo no inferior al cinco por ciento de las vacantes para ser cubiertas entre personas con discapacidad en grado igual o superior al 33 por ciento"},{"ref":"Art. 302","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Para concurrir a la oposición libre de acceso a la Escuela Judicial se requiere ser español, mayor de edad y licenciado en Derecho, así como no estar incurso en alguna de las causas de incapacidad que establece la ley."},{"ref":"Art. 42","law":"Ley 50/1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-837","quote":"El ingreso en la Carrera Fiscal se hará por oposición libre entre quienes reúnan las condiciones de capacidad exigidas en esta Ley, que se realizará conjuntamente con la de ingreso en la Carrera Judicial, en los términos previstos en la Ley Orgánica del Poder Judicial."}]}]},{"n":"8","title":"La independencia judicial y sus garantías","blocks":[{"text":"En el ejercicio de la potestad jurisdiccional, los Jueces y Magistrados son independientes respecto de todos los órganos judiciales y de gobierno del Poder Judicial (art. 12.1 LOPJ). Los superiores solo pueden corregir la interpretación de los inferiores al resolver los recursos legales, y ni los Tribunales, ni sus órganos de gobierno ni el CGPJ pueden dictar instrucciones, generales o particulares, sobre cómo aplicar o interpretar el ordenamiento (art. 12.2 y 3 LOPJ). Todos están obligados a respetar esa independencia (art. 13 LOPJ).","refs":[{"ref":"Art. 12.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"En el ejercicio de la potestad jurisdiccional, los Jueces y Magistrados son independientes respecto a todos los órganos judiciales y de gobierno del Poder Judicial."},{"ref":"Art. 12.3","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Tampoco podrán los Jueces y Tribunales, órganos de gobierno de los mismos o el Consejo General del Poder Judicial dictar instrucciones, de carácter general o particular, dirigidas a sus inferiores, sobre la aplicación o interpretación del ordenamiento jurídico que lleven a cabo en el ejercicio de su función jurisdiccional."}]},{"text":"El juez que se sienta inquietado o perturbado en su independencia lo comunica al CGPJ, da cuenta de los hechos al Juez o Tribunal competente y puede practicar él mismo las diligencias estrictamente indispensables; el Ministerio Fiscal promueve las acciones en defensa de la independencia judicial (art. 14 LOPJ). La inamovilidad significa que no pueden ser separados, suspendidos, trasladados ni jubilados sino por las causas y con las garantías de la ley (art. 117.2 CE; art. 15 LOPJ). La responsabilidad puede ser penal, civil y disciplinaria (art. 16.1 LOPJ).","refs":[{"ref":"Art. 14","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Los Jueces y Magistrados que se consideren inquietados o perturbados en su independencia lo pondrán en conocimiento del Consejo General del Poder Judicial, dando cuenta de los hechos al Juez o Tribunal competente para seguir el procedimiento adecuado, sin perjuicio de practicar por sí mismos las diligencias estrictamente indispensables para asegurar la acción de la justicia y restaurar el orden jurídico. 2. El Ministerio Fiscal, por sí o a petición de aquéllos, promoverá las acciones pertinentes en defensa de la independencia judicial."},{"ref":"Art. 15","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Los Jueces y Magistrados no podrán ser separados, suspendidos, trasladados ni jubilados sino por alguna de las causas y con las garantías previstas en esta Ley."},{"ref":"Art. 16.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Los Jueces y Magistrados responderán penal y civilmente en los casos y en la forma determinada en las leyes, y disciplinariamente de conformidad con lo establecido en esta Ley."}]},{"text":"La jubilación por edad es forzosa a los setenta años, aunque pueden pedir, con dos meses de antelación, prolongar el servicio activo hasta los setenta y dos; el CGPJ solo puede denegarlo si no se cumple la edad o la solicitud llega fuera de plazo. La jubilación voluntaria cabe desde los sesenta y cinco años, avisando al Consejo con seis meses de antelación (art. 386 LOPJ).","refs":[{"ref":"Art. 386.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"La jubilación por edad de los Jueces y Magistrados es forzosa y se decretará con la antelación suficiente para que el cese en la función se produzca efectivamente al cumplir la edad de setenta años. No obstante, podrán solicitar con dos meses de antelación a dicho momento la prolongación de la permanencia en el servicio activo hasta que cumplan como máximo setenta y dos años de edad."},{"ref":"Art. 386.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"También podrán jubilarse a partir de los sesenta y cinco años siempre que así lo hubieren manifestado al Consejo y General del Poder Judicial con seis meses de antelación"}]}]},{"n":"9","title":"Incompatibilidades, prohibiciones y asociacionismo judicial","blocks":[{"text":"Mientras estén en activo, Jueces, Magistrados y Fiscales no pueden desempeñar otros cargos públicos ni pertenecer a partidos políticos o sindicatos (art. 127.1 CE). El cargo judicial es incompatible, entre otros, con cualquier otra jurisdicción, con cargos de elección popular o designación política, con la Abogacía y la Procuraduría, con todo asesoramiento jurídico, retribuido o no, y con la actividad mercantil; se salvan la docencia o investigación jurídica y la creación literaria, artística, científica y técnica (art. 389 LOPJ). Quien, ocupando un cargo incompatible, sea nombrado Juez o Magistrado debe optar en ocho días; si no lo hace, se entiende que renuncia al nombramiento judicial (art. 390 LOPJ).","refs":[{"ref":"Art. 127.1","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Los Jueces y Magistrados así como los Fiscales, mientras se hallen en activo, no podrán desempeñar otros cargos públicos, ni pertenecer a partidos políticos o sindicatos."},{"ref":"Art. 389","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"5.º Con todo empleo, cargo o profesión retribuida, salvo la docencia o investigación jurídica, así como la producción y creación literaria, artística, científica y técnica, y las publicaciones derivadas de aquélla"},{"ref":"Art. 389","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"6.º Con el ejercicio de la Abogacía y de la Procuraduría. 7.º Con todo tipo de asesoramiento jurídico, sea o no retribuido."},{"ref":"Art. 390","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Los que ejerciendo cualquier empleo, cargo o profesión de los expresados en el artículo anterior fueren nombrados Jueces o Magistrados, deberán optar, en el plazo de ocho días, por uno u otro cargo, o cesar en el ejercicio de la actividad incompatible. 2. Quienes no hicieren uso de dicha opción en el indicado plazo se entenderá que renuncian al nombramiento judicial."}]},{"text":"Además, les está prohibido felicitar o censurar a poderes y autoridades por sus actos y tomar parte en las elecciones más allá de emitir su voto (art. 395 LOPJ). En cambio, la ley reconoce la libre asociación profesional: las asociaciones tienen ámbito nacional, no pueden realizar actividades políticas, solo admiten jueces y magistrados en servicio activo, nadie puede afiliarse a más de una y quedan constituidas al inscribirse en el registro del CGPJ (art. 401 LOPJ).","refs":[{"ref":"Art. 395","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"2.º Tomar en las elecciones legislativas o locales más parte que la de emitir su voto personal."},{"ref":"Art. 401","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"3.ª Las asociaciones de jueces y magistrados deberán tener ámbito nacional, sin perjuicio de la existencia de secciones cuyo ámbito coincida con el de un Tribunal Superior de Justicia."},{"ref":"Art. 401","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Sólo podrán formar parte de las mismas quienes ostenten la condición de jueces y magistrados en servicio activo. Ningún juez o magistrado podrá estar afiliado a más de una asociación profesional. 6.ª Las asociaciones profesionales de jueces y magistrados integrantes de la Carrera Judicial quedarán válidamente constituidas desde que se inscriban en el registro que será llevado al efecto por el Consejo General del Poder Judicial."}]}]},{"n":"10","title":"El Ministerio Fiscal: naturaleza, principios y funciones","blocks":[{"text":"La misión del Ministerio Fiscal es promover la acción de la justicia en defensa de la legalidad, de los derechos de los ciudadanos y del interés público tutelado por la ley, de oficio o a petición de los interesados, velar por la independencia de los Tribunales y procurar ante ellos la satisfacción del interés social (art. 124.1 CE; art. 1 EOMF). Su estatuto lo regula la Ley 50/1981 (EOMF), que lo define como órgano de relevancia constitucional con personalidad jurídica propia, integrado con autonomía funcional en el Poder Judicial (art. 2.1 EOMF).","refs":[{"ref":"Art. 124.1","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Ministerio Fiscal, sin perjuicio de las funciones encomendadas a otros órganos, tiene por misión promover la acción de la justicia en defensa de la legalidad, de los derechos de los ciudadanos y del interés público tutelado por la ley, de oficio o a petición de los interesados, así como velar por la independencia de los Tribunales y procurar ante éstos la satisfacción del interés social."},{"ref":"Art. 2.1","law":"Ley 50/1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-837","quote":"El Ministerio Fiscal es un órgano de relevancia constitucional con personalidad jurídica propia, integrado con autonomía funcional en el Poder Judicial"}]},{"text":"Actúa por medio de órganos propios conforme a dos principios orgánicos, unidad de actuación y dependencia jerárquica, y con sujeción en todo caso a dos principios funcionales, legalidad e imparcialidad (art. 124.2 CE). Es único para todo el Estado (art. 22.1 EOMF).","refs":[{"ref":"Art. 124.2","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Ministerio Fiscal ejerce sus funciones por medio de órganos propios conforme a los principios de unidad de actuación y dependencia jerárquica y con sujeción, en todo caso, a los de legalidad e imparcialidad."},{"ref":"Art. 22.1","law":"Ley 50/1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-837","quote":"El Ministerio Fiscal es único para todo el Estado."}]},{"text":"El artículo 3 EOMF detalla dieciséis funciones. Destacan: velar por que la función jurisdiccional se ejerza eficazmente y en plazo; defender la independencia judicial; ejercitar las acciones penales y civiles derivadas de delito (sin perjuicio de la Fiscalía Europea); intervenir en el proceso penal pidiendo medidas cautelares e instruyendo directamente en la responsabilidad penal de los menores; tomar parte en los procesos sobre estado civil; proteger a víctimas, testigos y peritos; e interponer el recurso de amparo. En los procesos no penales interviene, salvo otra previsión o que sea demandante, en último lugar.","refs":[{"ref":"Art. 3","law":"Ley 50/1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-837","quote":"1. Velar por que la función jurisdiccional se ejerza eficazmente conforme a las leyes y en los plazos y términos en ellas señalados, ejercitando, en su caso, las acciones, recursos y actuaciones pertinentes."},{"ref":"Art. 3","law":"Ley 50/1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-837","quote":"5. Intervenir en el proceso penal, instando de la autoridad judicial la adopción de las medidas cautelares que procedan y la práctica de las diligencias encaminadas al esclarecimiento de los hechos o instruyendo directamente el procedimiento en el ámbito de lo dispuesto en la Ley Orgánica reguladora de la Responsabilidad Penal de los Menores"},{"ref":"Art. 3","law":"Ley 50/1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-837","quote":"La intervención del fiscal en los procesos no penales, salvo que la ley disponga otra cosa o actúe como demandante, se producirá en último lugar."}]}]},{"n":"11","title":"Organización del Ministerio Fiscal: Fiscal General del Estado y Consejo Fiscal","blocks":[{"text":"Son órganos del Ministerio Fiscal, entre otros, el Fiscal General del Estado, el Consejo Fiscal, la Junta de Fiscales de Sala, la Junta de Fiscales Superiores, las Fiscalías del Tribunal Supremo, ante el Tribunal Constitucional y de la Audiencia Nacional, las Fiscalías Especiales, las de las Comunidades Autónomas, las Provinciales y las de Área (art. 12 EOMF). La Carrera Fiscal tiene tres categorías: Fiscales de Sala del Tribunal Supremo, Fiscales y Abogados-Fiscales, equiparados respectivamente a Magistrados del Supremo, Magistrados y Jueces (art. 34 EOMF).","refs":[{"ref":"Art. 12","law":"Ley 50/1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-837","quote":"Son órganos del Ministerio Fiscal: a) El Fiscal General del Estado. b) El Consejo Fiscal. c) La Junta de Fiscales de Sala."},{"ref":"Art. 34","law":"Ley 50/1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-837","quote":"1.ª Fiscales de Sala del Tribunal Supremo, equiparados a Magistrados del Alto Tribunal. El Teniente Fiscal del Tribunal Supremo tendrá la consideración de Presidente de Sala. 2.ª Fiscales, equiparados a Magistrados. 3.ª Abogados-Fiscales, equiparados a Jueces."}]},{"text":"El Fiscal General del Estado ostenta la jefatura superior y la representación del Ministerio Fiscal en toda España e imparte las órdenes e instrucciones del servicio (art. 22.2 EOMF). Lo nombra el Rey a propuesta del Gobierno, oído previamente el CGPJ (art. 124.4 CE), entre juristas españoles de reconocido prestigio con más de quince años de ejercicio efectivo; presta juramento ante el Rey y toma posesión ante el Pleno del Tribunal Supremo (art. 29 EOMF). Su mandato dura cuatro años, no es renovable salvo que lo hubiera ejercido menos de dos años, y solo cesa antes por causas tasadas, entre ellas el cese del Gobierno que lo propuso (art. 31 EOMF).","refs":[{"ref":"Art. 22.2","law":"Ley 50/1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-837","quote":"El Fiscal General del Estado ostenta la jefatura superior del Ministerio Fiscal y su representación en todo el territorio español. A él corresponde impartir las órdenes e instrucciones convenientes al servicio y al orden interno de la institución y, en general, la dirección e inspección del Ministerio Fiscal."},{"ref":"Art. 29.1","law":"Ley 50/1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-837","quote":"El Fiscal General del Estado será nombrado por el Rey, a propuesta del Gobierno, oído previamente el Consejo General del Poder Judicial, eligiéndolo entre juristas españoles de reconocido prestigio con más de quince años de ejercicio efectivo de su profesión."},{"ref":"Art. 31","law":"Ley 50/1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-837","quote":"El mandato del Fiscal General del Estado tendrá una duración de cuatro años. […] e) cuando cese el Gobierno que lo hubiera propuesto. Dos. El mandato del Fiscal General del Estado no podrá ser renovado, excepto en los supuestos en que el titular hubiera ostentado el cargo durante un periodo inferior a dos años."}]},{"text":"El Consejo Fiscal lo preside el Fiscal General del Estado y lo integran el Teniente Fiscal del Tribunal Supremo, el Fiscal Jefe Inspector y nueve Fiscales de cualquier categoría elegidos por cuatro años. Funciona en Pleno y en Comisión Permanente, decide por mayoría simple con voto dirimente del Presidente, y entre otras funciones asesora al Fiscal General, informa los nombramientos y los proyectos normativos que afecten al Ministerio Fiscal (en treinta días hábiles, o quince si son urgentes) (art. 14 EOMF).","refs":[{"ref":"Art. 14","law":"Ley 50/1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-837","quote":"Uno. El Consejo Fiscal se constituirá, bajo la Presidencia de la persona titular de la Fiscalía General del Estado, por el o la Teniente Fiscal del Tribunal Supremo, el Fiscal Jefe Inspector o la Fiscal Jefa Inspectora y nueve Fiscales pertenecientes a cualquiera de las categorías."},{"ref":"Art. 14","law":"Ley 50/1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-837","quote":"Tres. El Consejo Fiscal podrá funcionar en Pleno y en Comisión Permanente y sus acuerdos se adoptarán por mayoría simple, siendo dirimente, en caso de empate, el voto de su Presidente."},{"ref":"Art. 14","law":"Ley 50/1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-837","quote":"A estos efectos, el Consejo Fiscal deberá emitir el informe correspondiente en el plazo de treinta días hábiles. Cuando en la orden de remisión se haga constar la urgencia del informe, el plazo será de quince días hábiles."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Notas de los jueces (art. 117.1 CE): independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley.","refs":[{"ref":"Art. 117.1","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley."}]},{"text":"Se prohíben los Tribunales de excepción (CE) y los Tribunales de Honor (LOPJ).","refs":[{"ref":"Art. 117.6","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Se prohíben los Tribunales de excepción."}]},{"text":"El orden civil es el residual: conoce de todo lo no atribuido a otro orden.","refs":[{"ref":"Art. 9.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"además de las materias que les son propias, de todas aquellas que no estén atribuidas a otro orden jurisdiccional."}]},{"text":"CGPJ: Presidente del TS + 20 Vocales por cinco años; cada Cámara elige diez (cuatro juristas y seis jueces) por tres quintos.","refs":[{"ref":"Art. 566","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"El Consejo General del Poder Judicial estará integrado por el Presidente del Tribunal Supremo, que lo presidirá, y por veinte Vocales, de los cuales doce serán Jueces o Magistrados en servicio activo en la carrera judicial y ocho juristas de reconocida competencia."}]},{"text":"Informes del CGPJ: treinta días improrrogables, quince si es urgente.","refs":[{"ref":"Art. 561.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"El Consejo General del Poder Judicial emitirá su informe en el plazo improrrogable de treinta días."}]},{"text":"Pleno del CGPJ: una sesión ordinaria al mes; Comisión Permanente: Presidente + siete Vocales (cuatro judiciales y tres juristas).","refs":[{"ref":"Art. 600.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"El Pleno se reunirá en sesión ordinaria, a convocatoria del Presidente, una vez al mes."}]},{"text":"Carrera Judicial: tres categorías; jubilación forzosa a los setenta, prorrogable hasta los setenta y dos.","refs":[{"ref":"Art. 386.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"podrán solicitar con dos meses de antelación a dicho momento la prolongación de la permanencia en el servicio activo hasta que cumplan como máximo setenta y dos años de edad."}]},{"text":"Plazo para optar si se es nombrado juez ocupando un cargo incompatible: ocho días.","refs":[{"ref":"Art. 390.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"deberán optar, en el plazo de ocho días, por uno u otro cargo"}]},{"text":"Fiscal General del Estado: lo nombra el Rey a propuesta del Gobierno, oído el CGPJ; mandato de cuatro años no renovable (salvo menos de dos años en el cargo).","refs":[{"ref":"Art. 124.4","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Fiscal General del Estado será nombrado por el Rey, a propuesta del Gobierno, oído el Consejo General del Poder Judicial."}]},{"text":"Consejo Fiscal: FGE, Teniente Fiscal del TS, Fiscal Jefe Inspector y nueve Fiscales elegidos por cuatro años.","refs":[{"ref":"Art. 14","law":"Ley 50/1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-837","quote":"Todos los miembros del Consejo Fiscal, excepto la persona titular de la Fiscalía General del Estado, el o la Teniente Fiscal del Tribunal Supremo y el Fiscal Inspector, se elegirán, por un período de cuatro años"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229', null, null, null, 'Otras normas citadas: LOPJ (https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666), Ley 50/1981 (https://www.boe.es/buscar/act.php?id=BOE-A-1982-837)'
  from public.topics t where t.slug = 'jus-06-poder-judicial'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('jus-07-ts-an-tsj-ap', 'Tema 7. Organización y competencia del TS, la AN, los TSJ y las Audiencias Provinciales') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-07-ts-an-tsj-ap' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El Tribunal Supremo: sede, composición y Salas (arts. 53-55 LOPJ)"},{"n":"1.1","title":"Competencia de las Salas (arts. 56-60 LOPJ)"},{"n":"1.2","title":"La Sala del artículo 61 y el Gabinete Técnico (arts. 61-61 sexies LOPJ)"},{"n":"2","title":"La Audiencia Nacional: sede, composición y Salas (arts. 62-64 LOPJ)"},{"n":"2.1","title":"Competencia de las Salas de Apelación, Penal, Contencioso-Administrativo y Social (arts. 64 bis-69 LOPJ)"},{"n":"3","title":"Los Tribunales Superiores de Justicia: organización y Salas (arts. 70-72 LOPJ)"},{"n":"3.1","title":"Competencia de las Salas (arts. 73-79 LOPJ)"},{"n":"4","title":"Las Audiencias Provinciales: sede y composición (arts. 80-81 LOPJ)"},{"n":"4.1","title":"Competencia en los órdenes penal y civil y Jurado (arts. 82-83 LOPJ)"}]'::jsonb, '["Art. 53 LOPJ: «El Tribunal Supremo, con sede en la villa de Madrid, es el órgano jurisdiccional superior en todos los órdenes, salvo lo dispuesto en materia de garantías Constitucionales. Tendrá jurisdicción en toda España y ningún otro podrá tener el título de Supremo.»","Art. 55 LOPJ: «El Tribunal Supremo estará integrado por las siguientes Salas: Primera: De lo Civil. Segunda: De lo Penal. Tercera: De lo Contencioso-Administrativo. Cuarta: De lo Social. Quinta: De lo Militar, que se regirá por su legislación específica y supletoriamente por la presente Ley y por el ordenamiento común a las demás Salas del Tribunal Supremo.»","Art. 59 LOPJ: «La Sala de lo Social del Tribunal Supremo conocerá de los recursos de casación y revisión y otros extraordinarios que establezca la ley en materias propias de este orden jurisdiccional.»","Art. 61.1 LOPJ: «Una Sala formada por el Presidente del Tribunal Supremo, los Presidentes de Sala y el Magistrado más antiguo y el más moderno de cada una de ellas conocerá: 1.º De los recursos de revisión contra las sentencias dictadas en única instancia por la Sala de lo Contencioso-Administrativo de dicho Tribunal.»","Art. 62 LOPJ: «La Audiencia Nacional, con sede en la villa de Madrid, tiene jurisdicción en toda España.»","Art. 64.1 LOPJ: «La Audiencia Nacional estará integrada por las siguientes Salas: De Apelación. De lo Penal. De lo Contencioso-Administrativo. De lo Social.»","Art. 64 bis.1 LOPJ: «La Sala de Apelación de la Audiencia Nacional conocerá de los recursos de esta clase que establezca la ley contra las resoluciones de la Sala de lo Penal.»","Art. 67 LOPJ: «La Sala de lo Social de la Audiencia Nacional conocerá en única instancia: 1.º De los procesos especiales de impugnación de convenios colectivos cuyo ámbito territorial de aplicación sea superior al territorio de una Comunidad Autónoma. 2.º De los procesos sobre conflictos colectivos cuya resolución haya de surtir efecto en un ámbito territorial superior al de una Comunidad Autónoma.»","Art. 70 LOPJ: «El Tribunal Superior de Justicia de la Comunidad Autónoma culminará la organización judicial en el ámbito territorial de aquélla, sin perjuicio de la jurisdicción que corresponde al Tribunal Supremo.»","Art. 72 LOPJ: «El Tribunal Superior de Justicia estará integrado por las siguientes Salas: de lo Civil y Penal, de lo Contencioso-Administrativo y de lo Social. 2. Se compondrá de un Presidente, que lo será también de su Sala de lo Civil y Penal, y tendrá la consideración de Magistrado del Tribunal Supremo mientras desempeñe el cargo»","Art. 73.3 c) LOPJ: «El conocimiento de los recursos de apelación contra las resoluciones dictadas en primera instancia por las Audiencias Provinciales, así como el de todos aquellos previstos por las leyes.»","Art. 74.2 LOPJ: «Conocerán, en segunda instancia, de las apelaciones promovidas contra sentencias y autos dictados en las Secciones de lo Contencioso-Administrativo de los Tribunales de Instancia y de los correspondientes recursos de queja.»","Art. 80.1 LOPJ: «Las Audiencias Provinciales, que tendrán su sede en la capital de la provincia, de la que tomarán su nombre, extenderán su jurisdicción a toda ella, sin perjuicio de lo dispuesto en el apartado 4 del artículo 82.»","Art. 81.1 LOPJ: «Las Audiencias Provinciales se compondrán de un Presidente y dos o más magistrados. También podrán estar integradas por dos o más Secciones de la misma composición, en cuyo caso el Presidente de la Audiencia presidirá una de las Secciones que determinará al principio de su mandato.»","Art. 82.1 LOPJ: «Las Audiencias Provinciales conocerán en el orden penal: 1.º De las causas por delito, a excepción de los que la ley atribuye al conocimiento de las Secciones de lo Penal de los Tribunales de Instancia o de otros Tribunales previstos en esta ley.»","Art. 82.2 LOPJ: «Las Audiencias Provinciales conocerán en el orden civil: 1.º De los recursos que establezca la ley contra las resoluciones dictadas en primera instancia por las Secciones Civiles de los Tribunales de Instancia de la provincia.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"El Tribunal Supremo: sede, composición y Salas","blocks":[{"text":"El Tribunal Supremo tiene su sede en la villa de Madrid y jurisdicción en toda España. Es el órgano jurisdiccional superior en todos los órdenes, con una sola salvedad: lo dispuesto en materia de garantías constitucionales, que corresponde al Tribunal Constitucional (art. 123.1 CE; art. 53 LOPJ). Ningún otro órgano puede llevar el título de «Supremo». Su Presidente lo nombra el Rey a propuesta del CGPJ (art. 123.2 CE) y es a la vez Presidente del Consejo.","refs":[{"ref":"Art. 53","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"El Tribunal Supremo, con sede en la villa de Madrid, es el órgano jurisdiccional superior en todos los órdenes, salvo lo dispuesto en materia de garantías Constitucionales. Tendrá jurisdicción en toda España y ningún otro podrá tener el título de Supremo."},{"ref":"Art. 123.2","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Presidente del Tribunal Supremo será nombrado por el Rey, a propuesta del Consejo General del Poder Judicial, en la forma que determine la ley."}]},{"text":"Lo componen su Presidente, los Presidentes de Sala y los Magistrados que la ley fije para cada Sala y Sección (art. 54 LOPJ). Tiene cinco Salas, numeradas, cuyo orden es un clásico del examen: Primera, de lo Civil; Segunda, de lo Penal; Tercera, de lo Contencioso-Administrativo; Cuarta, de lo Social; y Quinta, de lo Militar, que se rige por su legislación específica y supletoriamente por la LOPJ (art. 55 LOPJ).","refs":[{"ref":"Art. 55","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"El Tribunal Supremo estará integrado por las siguientes Salas: Primera: De lo Civil. Segunda: De lo Penal. Tercera: De lo Contencioso-Administrativo. Cuarta: De lo Social. Quinta: De lo Militar, que se regirá por su legislación específica y supletoriamente por la presente Ley y por el ordenamiento común a las demás Salas del Tribunal Supremo."}]}]},{"n":"2","title":"Competencia de las Salas del Tribunal Supremo","blocks":[{"text":"La Sala de lo Civil conoce de los recursos de casación, revisión y otros extraordinarios en materia civil, y de las demandas de responsabilidad civil por hechos realizados en el ejercicio del cargo contra los altos cargos del Estado (Presidente del Gobierno, Presidentes de las Cámaras, miembros del Gobierno, Diputados y Senadores, Vocales del CGPJ, Fiscal General del Estado, Defensor del Pueblo, entre otros) y contra Magistrados de la Audiencia Nacional o de los Tribunales Superiores de Justicia (art. 56 LOPJ).","refs":[{"ref":"Art. 56","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"1.º De los recursos de casación, revisión y otros extraordinarios en materia civil que establezca la ley."},{"ref":"Art. 56","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"3.º De las demandas de responsabilidad civil dirigidas contra Magistrados de la Audiencia Nacional o de los Tribunales Superiores de Justicia por hechos realizados en el ejercicio de sus cargos."}]},{"text":"La Sala de lo Penal conoce de la casación, la revisión y otros recursos extraordinarios penales, y de la instrucción y enjuiciamiento de las causas contra los aforados ante el Supremo: Presidente del Gobierno, Presidentes del Congreso y del Senado, miembros del Gobierno, Diputados y Senadores, Vocales del CGPJ, Magistrados del Tribunal Constitucional y del Supremo, Fiscal General del Estado, Fiscal Europeo, Defensor del Pueblo y otros, así como contra Magistrados de la Audiencia Nacional o de un TSJ (art. 57.1 LOPJ). En esas causas se designa como instructor, por turno preestablecido, a un miembro de la Sala que después no la integra para enjuiciar (art. 57.2 LOPJ); si el delito corresponde a la Fiscalía Europea, se designa de igual modo un Juez de garantías (art. 57.3 LOPJ).","refs":[{"ref":"Art. 57.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"2.º De la instrucción y enjuiciamiento de las causas contra el Presidente del Gobierno, Presidentes del Congreso y del Senado, Presidente del Tribunal Supremo y del Consejo General del Poder Judicial, Presidente del Tribunal Constitucional, miembros del Gobierno, Diputados y Senadores"},{"ref":"Art. 57.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"En las causas a que se refieren los números segundo y tercero del párrafo anterior se designará de entre los miembros de la Sala, conforme a un turno preestablecido, un instructor, que no formará parte de la misma para enjuiciarlas."}]},{"text":"La Sala de lo Contencioso-Administrativo conoce en única instancia de los recursos contra actos y disposiciones del Consejo de Ministros, de las Comisiones Delegadas del Gobierno y del CGPJ, y contra los actos de los órganos competentes del Congreso, del Senado, del Tribunal Constitucional, del Tribunal de Cuentas y del Defensor del Pueblo; además, de la casación y la revisión (art. 58 LOPJ). La Sala de lo Social conoce de los recursos de casación, revisión y otros extraordinarios en su materia (art. 59 LOPJ). Cada Sala resuelve también las recusaciones contra sus Magistrados y las cuestiones de competencia entre órganos de su orden sin otro superior común (art. 60 LOPJ).","refs":[{"ref":"Art. 58","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Primero. En única instancia, de los recursos contencioso-administrativos contra actos y disposiciones del Consejo de Ministros, de las Comisiones Delegadas del Gobierno y del Consejo General del Poder Judicial y contra los actos y disposiciones de los órganos competentes del Congreso de los Diputados y del Senado, del Tribunal Constitucional, del Tribunal de Cuentas y del Defensor del Pueblo"},{"ref":"Art. 59","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"La Sala de lo Social del Tribunal Supremo conocerá de los recursos de casación y revisión y otros extraordinarios que establezca la ley en materias propias de este orden jurisdiccional."},{"ref":"Art. 60.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Conocerá además cada una de las Salas del Tribunal Supremo de las recusaciones que se interpusieren contra los Magistrados que las compongan, y de las cuestiones de competencia entre Juzgados o Tribunales del propio orden jurisdiccional que no tengan otro superior común."}]}]},{"n":"3","title":"La Sala del artículo 61 y el Gabinete Técnico","blocks":[{"text":"El artículo 61 LOPJ crea una Sala especial formada por el Presidente del Tribunal Supremo, los Presidentes de Sala y el Magistrado más antiguo y el más moderno de cada Sala. Conoce, entre otros asuntos, de los recursos de revisión contra sentencias de la Sala de lo Contencioso-Administrativo dictadas en única instancia; de la recusación del Presidente, de los Presidentes de Sala o de más de dos Magistrados de una Sala; de la responsabilidad civil y penal contra Presidentes de Sala o contra todos o la mayoría de los Magistrados de una Sala; del error judicial imputado a una Sala del Supremo; y de los procesos de declaración de ilegalidad y disolución de partidos políticos (LO 6/2002).","refs":[{"ref":"Art. 61.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Una Sala formada por el Presidente del Tribunal Supremo, los Presidentes de Sala y el Magistrado más antiguo y el más moderno de cada una de ellas conocerá:"},{"ref":"Art. 61.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"5.º Del conocimiento de las pretensiones de declaración de error judicial cuando éste se impute a una Sala del Tribunal Supremo. 6.º De los procesos de declaración de ilegalidad y consecuente disolución de los partidos políticos, conforme a lo dispuesto en la Ley Orgánica 6/2002, de 27 de junio, de Partidos Políticos."}]},{"text":"Para la casación para la unificación de doctrina cuando la contradicción se da entre sentencias de distintas Secciones de la Sala Tercera dictadas en única instancia, existe una Sección formada por el Presidente del Supremo, el de la Sala de lo Contencioso-Administrativo y cinco Magistrados de esa Sala: los dos más antiguos y los tres más modernos (art. 61.3 LOPJ). Al servicio del Tribunal hay un Gabinete Técnico, con un Director y Letrados del Gabinete Técnico, que asiste a la Presidencia y a las Salas en la admisión de asuntos y elabora estudios e informes (art. 61 bis LOPJ).","refs":[{"ref":"Art. 61.3","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Una Sección, formada por el Presidente del Tribunal Supremo, el de la Sala de lo Contencioso-administrativo y cinco Magistrados de esta misma Sala, que serán los dos más antiguos y los tres más modernos, conocerá del recurso de casación para la unificación de doctrina cuando la contradicción se produzca entre sentencias dictadas en única instancia por Secciones distintas de dicha Sala."},{"ref":"Art. 61 bis.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Al servicio del Tribunal Supremo existirá un Gabinete Técnico, que asistirá a la Presidencia y a sus diferentes Salas en los procesos de admisión de los asuntos de que conozcan y mediante la elaboración de estudios e informes que se le soliciten."}]}]},{"n":"4","title":"La Audiencia Nacional: sede, composición y Salas","blocks":[{"text":"La Audiencia Nacional tiene su sede en la villa de Madrid y jurisdicción en toda España (art. 62 LOPJ). Se compone de su Presidente, los Presidentes de Sala y los magistrados que fije la ley; su Presidente tiene la consideración de Presidente de Sala del Tribunal Supremo y es Presidente nato de todas sus Salas (art. 63 LOPJ). Tiene cuatro Salas: de Apelación, de lo Penal, de lo Contencioso-Administrativo y de lo Social; si el número de asuntos lo aconseja, pueden crearse Secciones (art. 64 LOPJ). No tiene Sala de lo Civil.","refs":[{"ref":"Art. 62","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"La Audiencia Nacional, con sede en la villa de Madrid, tiene jurisdicción en toda España."},{"ref":"Art. 63.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"El Presidente de la Audiencia Nacional, que tendrá la consideración de Presidente de Sala del Tribunal Supremo, es el Presidente nato de todas sus Salas."},{"ref":"Art. 64.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"La Audiencia Nacional estará integrada por las siguientes Salas: De Apelación. De lo Penal. De lo Contencioso-Administrativo. De lo Social."}]}]},{"n":"5","title":"Competencia de las Salas de Apelación y de lo Penal de la Audiencia Nacional","blocks":[{"text":"La Sala de Apelación conoce de los recursos de apelación que la ley establezca contra las resoluciones de la Sala de lo Penal (art. 64 bis LOPJ). La Sala de lo Penal enjuicia, salvo que corresponda en primera instancia a la Sección de lo Penal del Tribunal Central de Instancia, las causas por delitos contra el titular de la Corona, su Consorte o Sucesor, altos organismos de la Nación y forma de Gobierno; falsificación de moneda y de medios de pago por organizaciones criminales; grandes defraudaciones que afecten al territorio de más de una Audiencia; narcotráfico y fraudes alimentarios o farmacéuticos de bandas organizadas con efectos en varias Audiencias; delitos cometidos fuera del territorio nacional cuando su enjuiciamiento corresponda a los Tribunales españoles; los delitos que asuma la Fiscalía Europea; y el contrabando de material de defensa y de doble uso. Su competencia se extiende a los delitos conexos (art. 65.1.º LOPJ).","refs":[{"ref":"Art. 64 bis.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"La Sala de Apelación de la Audiencia Nacional conocerá de los recursos de esta clase que establezca la ley contra las resoluciones de la Sala de lo Penal."},{"ref":"Art. 65","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"1.º Del enjuiciamiento, salvo que corresponda en primera instancia a la Sección de lo Penal del Tribunal Central de Instancia, de las causas por los siguientes delitos: a) Delitos contra el titular de la Corona, su Consorte, su Sucesor o Sucesora, altos organismos de la Nación y forma de Gobierno."},{"ref":"Art. 65","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"e) Delitos cometidos fuera del territorio nacional, cuando conforme a las leyes o a los tratados corresponda su enjuiciamiento a los Tribunales españoles."},{"ref":"Art. 65","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"En todo caso, la Sala de lo penal de la Audiencia Nacional extenderá su competencia al conocimiento de los delitos conexos con todos los anteriormente reseñados."}]},{"text":"Además, la Sala de lo Penal conoce de la resolución de los procedimientos judiciales de extradición pasiva, sea cual sea el lugar de residencia o de detención del afectado, y de los recursos sobre instrumentos de reconocimiento mutuo de resoluciones penales en la UE (art. 65.4.º LOPJ). También resuelve los recursos contra las resoluciones de las Secciones de lo Penal, de Instrucción y de Menores del Tribunal Central de Instancia, y los recursos contra las de su Sección de Vigilancia Penitenciaria (art. 65.5.º y 6.º LOPJ). La tramitación de la extradición pasiva y de las órdenes europeas de detención corresponde, en cambio, a la Sección de Instrucción del Tribunal Central de Instancia (tema 8).","refs":[{"ref":"Art. 65","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"4.º De los recursos respecto a los instrumentos de reconocimiento mutuo de resoluciones penales en la Unión Europea que les atribuya la ley, y la resolución de los procedimientos judiciales de extradición pasiva, sea cual fuere el lugar de residencia o en que hubiese tenido lugar la detención del afectado por el procedimiento."},{"ref":"Art. 65","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"5.º De los recursos establecidos en la ley contra las sentencias y otras resoluciones de la Sección de lo Penal, de la Sección de Instrucción, incluidas sus funciones como Jueces de garantías en los delitos de los que conozca la Fiscalía Europea, y de la Sección de Menores, del Tribunal Central de Instancia."}]}]},{"n":"6","title":"Salas de lo Contencioso-Administrativo y de lo Social de la Audiencia Nacional","blocks":[{"text":"La Sala de lo Contencioso-Administrativo de la Audiencia Nacional conoce en única instancia de los recursos contra disposiciones y actos de Ministros y Secretarios de Estado que la ley no atribuya a la Sección de lo Contencioso-Administrativo del Tribunal Central de Instancia, y contra los actos de la Comisión de Vigilancia de Actividades de Financiación del Terrorismo. Conoce también de los recursos devolutivos contra las resoluciones de esa Sección del Tribunal Central de Instancia y de las cuestiones de competencia entre sus magistrados (art. 66 LOPJ).","refs":[{"ref":"Art. 66","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"a) En única instancia, de los recursos contencioso-administrativos contra disposiciones y actos de los Ministros, Ministras, Secretarios y Secretarias de Estado que la ley no atribuya a la Sección de lo Contencioso-Administrativo del Tribunal Central de Instancia."},{"ref":"Art. 66","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"c) De los recursos devolutivos que la ley establezca contra las resoluciones de la Sección de lo Contencioso-Administrativo del Tribunal Central de Instancia."}]},{"text":"La Sala de lo Social de la Audiencia Nacional conoce en única instancia de dos tipos de procesos: la impugnación de convenios colectivos y los conflictos colectivos, en ambos casos cuando su ámbito o efectos superen el territorio de una Comunidad Autónoma (art. 67 LOPJ). Cada Sala resuelve las recusaciones de sus Magistrados (art. 68 LOPJ) y una Sala especial, formada por el Presidente, los Presidentes de Sala y el Magistrado más antiguo y el más moderno de cada una, conoce de la recusación del Presidente, de los Presidentes de Sala o de más de dos Magistrados de una Sala (art. 69 LOPJ).","refs":[{"ref":"Art. 67","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"1.º De los procesos especiales de impugnación de convenios colectivos cuyo ámbito territorial de aplicación sea superior al territorio de una Comunidad Autónoma. 2.º De los procesos sobre conflictos colectivos cuya resolución haya de surtir efecto en un ámbito territorial superior al de una Comunidad Autónoma."},{"ref":"Art. 69","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Una Sala formada por el Presidente de la Audiencia Nacional, los Presidentes de las Salas y el Magistrado más antiguo y el más moderno de cada una, o aquel que, respectivamente, le sustituya, conocerá de los incidentes de recusación del Presidente, de los Presidentes de Sala o de más de dos Magistrados de una Sala."}]}]},{"n":"7","title":"Los Tribunales Superiores de Justicia: organización","blocks":[{"text":"El Tribunal Superior de Justicia culmina la organización judicial en el territorio de la Comunidad Autónoma, sin perjuicio de la jurisdicción del Tribunal Supremo (art. 152.1 CE; art. 70 LOPJ). Toma el nombre de la Comunidad y extiende su jurisdicción a su territorio (art. 71 LOPJ). Tiene tres Salas: de lo Civil y Penal, de lo Contencioso-Administrativo y de lo Social. Su Presidente lo es también de la Sala de lo Civil y Penal y tiene la consideración de Magistrado del Tribunal Supremo mientras ocupa el cargo (art. 72 LOPJ).","refs":[{"ref":"Art. 152.1","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Un Tribunal Superior de Justicia, sin perjuicio de la jurisdicción que corresponde al Tribunal Supremo, culminará la organización judicial en el ámbito territorial de la Comunidad Autónoma."},{"ref":"Art. 72","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"El Tribunal Superior de Justicia estará integrado por las siguientes Salas: de lo Civil y Penal, de lo Contencioso-Administrativo y de lo Social. 2. Se compondrá de un Presidente, que lo será también de su Sala de lo Civil y Penal, y tendrá la consideración de Magistrado del Tribunal Supremo mientras desempeñe el cargo"}]},{"text":"Excepcionalmente pueden crearse Salas de lo Contencioso-Administrativo o de lo Social con jurisdicción limitada a una o varias provincias de la Comunidad, con sede en su capital (art. 78 LOPJ). Las recusaciones contra el Presidente del TSJ, los Presidentes de Sala o de Audiencias Provinciales, o contra dos o más Magistrados de una Sala, Sección o Audiencia, las resuelve una Sala formada por el Presidente, los Presidentes de Sala y el Magistrado más moderno de cada una (art. 77 LOPJ).","refs":[{"ref":"Art. 78","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"podrán crearse, con carácter excepcional, Salas de lo Contencioso-Administrativo o de lo Social con jurisdicción limitada a una o varias provincias de la misma Comunidad Autónoma, en cuya capital tendrán su sede."},{"ref":"Art. 77.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Una Sala constituida por el Presidente del Tribunal Superior de Justicia, los Presidentes de Sala y el Magistrado más moderno de cada una de ellas conocerá de las recusaciones formuladas contra el Presidente, los Presidentes de Sala o de Audiencias Provinciales con sede en la Comunidad Autónoma o de dos o más Magistrados de una Sala o Sección o de una Audiencia Provincial."}]}]},{"n":"8","title":"Competencia de la Sala de lo Civil y Penal del TSJ","blocks":[{"text":"Como Sala de lo Civil conoce de la casación y de la revisión en materia de derecho civil, foral o especial propio de la Comunidad, si el Estatuto lo prevé; de las funciones de apoyo y control del arbitraje y del exequátur de laudos extranjeros; y, en única instancia, de la responsabilidad civil del Presidente y miembros del Consejo de Gobierno y de los miembros de la Asamblea autonómica, cuando no corresponda al Supremo (art. 73.1 y 2 LOPJ).","refs":[{"ref":"Art. 73.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"a) Del recurso de casación que establezca la ley contra resoluciones de órganos jurisdiccionales del orden civil con sede en la comunidad autónoma, siempre que el recurso se funde en infracción de normas del derecho civil, foral o especial, propio de la comunidad, y cuando el correspondiente Estatuto de Autonomía haya previsto esta atribución."},{"ref":"Art. 73.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"a) En única instancia, de las demandas de responsabilidad civil, por hechos cometidos en el ejercicio de sus respectivos cargos, dirigidas contra el Presidente y miembros del Consejo de Gobierno de la comunidad autónoma y contra los miembros de la Asamblea legislativa, cuando tal atribución no corresponda, según los Estatutos de Autonomía, al Tribunal Supremo."}]},{"text":"Como Sala de lo Penal conoce de las causas que los Estatutos reservan al TSJ (aforados autonómicos); de la instrucción y fallo de las causas contra jueces, magistrados y fiscales por delitos cometidos en el ejercicio de su cargo en la Comunidad, si no corresponden al Supremo; y de los recursos de apelación contra las resoluciones dictadas en primera instancia por las Audiencias Provinciales (art. 73.3 LOPJ). Para instruir las causas contra aforados se designa por turno un instructor que no enjuicia (art. 73.4 LOPJ). El texto vigente del art. 73.3.b) sigue diciendo «delitos o faltas», aunque las faltas fueron suprimidas del Código Penal en 2015.","refs":[{"ref":"Art. 73.3","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"b) La instrucción y el fallo de las causas penales contra jueces, magistrados y miembros del Ministerio Fiscal por delitos o faltas cometidos en el ejercicio de su cargo en la comunidad autónoma, siempre que esta atribución no corresponda al Tribunal Supremo. c) El conocimiento de los recursos de apelación contra las resoluciones dictadas en primera instancia por las Audiencias Provinciales, así como el de todos aquellos previstos por las leyes."},{"ref":"Art. 73.4","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Para la instrucción de las causas a que se refieren los párrafos a) y b) del apartado anterior se designará de entre los miembros de la Sala, conforme a un turno preestablecido, un instructor que no formará parte de la misma para enjuiciarlas."}]}]},{"n":"9","title":"Salas de lo Contencioso-Administrativo y de lo Social del TSJ","blocks":[{"text":"La Sala de lo Contencioso-Administrativo conoce en única instancia, entre otros, de los recursos contra actos de las Entidades locales y de las Administraciones autonómicas no atribuidos a las Secciones de lo Contencioso-Administrativo de los Tribunales de Instancia, contra las disposiciones generales autonómicas y locales y contra las resoluciones de los Tribunales Económico-Administrativos Regionales y Locales (art. 74.1 LOPJ). En segunda instancia conoce de las apelaciones contra sentencias y autos de esas Secciones de los Tribunales de Instancia y de los recursos de queja, y también de la revisión de sus sentencias firmes (art. 74.2 y 3 LOPJ).","refs":[{"ref":"Art. 74.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"a) Los actos de las Entidades locales y de las Administraciones de las comunidades autónomas, cuyo conocimiento no esté atribuido a las Secciones de lo Contencioso-Administrativo de los Tribunales de Instancia. b) Las disposiciones generales emanadas de las comunidades autónomas y de las Entidades locales."},{"ref":"Art. 74.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Conocerán, en segunda instancia, de las apelaciones promovidas contra sentencias y autos dictados en las Secciones de lo Contencioso-Administrativo de los Tribunales de Instancia y de los correspondientes recursos de queja."}]},{"text":"La Sala de lo Social conoce en única instancia de las controversias entre trabajadores y empresarios cuyo ámbito supere el de una Sección de lo Social del Tribunal de Instancia sin exceder el de la Comunidad; de los recursos (en especial la suplicación) contra las resoluciones de las Secciones de lo Social y, en materia laboral, de las de lo Mercantil de los Tribunales de Instancia; y de las cuestiones de competencia entre Secciones de lo Social de la Comunidad (art. 75 LOPJ).","refs":[{"ref":"Art. 75","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"1.º En única instancia, de los procesos que la ley establezca sobre controversias que afecten a intereses de los trabajadores y trabajadoras y empresarios y empresarias en ámbito superior al de una Sección de lo Social del Tribunal de Instancia y no superior al de la comunidad autónoma."},{"ref":"Art. 75","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"así como de los recursos de suplicación y los demás que prevé la ley contra las resoluciones de las Secciones de lo Mercantil de los Tribunales de Instancia de la comunidad autónoma en materia laboral"}]}]},{"n":"10","title":"Las Audiencias Provinciales: sede y composición","blocks":[{"text":"Las Audiencias Provinciales tienen su sede en la capital de la provincia, de la que toman su nombre, y extienden su jurisdicción a toda ella; pueden crearse Secciones fuera de la capital, con uno o varios partidos judiciales adscritos (art. 80 LOPJ). Se componen de un Presidente y dos o más magistrados, y pueden tener varias Secciones de igual composición. Si el número de asuntos es escaso, la plantilla puede ser de uno a dos magistrados, completándose con magistrados del TSJ para enjuiciar; y si conviene, las Secciones pueden tener cuatro o más magistrados (art. 81 LOPJ).","refs":[{"ref":"Art. 80.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Las Audiencias Provinciales, que tendrán su sede en la capital de la provincia, de la que tomarán su nombre, extenderán su jurisdicción a toda ella"},{"ref":"Art. 81.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Las Audiencias Provinciales se compondrán de un Presidente y dos o más magistrados."},{"ref":"Art. 81.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Cuando el escaso número de asuntos de que conozca una Audiencia Provincial lo aconseje, podrá constar su plantilla de uno a dos magistrados, incluido el Presidente."}]}]},{"n":"11","title":"Competencia de las Audiencias Provinciales y Jurado","blocks":[{"text":"En el orden penal, la Audiencia Provincial enjuicia las causas por delito no atribuidas a las Secciones de lo Penal de los Tribunales de Instancia ni a otros Tribunales, y resuelve los recursos contra las resoluciones de las Secciones de Instrucción y de lo Penal de la provincia; para los recursos en juicios por delitos leves se constituye con un solo magistrado, por turno de reparto. Conoce también de los recursos penales contra las Secciones de Violencia sobre la Mujer y de Violencia contra la Infancia y la Adolescencia, de Menores y, salvo competencia de la Audiencia Nacional, de Vigilancia Penitenciaria (art. 82.1 LOPJ).","refs":[{"ref":"Art. 82.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"1.º De las causas por delito, a excepción de los que la ley atribuye al conocimiento de las Secciones de lo Penal de los Tribunales de Instancia o de otros Tribunales previstos en esta ley."},{"ref":"Art. 82.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Para el conocimiento de los recursos contra resoluciones de las Secciones de Instrucción de los Tribunales de Instancia en juicios por delitos leves la Audiencia se constituirá con un solo magistrado o magistrada, mediante un turno de reparto."}]},{"text":"En el orden civil resuelve los recursos contra las resoluciones de primera instancia de las Secciones Civiles, de Familia, Infancia y Capacidad, de lo Mercantil (salvo incidentes concursales laborales) y, en materia civil, de Violencia sobre la Mujer y de Violencia contra la Infancia y la Adolescencia. Para los recursos en juicios verbales por razón de la cuantía actúa un solo magistrado por turno de reparto (art. 82.2 LOPJ). Las Secciones mercantiles de la Audiencia de Alicante conocen en segunda instancia, con jurisdicción en toda España, de los recursos sobre marca y dibujos y modelos de la Unión, y se denominan Tribunales de Marca de la Unión Europea (art. 82.3 LOPJ). El juicio del Jurado se celebra en el ámbito de la Audiencia Provincial u otros Tribunales y se rige por la LO del Tribunal del Jurado (art. 83 LOPJ).","refs":[{"ref":"Art. 82.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Para el conocimiento de los recursos contra resoluciones de las Secciones Civiles de los Tribunales de Instancia que se sigan por los trámites del juicio verbal por razón de la cuantía, la Audiencia se constituirá con un solo magistrado o magistrada, mediante un turno de reparto."},{"ref":"Art. 82.3","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"En el ejercicio de esta competencia extenderán su jurisdicción a todo el territorio nacional, y a estos solos efectos se denominarán Tribunales de Marca de la Unión Europea."},{"ref":"Art. 83.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"El juicio del Jurado se celebrará en el ámbito de la Audiencia Provincial u otros Tribunales y en la forma que establezca la ley."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"El Supremo es superior en todos los órdenes salvo en garantías constitucionales.","refs":[{"ref":"Art. 123.1","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Tribunal Supremo, con jurisdicción en toda España, es el órgano jurisdiccional superior en todos los órdenes, salvo lo dispuesto en materia de garantías constitucionales."}]},{"text":"Salas del TS: 1.ª Civil, 2.ª Penal, 3.ª Contencioso, 4.ª Social, 5.ª Militar.","refs":[{"ref":"Art. 55","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Cuarta: De lo Social."}]},{"text":"Aforados nacionales (Diputados, Senadores, Gobierno…): instruye y enjuicia la Sala de lo Penal del TS; el instructor no forma parte de la Sala que juzga.","refs":[{"ref":"Art. 57.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"un instructor, que no formará parte de la misma para enjuiciarlas."}]},{"text":"Ilegalización de partidos políticos: Sala del art. 61 LOPJ.","refs":[{"ref":"Art. 61.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"6.º De los procesos de declaración de ilegalidad y consecuente disolución de los partidos políticos"}]},{"text":"Audiencia Nacional: cuatro Salas (Apelación, Penal, Contencioso y Social); su Presidente se considera Presidente de Sala del TS.","refs":[{"ref":"Art. 63.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"es el Presidente nato de todas sus Salas."}]},{"text":"Extradición pasiva: la resuelve la Sala de lo Penal de la AN, cualquiera que sea el lugar de detención.","refs":[{"ref":"Art. 65","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"la resolución de los procedimientos judiciales de extradición pasiva, sea cual fuere el lugar de residencia o en que hubiese tenido lugar la detención del afectado por el procedimiento."}]},{"text":"Conflictos colectivos de ámbito superior a una Comunidad Autónoma: Sala de lo Social de la AN.","refs":[{"ref":"Art. 67","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"De los procesos sobre conflictos colectivos cuya resolución haya de surtir efecto en un ámbito territorial superior al de una Comunidad Autónoma."}]},{"text":"Apelación contra sentencias penales de primera instancia de las Audiencias Provinciales: Sala de lo Civil y Penal del TSJ.","refs":[{"ref":"Art. 73.3","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"El conocimiento de los recursos de apelación contra las resoluciones dictadas en primera instancia por las Audiencias Provinciales"}]},{"text":"Audiencia Provincial: Presidente y dos o más magistrados; un solo magistrado para recursos en delitos leves y en verbales por cuantía.","refs":[{"ref":"Art. 81.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Las Audiencias Provinciales se compondrán de un Presidente y dos o más magistrados."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666', null, null, null, null
  from public.topics t where t.slug = 'jus-07-ts-an-tsj-ap'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('jus-08-tribunales-instancia', 'Tema 8. De los Tribunales de Instancia y del Tribunal Central de Instancia. Jueces de Paz y Oficinas de Justicia en el Municipio') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-08-tribunales-instancia' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Los Tribunales de Instancia: sede, Secciones y Presidencia (art. 84 LOPJ)"},{"n":"2","title":"Sección Única y Secciones Civil y de Instrucción (arts. 85 y 88 LOPJ)"},{"n":"3","title":"Secciones de Familia, Infancia y Capacidad y de lo Mercantil (arts. 86-87 LOPJ)"},{"n":"3.1","title":"La Sección de lo Mercantil de Alicante: Tribunal de Marca de la Unión Europea (art. 87.10 LOPJ)"},{"n":"4","title":"Secciones de Violencia sobre la Mujer y de Violencia contra la Infancia y la Adolescencia (arts. 89-89 bis LOPJ)"},{"n":"5","title":"Secciones de lo Penal, de Menores y de Vigilancia Penitenciaria (arts. 90-92 LOPJ)"},{"n":"6","title":"Secciones de lo Contencioso-Administrativo y de lo Social (arts. 93-94 LOPJ)"},{"n":"7","title":"El Tribunal Central de Instancia (art. 95 LOPJ)"},{"n":"8","title":"Los jueces y juezas de paz: competencia, elección y nombramiento (arts. 99-103 LOPJ)"},{"n":"9","title":"Las Oficinas de Justicia en los municipios y sus agrupaciones; la Secretaría (arts. 439 ter-439 quinquies LOPJ)"}]'::jsonb, '["Art. 84.1 LOPJ: «Habrá un Tribunal de Instancia en cada partido judicial, con sede en su capital, de la que tomará su nombre.»","Art. 84.2 LOPJ: «Los Tribunales de Instancia estarán integrados por una Sección Única, de Civil y de Instrucción. En los supuestos determinados por la Ley 38/1988, de 28 de diciembre, de Demarcación y de Planta Judicial, el Tribunal de Instancia se integrará por una Sección Civil y otra Sección de Instrucción.»","Art. 84.2 LOPJ: «Además de las anteriores, los Tribunales de Instancia podrán estar integrados por alguna o varias de las siguientes Secciones: a) De Familia, Infancia y Capacidad. b) De lo Mercantil. c) De Violencia sobre la Mujer. d) De Violencia contra la Infancia y la Adolescencia. e) De lo Penal. f) De Menores. g) De Vigilancia Penitenciaria. h) De lo Contencioso-Administrativo. i) De lo Social.»","Art. 85 LOPJ: «Estas Secciones conocerán, en el orden civil: 1.º En primera instancia, de los juicios que no vengan atribuidos por esta ley a otros órganos judiciales.»","Art. 87.1 LOPJ: «Con carácter general, en el Tribunal de Instancia con sede en la capital de cada provincia, existirá una Sección de lo Mercantil con jurisdicción en toda la provincia y sede en su capital.»","Art. 87.10 LOPJ: «A los solos efectos de la competencia específica a que se refiere el párrafo anterior, dicha Sección se denominará Tribunal de Marca de la Unión Europea»","Art. 88.1 a) LOPJ: «De la instrucción de las causas por delito cuyo enjuiciamiento corresponda a las Audiencias Provinciales y a las Secciones de lo Penal de los Tribunales de Instancia, excepto de la instrucción de aquellas causas que sean competencia de las Secciones de Violencia sobre la Mujer o de la Sección de Violencia contra la Infancia y la Adolescencia.»","Art. 89 bis.7 LOPJ: «En caso de que los hechos objeto de instrucción por la Sección de Violencia contra la Infancia y Adolescencia también pudieran ser conocidos por la Sección de Violencia sobre la Mujer, la competencia le corresponderá en todo caso a la última.»","Art. 90.1 LOPJ: «Con carácter general, en el Tribunal de Instancia, con sede en la capital de cada provincia y con jurisdicción en toda ella, existirá una Sección de lo Penal.»","Art. 94.3 LOPJ: «Las Secciones de lo Social conocerán, en primera o única instancia, de los procesos sobre materias propias de este orden jurisdiccional que no estén atribuidos a otros órganos del mismo.»","Art. 95 LOPJ: «En la Villa de Madrid y con jurisdicción en todo el territorio nacional existirá un Tribunal Central de Instancia, que contará con las siguientes Secciones:»","Art. 99 LOPJ: «En cada municipio donde no exista Tribunal de Instancia, y con jurisdicción en el término correspondiente, habrá un juez o una jueza de paz.»","Art. 101.1-2 LOPJ: «Los Jueces de Paz y sus sustitutos serán nombrados para un periodo de cuatro años por la Sala de Gobierno del Tribunal Superior de Justicia correspondiente. El nombramiento recaerá en las personas elegidas por el respectivo Ayuntamiento. 2. Los Jueces de Paz y sus sustitutos serán elegidos por el Pleno del Ayuntamiento, con el voto favorable de la mayoría absoluta de sus miembros, entre las personas que, reuniendo las condiciones legales, así lo soliciten.»","Art. 102 LOPJ: «Podrán ser nombrados Jueces de Paz, tanto titular como sustituto, quienes, aun no siendo licenciados en Derecho, reúnan los requisitos establecidos en esta ley para el ingreso en la Carrera Judicial, y no estén incursos en ninguna de las causas de incapacidad o de incompatibilidad previstas para el desempeño de las funciones judiciales, a excepción del ejercicio de actividades profesionales o mercantiles.»","Art. 439 ter.2 LOPJ: «En cada municipio donde no tenga su sede un Tribunal de Instancia existirá una Oficina de Justicia, que prestará servicios en la localidad donde se encuentre ubicada. En ella el juez o jueza de paz dispondrá de recursos y espacios suficientes y adecuadamente señalizados.»","Art. 439 quinquies.1 LOPJ: «En todo caso, la Secretaría de estas Oficinas de Justicia será desempeñada por personal del Cuerpo de Gestión Procesal y Administrativa, conforme se determine en la correspondiente relación de puestos de trabajo.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Los Tribunales de Instancia: sede y estructura en Secciones","blocks":[{"text":"La LO 1/2025 sustituyó los antiguos Juzgados unipersonales por los Tribunales de Instancia. Hay un Tribunal de Instancia en cada partido judicial, con sede en su capital, de la que toma su nombre (art. 84.1 LOPJ). Con carácter general se integra por una Sección Única, de Civil y de Instrucción; en los casos que fije la Ley de Demarcación y Planta, por una Sección Civil y otra de Instrucción. Además puede tener una o varias de estas Secciones: Familia, Infancia y Capacidad; Mercantil; Violencia sobre la Mujer; Violencia contra la Infancia y la Adolescencia; Penal; Menores; Vigilancia Penitenciaria; Contencioso-Administrativo; y Social (art. 84.2 LOPJ).","refs":[{"ref":"Art. 84.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Habrá un Tribunal de Instancia en cada partido judicial, con sede en su capital, de la que tomará su nombre."},{"ref":"Art. 84.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Los Tribunales de Instancia estarán integrados por una Sección Única, de Civil y de Instrucción. En los supuestos determinados por la Ley 38/1988, de 28 de diciembre, de Demarcación y de Planta Judicial, el Tribunal de Instancia se integrará por una Sección Civil y otra Sección de Instrucción."},{"ref":"Art. 84.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"a) De Familia, Infancia y Capacidad. b) De lo Mercantil. c) De Violencia sobre la Mujer. d) De Violencia contra la Infancia y la Adolescencia. e) De lo Penal. f) De Menores. g) De Vigilancia Penitenciaria. h) De lo Contencioso-Administrativo. i) De lo Social."}]},{"text":"Cada Tribunal de Instancia tiene una Presidencia. Las Secciones solo tienen Presidencia de Sección si se cumplen a la vez tres condiciones: que el Tribunal tenga dos o más Secciones, que la Sección tenga ocho o más plazas judiciales y que el Tribunal sume doce o más plazas (art. 84.3 LOPJ). La jurisdicción la ejercen los jueces y magistrados destinados en las Secciones, cuya adscripción es funcional (art. 84.4 LOPJ). Algunas Secciones pueden extender su jurisdicción a varios partidos de la misma provincia o de provincias limítrofes del mismo TSJ (art. 84.5 LOPJ).","refs":[{"ref":"Art. 84.3","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Cada Tribunal de Instancia contará con una Presidencia. Las Secciones del Tribunal de Instancia contarán con una Presidencia de Sección cuando concurran las siguientes circunstancias: a) Que en el Tribunal de Instancia hubiere dos o más Secciones. b) Que en la Sección de que se trate existan ocho o más plazas judiciales. c) Que el número total de plazas judiciales del Tribunal de Instancia sea igual o superior a doce."},{"ref":"Art. 84.4","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"El ejercicio de la función jurisdiccional corresponde a los jueces, las juezas, los magistrados y las magistradas destinados o destinadas en las diferentes Secciones que integren los Tribunales de Instancia. Su adscripción a las referidas Secciones será funcional."}]}]},{"n":"2","title":"Sección Civil y Sección Única en el orden civil","blocks":[{"text":"Las Secciones Civiles, o las Civiles y de Instrucción que forman una Sección Única, extienden su jurisdicción al partido judicial (art. 85 LOPJ). En el orden civil conocen: en primera instancia, de los juicios no atribuidos a otros órganos (competencia residual); de los actos de jurisdicción voluntaria que prevean las leyes; de los recursos contra las resoluciones de los jueces de paz del partido y de las cuestiones de competencia civil entre ellos; y del reconocimiento y ejecución de sentencias y laudos extranjeros, salvo que corresponda a otra Sección o Tribunal.","refs":[{"ref":"Art. 85","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Estas Secciones conocerán, en el orden civil: 1.º En primera instancia, de los juicios que no vengan atribuidos por esta ley a otros órganos judiciales. 2.º De los actos de jurisdicción voluntaria en los términos que prevean las leyes. 3.º De los recursos que establezca la ley contra las resoluciones de los jueces y las juezas de paz del partido. 4.º De las cuestiones de competencia en materia civil entre los jueces y las juezas de paz del partido."}]}]},{"n":"3","title":"Sección de Instrucción y Sección Única en el orden penal","blocks":[{"text":"En el orden penal, las Secciones de Instrucción o las Únicas instruyen las causas por delito que enjuician las Audiencias Provinciales y las Secciones de lo Penal, salvo las que correspondan a las Secciones de Violencia sobre la Mujer o contra la Infancia y la Adolescencia; dictan sentencia de conformidad y en los procesos por aceptación de decreto; conocen y fallan los juicios por delito leve (salvo los de los jueces de paz o de las Secciones de violencia); y tramitan los procedimientos de habeas corpus. También resuelven los recursos contra resoluciones de los jueces de paz y adoptan, estando de guardia, la orden de protección cuando no pueda hacerlo la Sección especializada (art. 88.1 LOPJ).","refs":[{"ref":"Art. 88.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"a) De la instrucción de las causas por delito cuyo enjuiciamiento corresponda a las Audiencias Provinciales y a las Secciones de lo Penal de los Tribunales de Instancia, excepto de la instrucción de aquellas causas que sean competencia de las Secciones de Violencia sobre la Mujer o de la Sección de Violencia contra la Infancia y la Adolescencia."},{"ref":"Art. 88.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"c) Del conocimiento y fallo de los juicios por delito leve, salvo los que sean competencia de los jueces y juezas de paz o de las Secciones de Violencia sobre la Mujer o de la Sección de Violencia contra la Infancia y la Adolescencia. d) De los procedimientos de habeas corpus."}]},{"text":"Además autorizan el internamiento de extranjeros en los centros de internamiento y controlan su estancia en ellos y en las salas de inadmisión de fronteras, y conocen de las quejas de los internos que afecten a sus derechos fundamentales (art. 88.2 LOPJ). Excepcionalmente, el CGPJ, con informe de la Fiscalía General del Estado, puede agrupar las Secciones de Instrucción de partidos limítrofes de una provincia ante un aumento destacado de asuntos por narcotráfico o trata (art. 88.4 LOPJ).","refs":[{"ref":"Art. 88.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Asimismo, las Secciones de Instrucción y las Secciones Únicas conocerán de la autorización del internamiento de extranjeros en los centros de internamiento, así como del control de la estancia de éstos en los mismos y en las salas de inadmisión de fronteras."}]}]},{"n":"4","title":"Sección de Familia, Infancia y Capacidad","blocks":[{"text":"Se crea en el Tribunal de Instancia cuando la carga de trabajo lo aconseje y extiende su jurisdicción a todo el partido; el Gobierno puede establecer Secciones que abarquen dos o más partidos de la misma provincia (art. 86.1 y 2 LOPJ). Si no existe y el Tribunal tiene Sección Única con una sola plaza, el juez de esa plaza asume los asuntos de familia (art. 86.4 LOPJ). Su jurisdicción es exclusiva y excluyente, entre otras materias, en lo relativo al matrimonio y su régimen económico, guarda y custodia y alimentos de hijos menores, filiación, alimentos entre parientes, relaciones paternofiliales, medidas de apoyo a personas con discapacidad (incluidos los internamientos no voluntarios por trastorno psíquico), protección del menor y expedientes de jurisdicción voluntaria de personas y familia (art. 86.5 LOPJ).","refs":[{"ref":"Art. 86.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Cuando se estime conveniente, en función de la carga de trabajo, se creará en el Tribunal de Instancia una Sección de Familia, Infancia y Capacidad, que extenderá su jurisdicción a todo el partido judicial."},{"ref":"Art. 86.5","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"En todo caso, la jurisdicción de estas Secciones será exclusiva y excluyente en las siguientes materias:"},{"ref":"Art. 86.5","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"g) Las que versen sobre adopción de medidas judiciales de apoyo a personas con discapacidad, incluyendo los internamientos no voluntarios por razón de trastorno psíquico."}]}]},{"n":"5","title":"Sección de lo Mercantil y el Tribunal de Marca de la Unión Europea","blocks":[{"text":"Con carácter general existe una Sección de lo Mercantil en el Tribunal de Instancia de la capital de cada provincia, con jurisdicción en toda ella (art. 87.1 LOPJ). Conoce de las cuestiones civiles sobre propiedad intelectual e industrial, competencia desleal y publicidad, sociedades mercantiles y cooperativas, transporte, derecho marítimo y aéreo, de las acciones de defensa de la competencia (arts. 101 y 102 TFUE) y de los recursos contra calificaciones negativas de los registradores mercantiles (art. 87.6 LOPJ). Es también la Sección del concurso de acreedores, cualquiera que sea la condición civil o mercantil del deudor (art. 87.7 LOPJ).","refs":[{"ref":"Art. 87.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Con carácter general, en el Tribunal de Instancia con sede en la capital de cada provincia, existirá una Sección de lo Mercantil con jurisdicción en toda la provincia y sede en su capital."},{"ref":"Art. 87.7","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Las Secciones de lo Mercantil conocerán, además, de cuantas cuestiones sean de la competencia del orden jurisdiccional civil en materia de concurso de acreedores o acreedoras, cualquiera que sea la condición civil o mercantil de la persona deudora"}]},{"text":"La Sección de lo Mercantil del Tribunal de Instancia de Alicante, además de su competencia provincial, tiene competencia exclusiva en primera instancia, con jurisdicción en todo el territorio nacional, para las acciones basadas en el Reglamento (UE) 2017/1001 sobre la marca de la Unión Europea y en el Reglamento (CE) 6/2002 sobre dibujos y modelos comunitarios. A esos solos efectos se denomina Tribunal de Marca de la Unión Europea (art. 87.10 LOPJ). La segunda instancia corresponde a las Secciones mercantiles de la Audiencia Provincial de Alicante (art. 82.3 LOPJ).","refs":[{"ref":"Art. 87.10","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"la Sección de lo Mercantil del Tribunal de Instancia de Alicante tendrá competencia exclusiva para conocer en primera instancia con jurisdicción en todo el territorio nacional de aquellas acciones que se ejerciten al amparo de lo establecido en el Reglamento (UE) 2017/1001 del Parlamento y del Consejo, de 14 de junio de 2017, sobre la marca de la Unión Europea"},{"ref":"Art. 87.10","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"A los solos efectos de la competencia específica a que se refiere el párrafo anterior, dicha Sección se denominará Tribunal de Marca de la Unión Europea"}]}]},{"n":"6","title":"Secciones de Violencia sobre la Mujer y de Violencia contra la Infancia y la Adolescencia","blocks":[{"text":"La Sección de Violencia sobre la Mujer se crea cuando la carga de trabajo lo aconseje, con jurisdicción en todo el partido (art. 89.2 LOPJ). En el orden penal instruye los procesos por homicidio, aborto, lesiones, delitos contra la libertad, la integridad moral, la libertad sexual, la intimidad o el honor, o cualquier delito con violencia o intimidación, cometidos contra quien sea o haya sido esposa del autor o mujer ligada a él por análoga relación de afectividad, aun sin convivencia; adopta órdenes de protección; enjuicia los delitos leves que le atribuya la ley; y dicta sentencias de conformidad (art. 89.5 LOPJ). Tiene además competencia civil exclusiva y excluyente en asuntos de familia cuando concurren violencia de género o sexual y actuaciones penales iniciadas ante ella (art. 89.7 LOPJ), y en estos casos está vedada la mediación y demás medios adecuados de solución de controversias (art. 89.9 LOPJ).","refs":[{"ref":"Art. 89.5","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"a) De la instrucción de los procesos para exigir responsabilidad penal por los delitos recogidos en los Títulos del Código Penal relativos a homicidio, aborto, lesiones, lesiones al feto, delitos contra la libertad, delitos contra la integridad moral, contra la libertad e indemnidad sexual, contra la intimidad y el derecho a la propia imagen, contra el honor o cualquier otro delito cometido con violencia o intimidación, siempre que se hubiesen cometido contra quien sea o haya sido su esposa"},{"ref":"Art. 89.9","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"En todos estos casos está vedada la utilización de los medios adecuados de solución de controversias."}]},{"text":"La Sección de Violencia contra la Infancia y la Adolescencia instruye los procesos por homicidio, lesiones, delitos contra la libertad, la integridad moral, la libertad sexual, las relaciones familiares y otros delitos violentos cuando la víctima sea niño, niña o adolescente, además de la trata con al menos una víctima menor y el quebrantamiento cuando el ofendido sea menor (art. 89 bis.5 LOPJ). Si los hechos pudieran ser también de la Sección de Violencia sobre la Mujer, la competencia corresponde en todo caso a esta última (art. 89 bis.7 LOPJ).","refs":[{"ref":"Art. 89 bis.5","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"a) Homicidio, aborto, lesiones o lesiones al feto, cometidos contra niños, niñas y adolescentes."},{"ref":"Art. 89 bis.7","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"En caso de que los hechos objeto de instrucción por la Sección de Violencia contra la Infancia y Adolescencia también pudieran ser conocidos por la Sección de Violencia sobre la Mujer, la competencia le corresponderá en todo caso a la última."}]}]},{"n":"7","title":"Secciones de lo Penal, de Menores y de Vigilancia Penitenciaria","blocks":[{"text":"Con carácter general hay una Sección de lo Penal en el Tribunal de Instancia de la capital de provincia, con jurisdicción en toda ella, aunque pueden crearse en otras poblaciones. Enjuicia las causas por delito que la ley determine y ejecuta las sentencias por delito grave o menos grave dictadas por las Secciones de Instrucción y de Violencia (art. 90 LOPJ). La Sección de Menores, también provincial con carácter general, ejerce las funciones que fijen las leyes respecto de los menores que hayan cometido hechos tipificados como delito o delito leve (art. 91 LOPJ).","refs":[{"ref":"Art. 90.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Con carácter general, en el Tribunal de Instancia, con sede en la capital de cada provincia y con jurisdicción en toda ella, existirá una Sección de lo Penal."},{"ref":"Art. 90.4","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Corresponde asimismo a las Secciones de lo Penal la ejecución de las sentencias dictadas en causas por delito grave o menos grave por las Secciones de Instrucción, Secciones de Violencia sobre la Mujer y Secciones de Violencia contra la Infancia y la Adolescencia"},{"ref":"Art. 91.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Corresponde a las Secciones de Menores de los Tribunales de Instancia el ejercicio de las funciones que establezcan las leyes para con los menores que hubieren incurrido en conductas tipificadas por la ley como delito o delito leve"}]},{"text":"La Sección de Vigilancia Penitenciaria, ubicada con carácter general en la capital de provincia dentro del orden penal, tiene las funciones jurisdiccionales en ejecución de penas privativas de libertad y medidas de seguridad, el control jurisdiccional de la potestad disciplinaria de las autoridades penitenciarias y el amparo de los derechos y beneficios de los internos (art. 92.1 LOPJ). Su número y ámbito se fijan en la Ley de Demarcación y Planta atendiendo sobre todo a los establecimientos penitenciarios existentes (art. 92.3 LOPJ).","refs":[{"ref":"Art. 92.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"existirá una Sección de Vigilancia Penitenciaria, que tendrá las funciones jurisdiccionales previstas en la ley en materia de ejecución de penas privativas de libertad y medidas de seguridad, emisión y ejecución de los instrumentos de reconocimiento mutuo de resoluciones penales en la Unión Europea que les atribuya la ley, control jurisdiccional de la potestad disciplinaria de las autoridades penitenciarias"},{"ref":"Art. 92.3","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"se determinará en la Ley de Demarcación y Planta Judicial, atendiendo principalmente a los establecimientos penitenciarios existentes y a la clase de éstos."}]}]},{"n":"8","title":"Secciones de lo Contencioso-Administrativo y de lo Social","blocks":[{"text":"La Sección de lo Contencioso-Administrativo existe, con carácter general, en el Tribunal de Instancia de la capital de provincia con jurisdicción en toda ella. Conoce en primera o única instancia de los recursos contra los actos que la ley le atribuya expresamente y autoriza mediante auto la entrada en domicilios para ejecutar forzosamente actos de la Administración, salvo medidas de protección de menores (art. 93 LOPJ). La Sección de lo Social, también provincial con carácter general, conoce en primera o única instancia de los procesos de su orden no atribuidos a otros órganos (art. 94 LOPJ).","refs":[{"ref":"Art. 93.4 y 93.5","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Las Secciones de lo Contencioso-Administrativo conocerán, en primera o única instancia, de los recursos contencioso-administrativos contra actos que expresamente les atribuya la ley. 5. También les corresponde autorizar, mediante auto, la entrada en los domicilios y en los restantes edificios o lugares cuyo acceso requiera el consentimiento de su titular, cuando ello proceda para la ejecución forzosa de actos de la Administración"},{"ref":"Art. 94.3","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Las Secciones de lo Social conocerán, en primera o única instancia, de los procesos sobre materias propias de este orden jurisdiccional que no estén atribuidos a otros órganos del mismo."}]}]},{"n":"9","title":"El Tribunal Central de Instancia","blocks":[{"text":"Con sede en la Villa de Madrid y jurisdicción en todo el territorio nacional, el Tribunal Central de Instancia tiene cinco Secciones (art. 95 LOPJ). La Sección de Instrucción instruye las causas que enjuicia la Sala de lo Penal de la Audiencia Nacional o la propia Sección de lo Penal del Tribunal Central, y tramita los expedientes de órdenes europeas de detención y entrega y los procedimientos de extradición pasiva; en ella actúan los jueces de garantías ante la Fiscalía Europea. La Sección de lo Penal enjuicia, cuando así lo dispongan las leyes procesales, causas por los delitos del artículo 65 LOPJ. Completan el Tribunal las Secciones de Menores, de Vigilancia Penitenciaria (para delitos competencia de la Audiencia Nacional, con competencia preferente y excluyente) y de lo Contencioso-Administrativo (actos de autoridades y organismos con competencia en todo el territorio nacional).","refs":[{"ref":"Art. 95","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"En la Villa de Madrid y con jurisdicción en todo el territorio nacional existirá un Tribunal Central de Instancia, que contará con las siguientes Secciones:"},{"ref":"Art. 95","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"a) Sección de Instrucción, que instruirá las causas cuyo enjuiciamiento corresponda a la Sala de lo Penal de la Audiencia Nacional o, en su caso, a la Sección de lo Penal del propio Tribunal Central de Instancia y tramitará los expedientes de ejecución de las órdenes europeas de detención y entrega, los procedimientos de extradición pasiva"},{"ref":"Art. 95","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"e) Sección de lo Contencioso-Administrativo, que conocerá, en primera o única instancia, de los recursos contencioso-administrativos contra disposiciones y actos emanados de autoridades, organismos, órganos y entidades públicas con competencia en todo el territorio nacional, en los términos que la ley establezca."}]}]},{"n":"10","title":"Los jueces y juezas de paz: competencia y elección","blocks":[{"text":"En cada municipio donde no exista Tribunal de Instancia hay un juez o jueza de paz, con jurisdicción en su término (art. 99 LOPJ). En el orden civil conocen en primera instancia, fallan y ejecutan los procesos que la ley determine; en el penal, los procesos por delito leve que la ley les atribuya, y pueden intervenir en actuaciones de prevención o por delegación (art. 100 LOPJ). Ojo: el texto vigente de los artículos 100, 101.3, 101.5 y 103.1 todavía habla de «Juzgados de Paz» y de «Juez de Primera Instancia e Instrucción», porque la LO 1/2025 no los adaptó; esos órganos han sido sustituidos por los Tribunales de Instancia.","refs":[{"ref":"Art. 99","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"En cada municipio donde no exista Tribunal de Instancia, y con jurisdicción en el término correspondiente, habrá un juez o una jueza de paz."},{"ref":"Art. 100","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Los Juzgados de Paz conocerán, en el orden civil, de la sustanciación en primera instancia, fallo y ejecución de los procesos que la ley determine y cumplirán también las demás funciones que la ley les atribuya. 2. En el orden penal, conocerán en primera instancia de los procesos por delito leve que les atribuya la ley."}]},{"text":"Los jueces de paz y sus sustitutos son nombrados por cuatro años por la Sala de Gobierno del TSJ, a favor de las personas elegidas por el Ayuntamiento. Los elige el Pleno municipal por mayoría absoluta entre quienes lo soliciten y reúnan las condiciones legales; si nadie lo solicita, el Pleno elige libremente. Si el Ayuntamiento no hace la propuesta en tres meses desde la vacante, o el propuesto no reúne las condiciones (oído el Fiscal), designa la Sala de Gobierno. Juran ante el juez del partido y toman posesión ante quien ejerza la jurisdicción (art. 101 LOPJ).","refs":[{"ref":"Art. 101.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Los Jueces de Paz y sus sustitutos serán nombrados para un periodo de cuatro años por la Sala de Gobierno del Tribunal Superior de Justicia correspondiente. El nombramiento recaerá en las personas elegidas por el respectivo Ayuntamiento."},{"ref":"Art. 101.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Los Jueces de Paz y sus sustitutos serán elegidos por el Pleno del Ayuntamiento, con el voto favorable de la mayoría absoluta de sus miembros, entre las personas que, reuniendo las condiciones legales, así lo soliciten. Si no hubiere solicitante, el pleno elegirá libremente."},{"ref":"Art. 101.4","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Si en el plazo de tres meses, a contar desde que se produjera la vacante en un Juzgado de Paz, el Ayuntamiento correspondiente no efectuase la propuesta prevenida en los apartados anteriores, la Sala de Gobierno del Tribunal Superior de Justicia procederá a designar al Juez de Paz."}]},{"text":"Pueden ser jueces de paz quienes, aun sin ser licenciados en Derecho, reúnan los requisitos de ingreso en la Carrera Judicial y no estén incursos en incapacidad o incompatibilidad, salvo el ejercicio de actividades profesionales o mercantiles, que sí les está permitido (art. 102 LOPJ). Cesan por el transcurso del mandato y por las mismas causas que los jueces de carrera (art. 103.2 LOPJ).","refs":[{"ref":"Art. 102","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Podrán ser nombrados Jueces de Paz, tanto titular como sustituto, quienes, aun no siendo licenciados en Derecho, reúnan los requisitos establecidos en esta ley para el ingreso en la Carrera Judicial, y no estén incursos en ninguna de las causas de incapacidad o de incompatibilidad previstas para el desempeño de las funciones judiciales, a excepción del ejercicio de actividades profesionales o mercantiles."},{"ref":"Art. 103.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Los Jueces de Paz y los sustitutos, en su caso, cesarán por el transcurso de su mandato y por las mismas causas que los Jueces de carrera en cuanto les sean de aplicación."}]}]},{"n":"11","title":"Oficinas de Justicia en el municipio, agrupaciones y Secretaría","blocks":[{"text":"Las Oficinas de Justicia en los municipios son unidades que, sin integrarse en la Oficina judicial, prestan servicios a la ciudadanía del municipio. Existe una en cada municipio sin sede de Tribunal de Instancia, y en ella el juez de paz dispone de recursos y espacios. Sus instalaciones y medios corren a cargo del Ayuntamiento, salvo gestión del Ministerio o la comunidad autónoma, que facilitan los sistemas informáticos (art. 439 ter LOPJ). Prestan asistencia al juez de paz, practican los actos de comunicación con los residentes que no se hayan podido hacer por medios electrónicos y colaboran con el Registro Civil; cuando los medios lo permitan, también videoconferencias, recepción de solicitudes de justicia gratuita y otros servicios (art. 439 quater LOPJ).","refs":[{"ref":"Art. 439 ter.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Las Oficinas de Justicia en los municipios son aquellas unidades que, sin estar integradas en la estructura de la Oficina judicial, se constituyen en el ámbito de la organización de la Administración de Justicia para la prestación de servicios a la ciudadanía de los respectivos municipios."},{"ref":"Art. 439 ter.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"En cada municipio donde no tenga su sede un Tribunal de Instancia existirá una Oficina de Justicia, que prestará servicios en la localidad donde se encuentre ubicada."},{"ref":"Art. 439 quater.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"a) La asistencia al juez o la jueza de paz del municipio en el ejercicio de las funciones que tenga atribuidas legalmente. b) La práctica de los actos de comunicación procesal con quienes residan en el municipio o municipios para los que presten sus servicios, siempre que los mismos no se hayan podido practicar por medios electrónicos."}]},{"text":"Las Oficinas de municipios de más de 7.000 habitantes, y aquellas cuya carga de trabajo lo justifique, están servidas por funcionarios de la Administración de Justicia, y su Secretaría la desempeña en todo caso personal del Cuerpo de Gestión Procesal y Administrativa (art. 439 quinquies.1 LOPJ). El Ministerio o las comunidades autónomas pueden crear agrupaciones de Oficinas de municipios limítrofes de un mismo partido judicial, con un municipio cabecera dotado de personal de Justicia que atiende a todas; en los demás municipios, el Ayuntamiento nombra personal propio o persona idónea mayor de edad para auxiliar (art. 439 quinquies.3 LOPJ).","refs":[{"ref":"Art. 439 quinquies.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Las Oficinas de Justicia de municipios de más de 7.000 habitantes y aquellas otras en las que la carga de trabajo lo justifique estarán servidas por funcionarios de los Cuerpos al servicio de la Administración de Justicia"},{"ref":"Art. 439 quinquies.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"En todo caso, la Secretaría de estas Oficinas de Justicia será desempeñada por personal del Cuerpo de Gestión Procesal y Administrativa, conforme se determine en la correspondiente relación de puestos de trabajo."},{"ref":"Art. 439 quinquies.3","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"podrán establecer agrupaciones de Oficinas de Justicia de municipios limítrofes de un mismo partido judicial para la prestación a la ciudadanía de los servicios a que se refiere el artículo anterior. En tales casos se determinará el municipio cabecera de la agrupación."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Un Tribunal de Instancia por partido judicial, con sede en su capital; por regla general, Sección Única de Civil y de Instrucción.","refs":[{"ref":"Art. 84.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Habrá un Tribunal de Instancia en cada partido judicial"}]},{"text":"Presidencia de Sección: dos o más Secciones, ocho o más plazas en la Sección y doce o más en el Tribunal.","refs":[{"ref":"Art. 84.3","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"b) Que en la Sección de que se trate existan ocho o más plazas judiciales."}]},{"text":"Habeas corpus: Secciones de Instrucción o Únicas.","refs":[{"ref":"Art. 88.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"d) De los procedimientos de habeas corpus."}]},{"text":"Tribunal de Marca de la Unión Europea: Sección de lo Mercantil del Tribunal de Instancia de Alicante, con jurisdicción en toda España.","refs":[{"ref":"Art. 87.10","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"dicha Sección se denominará Tribunal de Marca de la Unión Europea"}]},{"text":"Conflicto entre Violencia contra la Infancia y Violencia sobre la Mujer: prevalece siempre Violencia sobre la Mujer.","refs":[{"ref":"Art. 89 bis.7","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"la competencia le corresponderá en todo caso a la última."}]},{"text":"Tribunal Central de Instancia: Madrid, jurisdicción nacional; la extradición pasiva y las órdenes europeas de detención las tramita su Sección de Instrucción.","refs":[{"ref":"Art. 95","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"En la Villa de Madrid y con jurisdicción en todo el territorio nacional existirá un Tribunal Central de Instancia"}]},{"text":"Juez de paz: cuatro años; lo elige el Pleno del Ayuntamiento por mayoría absoluta y lo nombra la Sala de Gobierno del TSJ.","refs":[{"ref":"Art. 101.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"con el voto favorable de la mayoría absoluta de sus miembros"}]},{"text":"Sin propuesta municipal en tres meses desde la vacante, designa la Sala de Gobierno del TSJ.","refs":[{"ref":"Art. 101.4","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Si en el plazo de tres meses, a contar desde que se produjera la vacante en un Juzgado de Paz"}]},{"text":"Oficinas de Justicia de más de 7.000 habitantes: Secretaría a cargo del Cuerpo de Gestión Procesal y Administrativa.","refs":[{"ref":"Art. 439 quinquies.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Las Oficinas de Justicia de municipios de más de 7.000 habitantes"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666', null, null, null, null
  from public.topics t where t.slug = 'jus-08-tribunales-instancia'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('jus-09-carta-derechos', 'Tema 9. La carta de Derechos de los Ciudadanos ante la Justicia. El Derecho a la Justicia Gratuita') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-09-carta-derechos' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"La Carta de Derechos de los Ciudadanos ante la Justicia (texto no disponible en el BOE consolidado: se estudian los derechos equivalentes de la LOPJ)"},{"n":"2","title":"Derechos de información: publicidad de las actuaciones y acceso a los procedimientos (arts. 232-235 LOPJ)"},{"n":"3","title":"Derechos lingüísticos (art. 231 LOPJ)"},{"n":"4","title":"Derechos frente a los profesionales: Abogados, Procuradores y Graduados Sociales (arts. 542-546 LOPJ)"},{"n":"5","title":"El derecho a la justicia gratuita: fundamento constitucional y objeto (art. 119 CE; art. 1 Ley 1/1996)"},{"n":"5.1","title":"Ámbito personal y requisitos económicos (arts. 2-5 Ley 1/1996)"},{"n":"5.2","title":"Contenido material y extensión temporal (arts. 6-8 Ley 1/1996)"},{"n":"6","title":"Comisiones de Asistencia Jurídica Gratuita y procedimiento de reconocimiento (arts. 9-21 bis Ley 1/1996)"},{"n":"7","title":"Designación de abogado y procurador de oficio, insostenibilidad y costas (arts. 27-36 Ley 1/1996)"}]'::jsonb, '["Art. 232.1 LOPJ: «Las actuaciones judiciales serán públicas, con las excepciones que prevean las leyes de procedimiento.»","Art. 234.1 LOPJ: «Los Letrados de la Administración de Justicia y funcionarios competentes de la oficina judicial y de la oficina fiscal facilitarán a los interesados cuanta información soliciten sobre el estado de las actuaciones procesales, que podrán examinar y conocer, salvo que sean o hubieren sido declaradas secretas o reservadas conforme a la ley.»","Art. 234.2 LOPJ: «Las partes y cualquier persona que acredite un interés legítimo y directo tendrán derecho a acceder a la información existente en los procedimientos judiciales»","Art. 231.1 LOPJ: «En todas las actuaciones judiciales, los Jueces, Magistrados, Fiscales, Secretarios y demás funcionarios de Juzgados y Tribunales usarán el castellano, lengua oficial del Estado.»","Art. 231.3 LOPJ: «Las partes, sus representantes y quienes les dirijan, así como los testigos y peritos, podrán utilizar la lengua que sea también oficial en la Comunidad Autónoma en cuyo territorio tengan lugar las actuaciones judiciales, tanto en manifestaciones orales como escritas.»","Art. 542.1 LOPJ: «Corresponde en exclusiva la denominación y función de abogado al licenciado en Derecho que ejerza profesionalmente la dirección y defensa de las partes en toda clase de procesos, o el asesoramiento y consejo jurídico.»","Art. 543.1 LOPJ: «Corresponde exclusivamente a los procuradores la representación de las partes en todo tipo de procesos, salvo cuando la ley autorice otra cosa.»","Art. 545.2 LOPJ: «En los procedimientos laborales y de Seguridad Social la representación técnica podrá ser ostentada por un Graduado Social, al que serán de aplicación las obligaciones inherentes a su función»","Art. 546.2 LOPJ: «Los Abogados, Procuradores y Graduados Sociales están sujetos en el ejercicio de su profesión a responsabilidad civil, penal y disciplinaria, según proceda.»","Art. 119 CE: «La justicia será gratuita cuando así lo disponga la ley y, en todo caso, respecto de quienes acrediten insuficiencia de recursos para litigar.»","Art. 2 a) Ley 1/1996: «Los ciudadanos españoles, los nacionales de los demás Estados miembros de la Unión Europea y los extranjeros que se encuentren en España, cuando acrediten insuficiencia de recursos para litigar.»","Art. 3.1 Ley 1/1996: «Se reconocerá el derecho de asistencia jurídica gratuita a aquellas personas físicas que careciendo de patrimonio suficiente cuenten con unos recursos e ingresos económicos brutos, computados anualmente por todos los conceptos y por unidad familiar, que no superen los siguientes umbrales: a) Dos veces el indicador público de renta de efectos múltiples vigente en el momento de efectuar la solicitud cuando se trate de personas no integradas en ninguna unidad familiar.»","Art. 7.1 Ley 1/1996: «La asistencia jurídica gratuita en el transcurso de una misma instancia se extiende a todos sus trámites e incidencias, incluida la ejecución, pero no podrá aplicarse a un proceso distinto.»","Art. 9 Ley 1/1996: «En cada capital de provincia, en las ciudades de Ceuta y Melilla y en cada isla en que existan uno o más partidos judiciales, se constituirá una Comisión de Asistencia Jurídica Gratuita como órgano responsable, en su correspondiente ámbito territorial, de efectuar el reconocimiento del derecho regulado en la presente Ley.»","Art. 16.1 Ley 1/1996: «La solicitud de reconocimiento del derecho a la asistencia jurídica gratuita no suspenderá el curso del proceso o expediente administrativo.»","Art. 32 Ley 1/1996: «Cuando el Abogado designado para un proceso considere insostenible la pretensión que pretende hacerse valer, deberá comunicarlo a la Comisión de Asistencia Jurídica Gratuita, dentro de los 15 días siguientes a su designación, exponiendo los motivos jurídicos en los que fundamenta su decisión.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"La Carta de Derechos de los Ciudadanos ante la Justicia: origen, estructura y eficacia","blocks":[{"text":"La Carta nace del Pacto de Estado para la Reforma de la Justicia de 28 de mayo de 2001, que la incluía entre sus prioridades. La redactó un Grupo de Trabajo de la Comisión de Seguimiento del Pacto de Estado, con representantes de los grupos parlamentarios y del Ministerio de Justicia, y fue aprobada por el Pleno del Congreso como Proposición no de Ley en 2002; no es una ley ni figura en el BOE consolidado. Tiene tres partes: una Justicia moderna y abierta a los ciudadanos; una Justicia que protege a los más débiles; y una relación de confianza con Abogados y Procuradores, más un apartado final sobre su eficacia.","refs":[{"ref":"Preámbulo","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"Tal es, precisamente, el objeto y finalidad del Pacto de Estado para la Reforma de la Justicia firmado el 28 de mayo de 2001."},{"ref":"Preámbulo","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"Entre las prioridades del Pacto de Estado figura la elaboración de una Carta de Derechos de los Ciudadanos ante la Justicia que atienda a los principios de transparencia, información y atención adecuada y que establezca los derechos de los usuarios de la Justicia."}]},{"text":"Los ciudadanos pueden exigir el cumplimiento de los derechos de la Carta, que vincula a Jueces y Magistrados, Fiscales, Secretarios Judiciales (hoy Letrados de la Administración de Justicia), médicos forenses, funcionarios, Abogados, Procuradores y demás cooperadores de la Justicia. El Congreso de los Diputados, a través de la Comisión de Justicia e Interior, hace su seguimiento y evaluación permanente, y la memoria anual del CGPJ a las Cortes debe incluir una referencia detallada a las quejas y sugerencias de los ciudadanos (apartados de «Eficacia»).","refs":[{"ref":"Eficacia 1","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"Los ciudadanos tienen derecho a exigir el cumplimiento de los derechos reconocidos en esta Carta. Estarán vinculados a ella Jueces y Magistrados, Fiscales, Secretarios Judiciales, médicos forenses, funcionarios públicos, Abogados, Procuradores y demás personas e Instituciones que cooperan con la Administración de Justicia."},{"ref":"Eficacia 3","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"El Congreso de los Diputados, a través de la Comisión de Justicia e Interior, llevará a cabo un seguimiento y evaluación permanente del desarrollo y cumplimiento de esta Carta"}]}]},{"n":"2","title":"Derechos de información: una justicia transparente","blocks":[{"text":"El ciudadano tiene derecho a información general y actualizada sobre el funcionamiento de juzgados y tribunales y sobre los requisitos de los procedimientos; para ello se impulsan las Oficinas de Atención al Ciudadano en todo el territorio y los horarios de atención deben estar en lugar visible (apdo. 1). También tiene derecho a información transparente sobre el estado y la actividad de todos los órganos jurisdiccionales, que el Ministerio de Justicia, las comunidades autónomas competentes y el CGPJ canalizan en el marco de un plan de transparencia (apdo. 2), y a conocer el contenido actualizado de las leyes españolas y de la Unión Europea mediante un sistema electrónico accesible (apdo. 3).","refs":[{"ref":"Apdo. 1","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"Se impulsará la creación y dotación material de Oficinas de Atención al Ciudadano, asegurando su implantación en todo el territorio nacional."},{"ref":"Apdo. 2","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"El Ministerio de Justicia y las Comunidades Autónomas con competencias en la materia, así como el Consejo General del Poder Judicial canalizarán esta información para facilitar su consulta en el marco de un plan de transparencia."}]},{"text":"Quien tenga interés legítimo puede conocer el contenido y estado de sus procesos y acceder a documentos, libros, archivos y registros judiciales no reservados; si se deniega el acceso a una información procesal, las autoridades y funcionarios deben exponer por escrito los motivos al ciudadano que lo pida (apdo. 4 Carta). La LOPJ recoge estos derechos: las actuaciones judiciales son públicas, con las excepciones de las leyes procesales (art. 232.1), y el LAJ vela por que se publique en lugar visible, el primer día hábil de cada semana, la relación de señalamientos (art. 232.2). Excepcionalmente, por orden público o protección de derechos, el juez puede declarar secretas actuaciones mediante resolución motivada (art. 232.3).","refs":[{"ref":"Apdo. 4","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"Las autoridades y funcionarios expondrán por escrito al ciudadano que lo solicite los motivos por los que se deniega el acceso a una información de carácter procesal."},{"ref":"Art. 232.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"publiquen en un lugar visible al público, el primer día hábil de cada semana, la relación de señalamientos correspondientes a su respectivo órgano judicial"}]},{"text":"Los Letrados de la Administración de Justicia y los funcionarios competentes de la oficina judicial y fiscal deben facilitar a los interesados información sobre el estado de las actuaciones, salvo que sean o hayan sido declaradas secretas o reservadas (art. 234.1 LOPJ). Las partes y quien acredite interés legítimo y directo pueden consultar escritos y documentos y obtener testimonios y certificados (art. 234.2). Si quien accede no es parte, puede exigirse la disociación o anonimización de los datos personales (art. 235).","refs":[{"ref":"Art. 234.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"facilitarán a los interesados cuanta información soliciten sobre el estado de las actuaciones procesales, que podrán examinar y conocer, salvo que sean o hubieren sido declaradas secretas o reservadas conforme a la ley."},{"ref":"Art. 235","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"podrá llevarse a cabo previa disociación, anonimización u otra medida de protección de los datos de carácter personal"}]}]},{"n":"3","title":"Derechos de atención y gestión: una justicia comprensible y atenta","blocks":[{"text":"Las notificaciones, citaciones, emplazamientos y requerimientos deben usar términos sencillos y comprensibles, sin elementos intimidatorios innecesarios (apdo. 5). En vistas y comparecencias se usará un lenguaje comprensible para quien no es especialista, y velan por ello los Jueces y Magistrados que dirigen el acto (apdo. 6); las sentencias deben redactarse con sintaxis y estructura sencillas (apdo. 7). Cuando no sea preceptiva la intervención de Abogado y Procurador, el ciudadano tiene derecho a disponer gratuitamente de los formularios necesarios (apdo. 8).","refs":[{"ref":"Apdo. 5","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"El ciudadano tiene derecho a que las notificaciones, citaciones, emplazamientos y requerimientos contengan términos sencillos y comprensibles, evitándose el uso de elementos intimidatorios innecesarios."},{"ref":"Apdo. 6","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"Los Jueces y Magistrados que dirijan los actos procesales velarán por la salvaguardia de este derecho."},{"ref":"Apdo. 8","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"El ciudadano tiene derecho a disponer gratuitamente de los formularios necesarios para el ejercicio de sus derechos ante los tribunales cuando no sea preceptiva la intervención de Abogado y Procurador."}]},{"text":"El ciudadano debe ser atendido de forma respetuosa y adaptada a sus circunstancias (apdo. 9) y puede exigir puntualidad; la suspensión de una actuación a la que esté convocado se le comunicará, salvo fuerza mayor, con antelación suficiente para evitar el desplazamiento (apdo. 10). Su comparecencia debe ser lo menos gravosa posible: solo se exige cuando es estrictamente indispensable, se procura concentrar en un solo día las actuaciones ante un mismo órgano y las indemnizaciones por desplazamiento se tramitan con preferencia (apdo. 11). Además, tiene derecho a ser atendido en horario de mañana y tarde en los órganos en que, por su naturaleza o volumen, resulte necesario (apdo. 15).","refs":[{"ref":"Apdo. 10","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"La suspensión se comunicará al ciudadano, salvo causa de fuerza mayor, con antelación suficiente para evitar su desplazamiento."},{"ref":"Apdo. 11","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"Se procurará siempre concentrar en un solo día las distintas actuaciones que exijan la comparecencia de una persona ante un mismo órgano judicial."},{"ref":"Apdo. 15","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"El ciudadano tiene derecho a ser atendido en horario de mañana y tarde en las dependencias judiciales de aquellos órganos en los que, por su naturaleza o volumen de asuntos, resulte necesario y en los términos legalmente previstos."}]}]},{"n":"4","title":"Identificación de actuaciones y funcionarios; una justicia responsable y ágil","blocks":[{"text":"El ciudadano tiene derecho a conocer la identidad y categoría de la autoridad o funcionario que le atiende, salvo cuando esté justificado por razones de seguridad en causas criminales; los datos figurarán en lugar visible del puesto y quien atienda por teléfono o por vía telemática debe identificarse siempre (apdo. 13). Puede ser atendido personalmente por el Juez o por el Secretario Judicial sobre cualquier incidencia del funcionamiento del órgano (apdo. 14).","refs":[{"ref":"Apdo. 13","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"El ciudadano tiene derecho a conocer la identidad y categoría de la autoridad o funcionario que le atienda, salvo cuando esté justificado por razones de seguridad en causas criminales."},{"ref":"Apdo. 13","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"Quien responda por teléfono o quien realice una comunicación por vía telemática deberá en todo caso identificarse ante el ciudadano."}]},{"text":"Puede formular reclamaciones, quejas y sugerencias sobre el funcionamiento de la Justicia y recibir respuesta en el plazo máximo de un mes; se presentan ante el propio Juzgado o Tribunal, sus órganos de gobierno, las Oficinas de Atención al Ciudadano, el CGPJ, el Ministerio de Justicia y, en su caso, las comunidades autónomas (apdo. 17; no se cita al Defensor del Pueblo). Puede exigir responsabilidad por error judicial o funcionamiento anormal, con tramitación preferente de las indemnizaciones (apdo. 18). Tiene derecho a una tramitación ágil: el Ministerio de Justicia y el CGPJ elaboran un programa de previsiones de duración de los procedimientos (apdo. 19). No se le exigirán documentos que ya obren en poder de las Administraciones, salvo que lo pidan las leyes procesales (apdo. 20), y puede comunicarse por correo electrónico, videoconferencia y otros medios telemáticos (apdo. 21).","refs":[{"ref":"Apdo. 17","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"así como a recibir respuesta a las mismas con la mayor celeridad y, en todo caso, dentro del plazo de un mes."},{"ref":"Apdo. 17","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"Podrá presentar las quejas y sugerencias ante el propio Juzgado o Tribunal, sus órganos de gobierno, las Oficinas de Atención al Ciudadano, el Consejo General del Poder Judicial, el Ministerio de Justicia y, en su caso, ante las Administraciones de las Comunidades Autónomas."},{"ref":"Apdo. 19","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"El Ministerio de Justicia y el Consejo General del Poder Judicial elaborarán un programa de previsiones con la duración debida de los distintos procedimientos en todos los órdenes jurisdiccionales"},{"ref":"Apdo. 20","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"El ciudadano tiene derecho a que no se le exija la aportación de documentos que obren en poder de las Administraciones Públicas, salvo que las leyes procesales expresamente lo requieran."}]}]},{"n":"5","title":"Derechos lingüísticos","blocks":[{"text":"La Carta reconoce el derecho a utilizar con la Administración de Justicia del territorio de la propia comunidad la lengua oficial que se elija, en los términos de la LOPJ y los Estatutos de Autonomía (apdo. 16). La LOPJ fija las reglas: jueces, fiscales, letrados y funcionarios usan el castellano, lengua oficial del Estado (art. 231.1), y pueden usar también la lengua oficial propia de la comunidad si ninguna parte se opone alegando un desconocimiento que pueda causar indefensión (art. 231.2). Las partes, sus representantes y defensores, testigos y peritos pueden usar la lengua cooficial tanto oralmente como por escrito (art. 231.3).","refs":[{"ref":"Apdo. 16","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"El ciudadano tiene derecho a utilizar con la Administración de Justicia del territorio de su Comunidad la lengua oficial que escoja"},{"ref":"Art. 231.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"podrán usar también la lengua oficial propia de la Comunidad Autónoma, si ninguna de las partes se opusiere, alegando desconocimiento de ella que pudiere producir indefensión."},{"ref":"Art. 231.3","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"podrán utilizar la lengua que sea también oficial en la Comunidad Autónoma en cuyo territorio tengan lugar las actuaciones judiciales, tanto en manifestaciones orales como escritas."}]},{"text":"Lo actuado o presentado en lengua cooficial es plenamente válido sin traducción. Se traduce de oficio cuando deba surtir efecto fuera de la comunidad (salvo comunidades con lengua oficial propia coincidente), cuando lo dispongan las leyes o a instancia de parte que alegue indefensión (art. 231.4 LOPJ). Para el extranjero que no conozca el castellano ni la lengua cooficial se garantiza intérprete cuando deba ser interrogado, declarar o conocer personalmente una resolución (apdo. 31 Carta).","refs":[{"ref":"Art. 231.4","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"De oficio se procederá a su traducción cuando deban surtir efecto fuera de la jurisdicción de los órganos judiciales sitos en la Comunidad Autónoma, salvo si se trata de Comunidades Autónomas con lengua oficial propia coincidente."},{"ref":"Apdo. 31","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"Se garantizará el uso de intérprete cuando el extranjero que no conozca el castellano ni, en su caso, la lengua oficial propia de la Comunidad Autónoma, hubiese de ser interrogado o prestar alguna declaración"}]}]},{"n":"6","title":"Una justicia que protege a los más débiles","blocks":[{"text":"La víctima de un delito tiene derecho a información clara sobre su intervención y la reparación (apdo. 22), a comparecer de forma adecuada a su dignidad e intimidad, sin coincidir con el agresor en las dependencias judiciales (apdo. 23), a protección inmediata, con medios como localizadores o teleasistencia (apdo. 24), y a protección frente a la publicidad no deseada (apdo. 25). El menor tiene derecho a comparecer de forma adaptada (circuito cerrado, videoconferencia) evitando reiterar comparecencias (apdo. 26); si tiene suficiente juicio, a ser oído en todo proceso que le afecte, derecho por el que vela el Ministerio Fiscal (apdo. 27); y a la reserva de las actuaciones (apdo. 28).","refs":[{"ref":"Apdo. 23","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"Se adoptarán las medidas necesarias para que la víctima no coincida con el agresor cuando ambos se encuentren en dependencias judiciales a la espera de la práctica de cualquier actuación procesal."},{"ref":"Apdo. 27","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"El Ministerio Fiscal velará por la efectividad de este derecho, prestando al menor la asistencia que necesite."}]},{"text":"La persona con discapacidad solo comparece cuando sea estrictamente necesario y los edificios deben tener servicios que faciliten el acceso (apdo. 29). La persona sorda, muda o con discapacidad visual tiene derecho a intérprete de signos o medios tecnológicos; se comprobará con especial cuidado que el acto de comunicación le ha llegado y, en su caso, se leerá en voz alta (apdo. 30). Los extranjeros inmigrantes deben comprender el significado de las actuaciones, y velan por ello Jueces, Tribunales y Ministerio Fiscal (apdo. 32).","refs":[{"ref":"Apdo. 30","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"Se comprobará con especial cuidado que el acto de comunicación ha llegado a conocimiento efectivo de su destinatario y, en su caso, se procederá a la lectura en voz alta del contenido del acto."}]}]},{"n":"7","title":"Derechos frente a Abogados, Procuradores y Graduados Sociales","blocks":[{"text":"La tercera parte de la Carta regula la relación de confianza con Abogados y Procuradores (no menciona a los Graduados Sociales): servicio profesional de calidad (apdo. 33), denuncia ante los Colegios de conductas antideontológicas con resolución motivada (apdo. 34), conocer las sanciones disciplinarias no canceladas (apdo. 35) y secreto profesional (apdo. 36). El cliente tiene derecho a conocer de antemano el coste aproximado y la forma de pago, por lo que Abogados y Procuradores deben entregar un presupuesto previo (apdo. 37); a ser informado del estado del procedimiento y recibir copia de escritos y resoluciones relevantes (apdo. 38); y a conocer antes de litigar las consecuencias de una condena en costas (apdo. 39). Si tiene derecho a justicia gratuita, puede exigir un Abogado cualificado y formación de calidad del turno de oficio (apdos. 40 y 41).","refs":[{"ref":"Apdo. 37","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"Los Abogados y Procuradores estarán obligados a entregar a su cliente un presupuesto previo que contenga los anteriores extremos."},{"ref":"Apdo. 35","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"El ciudadano tiene derecho a conocer, a través del Colegio Profesional correspondiente, si un Abogado o Procurador ha sido objeto de alguna sanción disciplinaria, no cancelada, por alguna actuación profesional."}]},{"text":"La LOPJ completa este epígrafe. Corresponde en exclusiva la denominación y función de abogado a quien ejerce profesionalmente la dirección y defensa de las partes o el asesoramiento jurídico (art. 542.1), y a los procuradores la representación de las partes, salvo que la ley autorice otra cosa (art. 543.1). En los procedimientos laborales y de Seguridad Social la representación técnica puede ostentarla un Graduado Social (art. 545.2). Los tres prestan juramento o promesa de acatar la Constitución y su colegiación es obligatoria para actuar ante los tribunales, salvo que sirvan a las Administraciones públicas por dependencia funcionarial o laboral (art. 544). Están sujetos a responsabilidad civil, penal y disciplinaria (art. 546.2).","refs":[{"ref":"Art. 543.1","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Corresponde exclusivamente a los procuradores la representación de las partes en todo tipo de procesos, salvo cuando la ley autorice otra cosa."},{"ref":"Art. 545.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"En los procedimientos laborales y de Seguridad Social la representación técnica podrá ser ostentada por un Graduado Social"},{"ref":"Art. 544.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"La colegiación de los Abogados, Procuradores y Graduados Sociales será obligatoria para actuar ante los Juzgados y Tribunales en los términos previstos en esta Ley y por la legislación general sobre colegios profesionales, salvo que actúen al servicio de las Administraciones públicas o entidades públicas por razón de dependencia funcionarial o laboral."}]}]},{"n":"8","title":"El derecho a la justicia gratuita: fundamento, ámbito personal y requisitos","blocks":[{"text":"Según el artículo 119 CE, la justicia es gratuita cuando lo disponga la ley y, en todo caso, para quienes acrediten insuficiencia de recursos para litigar. La Ley 1/1996, de Asistencia Jurídica Gratuita, desarrolla ese derecho, regula su procedimiento y se aplica a todo tipo de procesos, incluido el recurso de amparo (art. 1 AJG). Tienen derecho, si acreditan insuficiencia de recursos, los españoles, los nacionales de otros Estados de la UE y los extranjeros que se encuentren en España (art. 2.a); en todo caso, las Entidades Gestoras y Servicios Comunes de la Seguridad Social (art. 2.b). Con independencia de sus recursos y de inmediato, lo tienen las víctimas de violencia de género, terrorismo y trata en los procesos vinculados a su condición de víctimas (art. 2.h).","refs":[{"ref":"Art. 119","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"La justicia será gratuita cuando así lo disponga la ley y, en todo caso, respecto de quienes acrediten insuficiencia de recursos para litigar."},{"ref":"Art. 2.a)","law":"Ley 1/1996","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-750","quote":"Los ciudadanos españoles, los nacionales de los demás Estados miembros de la Unión Europea y los extranjeros que se encuentren en España, cuando acrediten insuficiencia de recursos para litigar."},{"ref":"Art. 2.h)","law":"Ley 1/1996","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-750","quote":"Con independencia de la existencia de recursos para litigar, se reconoce el derecho de asistencia jurídica gratuita, que se les prestará de inmediato, a las víctimas de violencia de género, de terrorismo y de trata de seres humanos"}]},{"text":"Los umbrales de ingresos brutos anuales por unidad familiar, para personas sin patrimonio suficiente, se fijan en el IPREM: dos veces si no se integra en ninguna unidad familiar, dos veces y media en unidades de menos de cuatro miembros y el triple en las de cuatro o más o familias numerosas (art. 3.1 AJG). Se tienen en cuenta los signos externos de capacidad económica (art. 4). Excepcionalmente, la Comisión puede reconocerlo por resolución motivada si los ingresos no superan el quíntuplo del IPREM, atendiendo a circunstancias familiares, de salud o discapacidad (art. 5).","refs":[{"ref":"Art. 3.1","law":"Ley 1/1996","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-750","quote":"a) Dos veces el indicador público de renta de efectos múltiples vigente en el momento de efectuar la solicitud cuando se trate de personas no integradas en ninguna unidad familiar."},{"ref":"Art. 3.1.c)","law":"Ley 1/1996","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-750","quote":"El triple de dicho indicador cuando se trate de unidades familiares integradas por cuatro o más miembros o que tengan reconocida su condición de familia numerosa"},{"ref":"Art. 5.1","law":"Ley 1/1996","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-750","quote":"no excedan del quíntuplo del indicador público de renta de efectos múltiples"}]}]},{"n":"9","title":"Contenido material y extensión temporal del derecho","blocks":[{"text":"El derecho comprende, entre otras prestaciones: asesoramiento y orientación previos al proceso; asistencia de abogado al detenido o preso que no lo haya designado; defensa y representación gratuitas por abogado y procurador cuando sean preceptivos o lo requiera el tribunal por auto motivado; inserción gratuita de anuncios y edictos; exención de tasas judiciales y depósitos para recurrir; asistencia pericial gratuita; copias y actas notariales gratuitas; y reducción del 80 % de aranceles notariales y registrales (art. 6 AJG). El reconocimiento implica siempre la exención de tasas y depósitos (art. 12.1).","refs":[{"ref":"Art. 6.5","law":"Ley 1/1996","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-750","quote":"Exención del pago de tasas judiciales, así como del pago de depósitos necesarios para la interposición de recursos."},{"ref":"Art. 6.8","law":"Ley 1/1996","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-750","quote":"Reducción del 80 por 100 de los derechos arancelarios que correspondan por el otorgamiento de escrituras públicas"}]},{"text":"Dentro de una misma instancia el derecho alcanza a todos los trámites e incidencias, incluida la ejecución, pero no a un proceso distinto (art. 7.1 AJG), y se mantiene para los recursos contra la resolución que ponga fin a la instancia (art. 7.2). Una vez presentada la demanda o contestación solo se reconoce si las circunstancias sobrevinieron después, y sin efecto retroactivo (art. 8).","refs":[{"ref":"Art. 7.1","law":"Ley 1/1996","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-750","quote":"La asistencia jurídica gratuita en el transcurso de una misma instancia se extiende a todos sus trámites e incidencias, incluida la ejecución, pero no podrá aplicarse a un proceso distinto."},{"ref":"Art. 8","law":"Ley 1/1996","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-750","quote":"El reconocimiento del derecho a la asistencia jurídica gratuita por circunstancias sobrevenidas no tendrá carácter retroactivo."}]}]},{"n":"10","title":"Comisiones de Asistencia Jurídica Gratuita y procedimiento de reconocimiento","blocks":[{"text":"El reconocimiento corresponde a la Comisión de Asistencia Jurídica Gratuita, que existe en cada capital de provincia, en Ceuta y Melilla y en cada isla con uno o más partidos judiciales; para los órganos con competencia nacional hay una Comisión Central en Madrid (art. 9 AJG). La solicitud se presenta ante el Colegio de Abogados del lugar del juzgado o tribunal que conozca del proceso principal o ante el juzgado del domicilio, que la traslada al Colegio (art. 12.2). Si hay deficiencias, el Colegio requiere la subsanación en diez días hábiles y, si no se atiende, archiva (art. 14).","refs":[{"ref":"Art. 9","law":"Ley 1/1996","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-750","quote":"En cada capital de provincia, en las ciudades de Ceuta y Melilla y en cada isla en que existan uno o más partidos judiciales, se constituirá una Comisión de Asistencia Jurídica Gratuita"},{"ref":"Art. 12.2","law":"Ley 1/1996","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-750","quote":"se instará por los solicitantes ante el Colegio de Abogados del lugar en que se halle el juzgado o tribunal que haya de conocer del proceso principal para el que aquél se solicita, o ante el juzgado de su domicilio."},{"ref":"Art. 14","law":"Ley 1/1996","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-750","quote":"requiriéndole para que la complete en el plazo de diez días hábiles."}]},{"text":"Si el solicitante entra en el ámbito del artículo 2, el Colegio designa provisionalmente abogado en un máximo de quince días y lo comunica al Colegio de Procuradores, que designa procurador, si es preceptivo, en un máximo de tres días; el expediente pasa a la Comisión en tres días (art. 15). La solicitud no suspende el proceso, aunque el Letrado de la Administración de Justicia (la ley aún dice «secretario judicial») puede suspenderlo para evitar preclusión o indefensión (art. 16.1). La Comisión resuelve en un máximo de treinta días; si no lo hace, quedan ratificadas las decisiones previas de los Colegios (art. 17.2). La resolución definitiva se impugna por escrito motivado, sin abogado, en diez días, ante el secretario de la Comisión, y la resuelve el juez por auto sin recurso (art. 20).","refs":[{"ref":"Art. 15","law":"Ley 1/1996","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-750","quote":"procederá en el plazo máximo de quince días, contado a partir de la recepción de la solicitud por dicho Colegio o de la subsanación de los defectos, a la designación provisional de abogado"},{"ref":"Art. 16.1","law":"Ley 1/1996","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-750","quote":"La solicitud de reconocimiento del derecho a la asistencia jurídica gratuita no suspenderá el curso del proceso o expediente administrativo."},{"ref":"Art. 17.2","law":"Ley 1/1996","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-750","quote":"dictará resolución, en el plazo máximo de treinta días, contados a partir de la recepción del expediente por la Comisión"},{"ref":"Art. 20.1","law":"Ley 1/1996","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-750","quote":"Tal impugnación, para la que no será preceptiva la intervención de abogado, habrá de realizarse por escrito y de forma motivada, en el plazo de diez días"},{"ref":"Art. 20.3","law":"Ley 1/1996","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-750","quote":"Contra el auto dictado por el juez o el tribunal no cabrá recurso alguno."}]}]},{"n":"11","title":"Designación de oficio, insostenibilidad y costas","blocks":[{"text":"El reconocimiento conlleva la designación de abogado y, si es preciso, procurador de oficio; no pueden actuar a la vez un profesional de oficio y otro de libre elección, salvo renuncia escrita de este a sus honorarios (art. 27 AJG). Los designados deben actuar hasta el final de la instancia y, en su caso, la ejecución si se produce en los dos años siguientes; solo en el orden penal puede el abogado excusarse, por motivo personal y justo, en tres días (art. 31).","refs":[{"ref":"Art. 27","law":"Ley 1/1996","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-750","quote":"sin que en ningún caso puedan actuar simultáneamente un abogado de oficio y un procurador libremente elegido, o viceversa"},{"ref":"Art. 31","law":"Ley 1/1996","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-750","quote":"Sólo en el orden penal podrán los abogados designados excusarse de la defensa."}]},{"text":"Si el abogado considera insostenible la pretensión, debe comunicarlo a la Comisión dentro de los quince días siguientes a su designación; si no lo hace, queda obligado a asumir la defensa, y la del acusado es siempre obligatoria (art. 32). La Comisión pide dictamen al Colegio de Abogados (quince días) y, si coincide con el del abogado, informe del Ministerio Fiscal (seis días) (art. 33). En el orden penal no cabe insostenibilidad respecto de los condenados (art. 35). Si el beneficiario es condenado en costas, pagará las propias y las contrarias si viene a mejor fortuna en los tres años siguientes a la terminación del proceso (art. 36.2).","refs":[{"ref":"Art. 32","law":"Ley 1/1996","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-750","quote":"Cuando el Abogado designado para un proceso considere insostenible la pretensión que pretende hacerse valer, deberá comunicarlo a la Comisión de Asistencia Jurídica Gratuita, dentro de los 15 días siguientes a su designación"},{"ref":"Art. 36.2","law":"Ley 1/1996","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-750","quote":"si dentro de los tres años siguientes a la terminación del proceso viniere a mejor fortuna"}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Quejas y sugerencias: respuesta en un mes como máximo (apdo. 17 Carta).","refs":[{"ref":"Apdo. 17","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"en todo caso, dentro del plazo de un mes."}]},{"text":"Seguimiento de la Carta: Comisión de Justicia e Interior del Congreso.","refs":[{"ref":"Eficacia 3","law":"Carta de Derechos de los Ciudadanos ante la Justicia","url":"https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos","quote":"a través de la Comisión de Justicia e Interior"}]},{"text":"Señalamientos: se publican el primer día hábil de cada semana (art. 232.2 LOPJ).","refs":[{"ref":"Art. 232.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"el primer día hábil de cada semana"}]},{"text":"Lengua cooficial: partes, testigos y peritos pueden usarla oralmente y por escrito; jueces y funcionarios, si ninguna parte se opone alegando indefensión (art. 231 LOPJ).","refs":[{"ref":"Art. 231.3","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"tanto en manifestaciones orales como escritas."}]},{"text":"Graduado Social: representación técnica en procedimientos laborales y de Seguridad Social (art. 545.2 LOPJ).","refs":[{"ref":"Art. 545.2","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"la representación técnica podrá ser ostentada por un Graduado Social"}]},{"text":"Umbral general de justicia gratuita: dos veces el IPREM para quien no tiene unidad familiar (art. 3.1 AJG).","refs":[{"ref":"Art. 3.1","law":"Ley 1/1996","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-750","quote":"Dos veces el indicador público de renta de efectos múltiples"}]},{"text":"Plazos clave del procedimiento: diez días hábiles para subsanar; quince días para designar abogado y tres para procurador; treinta días para que resuelva la Comisión; diez días para impugnar (arts. 14, 15, 17 y 20 AJG).","refs":[{"ref":"Art. 15","law":"Ley 1/1996","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-750","quote":"en el plazo máximo de tres días, se designe procurador"}]},{"text":"Insostenibilidad: el abogado la comunica en quince días; mejor fortuna: tres años desde que termina el proceso (arts. 32 y 36.2 AJG).","refs":[{"ref":"Art. 32","law":"Ley 1/1996","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-750","quote":"dentro de los 15 días siguientes a su designación"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666', null, null, null, 'Otras normas citadas: CE (https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229), Ley 1/1996 (https://www.boe.es/buscar/act.php?id=BOE-A-1996-750)'
  from public.topics t where t.slug = 'jus-09-carta-derechos'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('jus-10-oficina-judicial', 'Tema 10. La modernización de la oficina judicial y las nuevas tecnologías') on conflict (slug) do nothing;
