insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 36/2011, de 10 de octubre, reguladora de la jurisdicción social (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('jus-20-proceso-laboral', 'Tema 20. El proceso laboral: ordinario, despido y seguridad social') on conflict (slug) do nothing;
