insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 20/2011, de 21 de julio, del Registro Civil (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('jus-25-registro-civil', 'Tema 25. El Registro Civil: oficinas, hechos inscribibles, inscripciones, certificaciones y expedientes') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-25-registro-civil' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El Registro Civil: naturaleza, elementos definitorios y hechos inscribibles (arts. 2-4 LRC)"},{"n":"2","title":"Principios y eficacia de la inscripción (arts. 15-18 LRC)"},{"n":"3","title":"Estructura: Oficina Central, Oficinas Generales y Oficinas Consulares y sus funciones (arts. 20-24 LRC)"},{"n":"4","title":"Los asientos: competencia, plazos y clases (arts. 33, 38-41 LRC)"},{"n":"5","title":"Inscripción de nacimiento y filiación (arts. 44-49 LRC)"},{"n":"6","title":"Inscripciones relativas al matrimonio (arts. 58-61 LRC)"},{"n":"7","title":"Inscripción de la defunción (arts. 62-67 LRC)"},{"n":"8","title":"Otras inscripciones: nacionalidad, vecindad, emancipación, patria potestad, apoyos (arts. 68-78 LRC)"},{"n":"9","title":"Publicidad: certificaciones y datos especialmente protegidos (arts. 80-84 LRC)"},{"n":"10","title":"Recursos y expedientes (procedimientos registrales) del Registro Civil (arts. 85-93 LRC)"}]'::jsonb, '["Art. 2.2 Ley 20/2011: «El Registro Civil tiene por objeto hacer constar oficialmente los hechos y actos que se refieren al estado civil de las personas y aquellos otros que determine la presente Ley.»","Art. 3.1-2 Ley 20/2011: «1. El Registro Civil es único para toda España. 2. El Registro Civil es electrónico.»","Art. 17.1 Ley 20/2011: «La inscripción en el Registro Civil constituye prueba plena de los hechos inscritos.»","Art. 20.1 Ley 20/2011: «El Registro Civil depende del Ministerio de Justicia y se organiza en: 1.º Oficina Central. 2.º Oficinas Generales. 3.º Oficinas Consulares.»","Art. 22.1 Ley 20/2011: «Existirá una Oficina General del Registro Civil en todas las poblaciones que sean sede de la capital de un partido judicial.»","Art. 23 Ley 20/2011: «Las Oficinas Consulares del Registro Civil estarán a cargo de los Cónsules de España o, en su caso, de los funcionarios diplomáticos encargados de las Secciones consulares de la Misión Diplomática.»","Art. 33.1 Ley 20/2011: «El Encargado de la Oficina del Registro Civil ante el que se presente el título o se formule la declaración practicará los asientos correspondientes de oficio o dictará resolución denegándolos en el plazo de cinco días. La inscripción de la defunción, no existiendo obstáculo legal, se practicará en el mismo día de la presentación de la documentación.»","Art. 38 Ley 20/2011: «Los asientos del Registro Civil son las inscripciones, las anotaciones y las cancelaciones.»","Art. 44.2 Ley 20/2011: «La inscripción hace fe del hecho, fecha, hora y lugar del nacimiento, identidad, sexo y, en su caso, filiación del inscrito.»","Art. 47.1 Ley 20/2011: «Respecto de los nacimientos que se hayan producido fuera de establecimiento sanitario, o cuando por cualquier causa no se haya remitido el documento en el plazo y condiciones previstos en el artículo anterior, los obligados a promover la inscripción dispondrán de un plazo de diez días para declarar el nacimiento ante la Oficina del Registro Civil o las Oficinas Consulares de Registro Civil.»","Art. 59.4 Ley 20/2011: «La inscripción hace fe del matrimonio y de la fecha y lugar en que se contrae.»","Art. 62.1 Ley 20/2011: «La inscripción en el Registro Civil de la defunción es obligatoria. La inscripción hace fe de la muerte de una persona y de la fecha, hora y lugar en que se produce. En la inscripción debe figurar asimismo la identidad del fallecido.»","Art. 68.1 Ley 20/2011: «La adquisición de la nacionalidad española por residencia, carta de naturaleza y opción, así como su recuperación y las declaraciones de voluntad relativas a la vecindad, se inscribirán en el registro individual. Estas inscripciones tendrán carácter constitutivo.»","Art. 82.1 Ley 20/2011: «Las certificaciones podrán ser literales o en extracto. Salvo solicitud expresa en sentido contrario, se expedirá certificación en extracto. Si no constara ningún asiento, la certificación será negativa.»","Art. 86.2 Ley 20/2011: «La Dirección General resolverá el recurso en el plazo de seis meses siguientes a la recepción del escrito de interposición.»","Art. 88 Ley 20/2011: «1. Los procedimientos registrales serán tramitados y resueltos por el Encargado del Registro Civil de la Oficina donde se pretendiera efectuar el asiento. Los procedimientos de rectificación de asientos se tramitarán por el Encargado de la Oficina que los hubiese practicado.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"El Registro Civil: naturaleza, objeto y elementos definitorios","blocks":[{"text":"El Registro Civil es un registro público que depende del Ministerio de Justicia; su objeto es dejar constancia oficial de los hechos y actos relativos al estado civil de las personas y de los demás que determine la Ley 20/2011 (art. 2 LRC). Se compone del conjunto de registros individuales de las personas físicas y de las restantes inscripciones (art. 2.3 LRC). Tiene dos elementos definitorios: es único para toda España y es electrónico, con una base de datos única cuya estructura corresponde al Ministerio de Justicia (art. 3 LRC). Nota de vigencia: varios artículos de la LRC conservan la antigua denominación «Dirección General de los Registros y del Notariado», mientras otros ya hablan de «Dirección General de Seguridad Jurídica y Fe Pública», que es el nombre actual del centro directivo.","refs":[{"ref":"Art. 2.2","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"El Registro Civil tiene por objeto hacer constar oficialmente los hechos y actos que se refieren al estado civil de las personas y aquellos otros que determine la presente Ley."},{"ref":"Art. 3.1 y 2","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"1. El Registro Civil es único para toda España. 2. El Registro Civil es electrónico."}]},{"text":"Cada persona tiene un registro individual, que se abre con la inscripción de nacimiento o con el primer asiento que se practique, y en el que se anotan cronológicamente todos sus hechos y actos (art. 5 LRC). A ese registro se le asigna un código personal alfanumérico, único e invariable (art. 6 LRC).","refs":[{"ref":"Art. 5.2","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"2. El registro individual se abrirá con la inscripción de nacimiento o con el primer asiento que se practique."},{"ref":"Art. 6","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"se le asignará un código personal constituido por la secuencia alfanumérica generada por el Registro Civil, que será única e invariable en el tiempo."}]}]},{"n":"2","title":"Hechos y actos inscribibles","blocks":[{"text":"Acceden al Registro los hechos y actos que se refieren a la identidad, estado civil y demás circunstancias de la persona. El art. 4 LRC enumera dieciséis: nacimiento; filiación; nombre y apellidos y sus cambios; sexo y su cambio; nacionalidad y vecindad civil; emancipación y beneficio de la mayor edad; matrimonio, separación, nulidad y divorcio; régimen económico matrimonial; relaciones paterno-filiales; poderes y mandatos preventivos y medidas de apoyo voluntarias; resoluciones judiciales de provisión de apoyos; patrimonio protegido de personas con discapacidad; tutela del menor y defensa judicial del emancipado; concurso de personas físicas; declaraciones de ausencia y fallecimiento; y la defunción.","refs":[{"ref":"Art. 4","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"Tienen acceso al Registro Civil los hechos y actos que se refieren a la identidad, estado civil y demás circunstancias de la persona. Son, por tanto, inscribibles: 1.º El nacimiento. 2.º La filiación."},{"ref":"Art. 4.16.º","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"15.º Las declaraciones de ausencia y fallecimiento. 16.º La defunción."}]}]},{"n":"3","title":"Principios y eficacia de la inscripción","blocks":[{"text":"El Registro es público: cada ciudadano accede libremente a su registro individual, las Administraciones acceden para ejercer sus funciones y terceros pueden obtener información si consta su identidad y tienen interés legítimo; se exceptúan los datos especialmente protegidos (art. 15 LRC). Se presume que los hechos inscritos existen y que los actos son válidos y exactos mientras el asiento no se rectifique o cancele (art. 16.2 LRC), y el contenido del Registro se presume íntegro (art. 19 LRC).","refs":[{"ref":"Art. 15.1 y 2","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"1. Los ciudadanos tendrán libre acceso a los datos que figuren en su registro individual. 2. El Registro Civil es público."},{"ref":"Art. 16.2","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"2. Se presume que los hechos inscritos existen y los actos son válidos y exactos mientras el asiento correspondiente no sea rectificado o cancelado en la forma prevista por la ley."}]},{"text":"La inscripción constituye prueba plena de los hechos inscritos; solo si falta la inscripción o no se puede certificar se admiten otros medios de prueba, y en el primer caso hay que acreditar que se ha instado la inscripción omitida (art. 17 LRC). La inscripción solo tiene eficacia constitutiva en los casos previstos por la ley (art. 18 LRC), como la adquisición de la nacionalidad (art. 68 LRC).","refs":[{"ref":"Art. 17.1","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"1. La inscripción en el Registro Civil constituye prueba plena de los hechos inscritos."},{"ref":"Art. 18","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"La inscripción en el Registro Civil sólo tendrá eficacia constitutiva en los casos previstos por la Ley."}]}]},{"n":"4","title":"Estructura del Registro Civil y Oficina Central","blocks":[{"text":"El Registro Civil depende del Ministerio de Justicia y se organiza en Oficina Central, Oficinas Generales y Oficinas Consulares (art. 20.1 LRC). Los asientos los practican los Encargados de las Oficinas, que pueden delegar funciones en el personal de la oficina (art. 20.2 LRC). Los ciudadanos pueden presentar solicitudes y documentos en cualquier Oficina, electrónicamente o en las Oficinas Colaboradoras (art. 20.3 LRC).","refs":[{"ref":"Art. 20.1","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"1. El Registro Civil depende del Ministerio de Justicia y se organiza en: 1.º Oficina Central. 2.º Oficinas Generales. 3.º Oficinas Consulares."},{"ref":"Art. 20.3","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"3. Los ciudadanos podrán presentar la solicitud y la documentación requerida ante cualquier Oficina del Registro Civil o remitirla electrónicamente."}]},{"text":"Los Encargados de la Oficina Central los designa el Ministerio de Justicia. Esta oficina inscribe lo que derive de resoluciones de la Dirección General, los documentos extranjeros judiciales y extrajudiciales y certificaciones de registros extranjeros (salvo lo que corresponda a los Consulados) y ciertos fallecimientos de extranjeros al servicio de las Fuerzas Armadas o de Seguridad en misiones fuera de España; además es la autoridad de cooperación internacional en materia de Registro Civil (art. 21 LRC).","refs":[{"ref":"Art. 21.1","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"1. El Ministerio de Justicia designará a los Encargados de la Oficina Central del Registro Civil."},{"ref":"Art. 21.3","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"3. La Oficina Central es la autoridad encargada en materia de cooperación internacional sobre Registro Civil"}]}]},{"n":"5","title":"Oficinas Generales y Oficinas Consulares","blocks":[{"text":"Hay una Oficina General en todas las poblaciones que son capital de un partido judicial (art. 22.1 LRC). Al frente está un Encargado, que depende funcionalmente de la Dirección General de Seguridad Jurídica y Fe Pública; puede haber varios, con un Encargado coordinador (art. 22.2 LRC). Sus funciones son recibir declaraciones de conocimiento y de voluntad, recibir solicitudes y títulos, tramitar y resolver expedientes, practicar inscripciones y demás asientos y expedir certificaciones (art. 22.3 LRC).","refs":[{"ref":"Art. 22.1","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"1. Existirá una Oficina General del Registro Civil en todas las poblaciones que sean sede de la capital de un partido judicial."},{"ref":"Art. 22.3","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"c) Tramitar y resolver los expedientes de Registro Civil que les atribuya el ordenamiento jurídico. d) Practicar las inscripciones y demás asientos de su competencia. e) Expedir certificaciones de los asientos registrales."}]},{"text":"Las Oficinas Consulares están a cargo de los Cónsules de España o de los funcionarios diplomáticos encargados de las secciones consulares (art. 23 LRC). Inscriben los hechos relativos a españoles ocurridos en su circunscripción, expiden certificaciones, reciben declaraciones, instruyen el expediente previo de matrimonio y expiden certificados de capacidad matrimonial, y comunican la legislación extranjera sobre estado civil (art. 24 LRC). La Dirección General dicta instrucciones vinculantes, resuelve recursos y supervisa a los Encargados (art. 26 LRC).","refs":[{"ref":"Art. 23","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"Las Oficinas Consulares del Registro Civil estarán a cargo de los Cónsules de España o, en su caso, de los funcionarios diplomáticos encargados de las Secciones consulares de la Misión Diplomática."},{"ref":"Art. 24","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"4.ª Instruir el expediente previo de matrimonio, así como expedir los certificados de capacidad necesarios para su celebración en el extranjero."}]}]},{"n":"6","title":"Títulos, plazos y clases de asientos","blocks":[{"text":"Son título para inscribir los documentos auténticos (judiciales, administrativos, notariales o registrales) y las resoluciones judiciales firmes (art. 27 LRC). El Encargado controla la legalidad de los documentos y, si tiene dudas fundadas, hace comprobaciones en diez días (art. 30 LRC). Regla general: el Encargado practica los asientos de oficio o deniega por resolución en cinco días; la defunción, si no hay obstáculo legal, se inscribe el mismo día en que se presenta la documentación (art. 33.1 LRC).","refs":[{"ref":"Art. 33.1","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"practicará los asientos correspondientes de oficio o dictará resolución denegándolos en el plazo de cinco días. La inscripción de la defunción, no existiendo obstáculo legal, se practicará en el mismo día de la presentación de la documentación."},{"ref":"Art. 30.3","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"realizará antes de extender la inscripción, y en el plazo de diez días, las comprobaciones oportunas."}]},{"text":"Los asientos son inscripciones, anotaciones y cancelaciones (art. 38 LRC). La inscripción es el asiento por el que acceden los hechos de estado civil, con los efectos de prueba plena y, en su caso, constitutivos (art. 39 LRC). Las anotaciones nunca tienen el valor probatorio de la inscripción: son meramente informativas, salvo que la ley les atribuya valor de presunción; se extienden a petición del Ministerio Fiscal o de cualquier interesado y recogen, por ejemplo, procedimientos en trámite, la desaparición o el acogimiento (art. 40 LRC). Las cancelaciones privan de eficacia total o parcial a un asiento (art. 41 LRC).","refs":[{"ref":"Art. 38","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"Los asientos del Registro Civil son las inscripciones, las anotaciones y las cancelaciones."},{"ref":"Art. 40.1","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"1. Las anotaciones registrales son la modalidad de asiento que en ningún caso tendrá el valor probatorio que proporciona la inscripción. Tendrán un valor meramente informativo, salvo los casos en que la Ley les atribuya valor de presunción."},{"ref":"Art. 41","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"Los asientos de cancelación privan de eficacia, total o parcial, al asiento registral de cualquier clase"}]}]},{"n":"7","title":"Inscripción de nacimiento y filiación","blocks":[{"text":"La inscripción de nacimiento hace fe del hecho, fecha, hora y lugar del nacimiento, de la identidad, el sexo y, en su caso, la filiación (art. 44.2 LRC); abre el registro individual y se le asigna código personal (art. 44.3 LRC). Están obligados a promoverla la dirección del centro sanitario, el personal que atendió el parto fuera del centro, los progenitores y el pariente más próximo o cualquier mayor de edad presente (art. 45 LRC). Los hospitales comunican el nacimiento en setenta y dos horas, por vía electrónica (art. 46 LRC). Si el parto fue fuera de un centro sanitario o el centro no lo comunicó, los obligados tienen diez días para declararlo; pasado ese plazo hace falta expediente registral (art. 47 LRC).","refs":[{"ref":"Art. 44.2","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"La inscripción hace fe del hecho, fecha, hora y lugar del nacimiento, identidad, sexo y, en su caso, filiación del inscrito."},{"ref":"Art. 46","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"La dirección de hospitales, clínicas y establecimientos sanitarios comunicará en el plazo de setenta y dos horas a la Oficina del Registro Civil que corresponda cada uno de los nacimientos que hayan tenido lugar en el centro sanitario"},{"ref":"Art. 47.1","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"los obligados a promover la inscripción dispondrán de un plazo de diez días para declarar el nacimiento ante la Oficina del Registro Civil o las Oficinas Consulares de Registro Civil."}]},{"text":"La filiación materna consta siempre en los nacimientos ocurridos en España, salvo abandono (art. 44.4 LRC). La filiación determina los apellidos: si hay doble filiación, los progenitores acuerdan el orden; si no se ponen de acuerdo o no los indican, el Encargado les requiere para que lo comuniquen en tres días y, si no lo hacen, decide atendiendo al interés superior del menor (art. 49.2 LRC). Si el parte facultativo indica condición intersexual, los progenitores pueden pedir de común acuerdo que el sexo figure en blanco durante un año como máximo (art. 49.5 LRC). El nombre propio es de libre elección, con un máximo de dos simples o uno compuesto (art. 51 LRC).","refs":[{"ref":"Art. 49.2","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"el Encargado del Registro Civil requerirá a los progenitores, o a quienes ostenten la representación legal del menor, para que en el plazo máximo de tres días comuniquen el orden de apellidos. Transcurrido dicho plazo sin comunicación expresa, el Encargado acordará el orden de los apellidos atendiendo al interés superior del menor."},{"ref":"Art. 49.5","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"podrán solicitar que la mención del sexo figure en blanco por el plazo máximo de un año."},{"ref":"Art. 51","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"1.º No podrán consignarse más de dos nombres simples o uno compuesto."}]}]},{"n":"8","title":"Inscripciones relativas al matrimonio","blocks":[{"text":"El matrimonio civil se celebra ante el Alcalde o concejal delegado, el LAJ, el notario o el funcionario diplomático o consular Encargado del Registro Civil, previa acta o expediente que acredite la capacidad y la falta de impedimentos (art. 58.1 y 2 LRC). Celebrado, el autorizante remite el mismo día y por medios telemáticos el documento al Registro (art. 58.8 LRC). El matrimonio se inscribe en los registros individuales de los contrayentes; el celebrado ante autoridad extranjera, mediante la certificación correspondiente, y el religioso, mediante certificación de la Iglesia o confesión. La inscripción hace fe del matrimonio y de la fecha y lugar en que se contrae (art. 59 LRC).","refs":[{"ref":"Art. 58.1","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"1. El matrimonio en forma civil se celebrará ante el o la Alcalde o Concejal en quien este delegue, letrado o letrada de la Administración de Justicia, notario o notaria, o personal funcionario diplomático o consular Encargado o Encargada del Registro Civil."},{"ref":"Art. 59.1 y 4","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"1. El matrimonio autorizado y celebrado según el procedimiento previsto en el artículo anterior se inscribirá en los registros individuales de los contrayentes."},{"ref":"Art. 59.4","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"4. La inscripción hace fe del matrimonio y de la fecha y lugar en que se contrae."}]},{"text":"Junto al matrimonio se inscribe el régimen económico matrimonial; el tercero de buena fe no queda perjudicado sino desde su inscripción (art. 60 LRC). En separación, nulidad y divorcio, el LAJ del órgano que dictó la resolución firme debe remitir testimonio o copia electrónica a la Oficina General en el mismo día o al siguiente hábil, y la Oficina inscribe de inmediato; mientras no son firmes, pueden anotarse. La misma obligación tiene el notario que autoriza el convenio regulador (art. 61 LRC).","refs":[{"ref":"Art. 61","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"deberá remitir en el mismo día o al siguiente hábil y por medios electrónicos testimonio o copia electrónica de la misma a la Oficina General del Registro Civil, la cual practicará de forma inmediata la correspondiente inscripción."},{"ref":"Art. 60.1","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"en ningún caso el tercero de buena fe resultará perjudicado sino desde la fecha de la inscripción del régimen económico matrimonial o de sus modificaciones."}]}]},{"n":"9","title":"Inscripción de la defunción","blocks":[{"text":"Inscribir la defunción es obligatorio; la inscripción hace fe de la muerte y de su fecha, hora y lugar, y debe constar la identidad del fallecido (art. 62.1 LRC). Se practica con el formulario oficial y el certificado médico, sin el cual nunca puede inscribirse (arts. 62.2 y 66 LRC). Una vez practicada, el Encargado expide la licencia de entierro o incineración (art. 62.3 LRC). La inscripción de defunción cierra el registro individual y el código personal no puede volver a asignarse (art. 62.4 LRC).","refs":[{"ref":"Art. 62.1","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"1. La inscripción en el Registro Civil de la defunción es obligatoria. La inscripción hace fe de la muerte de una persona y de la fecha, hora y lugar en que se produce."},{"ref":"Art. 62.4","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"4. La inscripción de la defunción cerrará el registro individual. En ningún caso, el código personal podrá volver a ser asignado."},{"ref":"Art. 66","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"En ningún caso podrá efectuarse la inscripción de defunción sin que se haya presentado ante el Registro Civil el certificado médico de defunción."}]},{"text":"Están obligados a promoverla la dirección del centro sanitario, el médico que certifica la muerte fuera del centro, los parientes, el director del establecimiento o habitantes de la casa y cualquiera que conozca el fallecimiento, comunicándolo a la autoridad (art. 63 LRC). Si el cadáver desapareció o se inhumó antes de inscribir, hace falta resolución que declare el fallecimiento u orden judicial; si hay indicios de muerte violenta, la licencia de enterramiento solo se expide cuando lo autoriza el órgano judicial (art. 67 LRC).","refs":[{"ref":"Art. 63","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"1.º La dirección de hospitales, clínicas y establecimientos sanitarios donde se produzca el fallecimiento."},{"ref":"Art. 67.2","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"Dicha licencia se expedirá cuando se autorice por el órgano judicial competente."}]}]},{"n":"10","title":"Otras inscripciones","blocks":[{"text":"La adquisición de la nacionalidad por residencia, carta de naturaleza y opción, su recuperación y las declaraciones sobre vecindad civil se inscriben en el registro individual con carácter constitutivo; antes debe estar inscrito el nacimiento. En cambio, la inscripción de la pérdida de la nacionalidad es meramente declarativa (art. 68.1 LRC). Se presumen españoles los nacidos en España de progenitores también nacidos en España (art. 69 LRC).","refs":[{"ref":"Art. 68.1","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"Estas inscripciones tendrán carácter constitutivo. No podrá inscribirse la nacionalidad española adquirida por cualquiera de las vías que reconoce el ordenamiento jurídico si no se ha efectuado la inscripción previa de nacimiento. La inscripción de la pérdida de la nacionalidad tendrá carácter meramente declarativo."}]},{"text":"También se inscriben la emancipación y el beneficio de la mayor edad, que no producen efectos frente a terceros hasta su inscripción (art. 70 LRC); las resoluciones sobre patria potestad (art. 71 LRC); las resoluciones judiciales de provisión de apoyos y la declaración de concurso, oponibles a terceros solo desde su inscripción (arts. 72 y 73 LRC); la tutela administrativa del menor desamparado (art. 75); las medidas de apoyo voluntarias en documento público (art. 77 LRC); y las declaraciones de ausencia y fallecimiento, con la fecha desde la que se entiende ocurrida la muerte (art. 78 LRC).","refs":[{"ref":"Art. 70.4","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"La concesión de emancipación y la emancipación por vida independiente, así como el beneficio de la mayor edad, no producirán efectos frente a terceros mientras no se inscriban en el Registro Civil."},{"ref":"Art. 73","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"Las resoluciones a que se refiere el artículo anterior solo serán oponibles frente a terceros cuando se hayan practicado las oportunas inscripciones."},{"ref":"Art. 78.2","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"2. En la inscripción de la declaración de fallecimiento se expresará la fecha a partir de la cual se entiende ocurrida la muerte."}]}]},{"n":"11","title":"Publicidad: certificaciones y datos especialmente protegidos","blocks":[{"text":"La publicidad se hace mediante el acceso de las Administraciones y mediante certificación (art. 80 LRC). Las certificaciones las expiden los Encargados, por medios electrónicos (excepcionalmente en papel) y pueden ser bilingües; se presumen exactas y son prueba plena (art. 81 LRC). Pueden ser literales (todo el asiento) o en extracto; salvo petición expresa en contrario, se expide en extracto, y si no hay asiento la certificación es negativa (art. 82 LRC).","refs":[{"ref":"Art. 82.1","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"1. Las certificaciones podrán ser literales o en extracto. Salvo solicitud expresa en sentido contrario, se expedirá certificación en extracto. Si no constara ningún asiento, la certificación será negativa."},{"ref":"Art. 81.2","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"2. Las certificaciones se expedirán por medios electrónicos. Excepcionalmente, también se podrán expedir por medios no electrónicos. A petición del interesado, las certificaciones podrán ser bilingües."}]},{"text":"Son datos especialmente protegidos, de publicidad restringida: la filiación adoptiva y la desconocida; la discapacidad y las medidas de apoyo; los cambios de apellido por violencia de género y otros cambios de identidad autorizados; la rectificación del sexo; las causas de privación o suspensión de la patria potestad; y el matrimonio secreto (art. 83.1 LRC). Solo el inscrito, sus representantes o quien preste el apoyo autorizado pueden acceder o autorizar a terceros; si el inscrito ha fallecido, autoriza el juez del domicilio del solicitante con interés legítimo (art. 84 LRC; el texto aún dice «Juez de Primera Instancia», denominación afectada por la LO 1/2025).","refs":[{"ref":"Art. 83.1","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"a) La filiación adoptiva y la desconocida. b) La discapacidad y las medidas de apoyo."},{"ref":"Art. 83.1","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"e) Las causas de privación o suspensión de la patria potestad. f) El matrimonio secreto."},{"ref":"Art. 84","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"Si el inscrito ha fallecido, la autorización para acceder a los datos especialmente protegidos sólo podrá efectuarla el Juez de Primera Instancia del domicilio del solicitante"}]}]},{"n":"12","title":"Recursos y expedientes (procedimientos registrales)","blocks":[{"text":"Contra las decisiones de los Encargados de las Oficinas Central, Generales y Consulares solo cabe recurso ante la Dirección General (hoy de Seguridad Jurídica y Fe Pública) en el plazo de un mes (art. 85.1 LRC), conforme a la Ley 39/2015. La Dirección General resuelve en seis meses desde la recepción; si no resuelve y notifica en ese plazo, la pretensión se entiende desestimada y queda abierta la vía jurisdiccional (art. 86 LRC). Sus resoluciones se impugnan ante el órgano judicial civil de la capital de provincia del domicilio del recurrente, salvo las de nacionalidad por residencia, que van a lo contencioso-administrativo (art. 87 LRC).","refs":[{"ref":"Art. 85.1","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"los interesados sólo podrán interponer recurso ante la Dirección General de los Registros y del Notariado, en el plazo de un mes."},{"ref":"Art. 86.2","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"2. La Dirección General resolverá el recurso en el plazo de seis meses siguientes a la recepción del escrito de interposición. Transcurrido este plazo sin que la Dirección General de Seguridad Jurídica y Fe Pública haya dictado y notificado resolución expresa, se entenderá desestimada la pretensión, quedando expedita la vía jurisdiccional correspondiente."},{"ref":"Art. 87.2","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"relativos a la solicitud de nacionalidad por residencia que en aplicación del artículo 22.5 del Código civil se someten a la jurisdicción contencioso-administrativa."}]},{"text":"Los procedimientos registrales (expedientes) los tramita y resuelve el Encargado de la Oficina donde se pretende el asiento; los de rectificación, el de la Oficina que lo practicó. Se rigen por la Ley 39/2015 y el silencio es negativo (art. 88 LRC). Pueden promoverlos el Ministerio Fiscal, los obligados a promover la inscripción y cualquier interesado (art. 89 LRC). La regla general es que los asientos se rectifican por resolución judicial firme (art. 90 LRC), pero por expediente pueden corregirse menciones erróneas y divergencias con los documentos (art. 91 LRC) y declararse hechos con valor de simple presunción, que es una presunción iuris tantum de anotación obligatoria (arts. 92 y 93 LRC).","refs":[{"ref":"Art. 88","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"1. Los procedimientos registrales serán tramitados y resueltos por el Encargado del Registro Civil de la Oficina donde se pretendiera efectuar el asiento."},{"ref":"Art. 88.2","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"El silencio administrativo en los procedimientos registrales será negativo."},{"ref":"Art. 90","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"Los asientos están bajo la salvaguarda de los Tribunales y su rectificación se efectuará en virtud de resolución judicial firme"}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"El Registro Civil es único para toda España y electrónico (art. 3 LRC).","refs":[{"ref":"Art. 3.1 y 2","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"1. El Registro Civil es único para toda España. 2. El Registro Civil es electrónico."}]},{"text":"Estructura: Oficina Central, Oficinas Generales (una por capital de partido judicial) y Oficinas Consulares (a cargo de los Cónsules) (arts. 20, 22 y 23 LRC).","refs":[{"ref":"Art. 22.1","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"en todas las poblaciones que sean sede de la capital de un partido judicial."}]},{"text":"Asientos: inscripciones, anotaciones y cancelaciones; la inscripción es prueba plena (arts. 17 y 38 LRC).","refs":[{"ref":"Art. 17.1","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"constituye prueba plena de los hechos inscritos."}]},{"text":"Plazos de práctica: cinco días en general; la defunción, el mismo día (art. 33.1 LRC).","refs":[{"ref":"Art. 33.1","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"se practicará en el mismo día de la presentación de la documentación."}]},{"text":"Nacimiento: el hospital comunica en setenta y dos horas; fuera de centro sanitario, diez días para declararlo (arts. 46 y 47 LRC).","refs":[{"ref":"Art. 47.1","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"dispondrán de un plazo de diez días para declarar el nacimiento"}]},{"text":"Desacuerdo sobre el orden de apellidos: tres días; sexo en blanco por intersexualidad: un año como máximo (art. 49 LRC).","refs":[{"ref":"Art. 49.2","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"en el plazo máximo de tres días comuniquen el orden de apellidos."}]},{"text":"Separación, nulidad o divorcio: el LAJ remite la resolución firme en el mismo día o el siguiente hábil (art. 61 LRC).","refs":[{"ref":"Art. 61","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"en el mismo día o al siguiente hábil"}]},{"text":"Nacionalidad por residencia, carta de naturaleza u opción: inscripción constitutiva; pérdida: declarativa (art. 68.1 LRC).","refs":[{"ref":"Art. 68.1","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"Estas inscripciones tendrán carácter constitutivo."}]},{"text":"Certificación en extracto salvo que se pida literal; negativa si no hay asiento (art. 82.1 LRC).","refs":[{"ref":"Art. 82.1","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"Salvo solicitud expresa en sentido contrario, se expedirá certificación en extracto."}]},{"text":"Recurso ante la Dirección General: un mes; resolución en seis meses; silencio desestimatorio. Expedientes: silencio negativo (arts. 85, 86 y 88 LRC).","refs":[{"ref":"Art. 85.1","law":"Ley 20/2011","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628","quote":"en el plazo de un mes."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628', null, null, null, null
  from public.topics t where t.slug = 'jus-25-registro-civil'
